1	#!/usr/bin/env node
2	/**
3	 * harness-cli — single TS entrypoint for Claude Code / Codex shell wrappers
4	 * and the manual `pi` test path. The Pi extension calls store.ts in-process
5	 * (deliverable 5) and skips this CLI.
6	 *
7	 * Reads stdin JSON, normalises per-harness payloads into one shape, and
8	 * dispatches the right side-effect:
9	 *
10	 *   SessionStart     -> stdout = profile + project markdown (≤24kB / ≤8 files)
11	 *                       Promise.race(150ms); on timeout: appendEvent
12	 *                       MemoryInjectionTimeout, no stdout, exit 0.
13	 *   UserPromptSubmit -> stdout = top-5 search hits via `bm tool search-notes
14	 *                       --hybrid` (≤10kB), timeout-bounded; on timeout:
15	 *                       MemoryInjectionTimeout, no stdout, exit 0.
16	 *   PreToolUse       -> appendEvent only.
17	 *   PostToolUse      -> appendEvent only.
18	 *   Stop             -> appendEvent + write dream-pending marker if cadence
19	 *                       threshold met. Never invokes the dream itself.
20	 *
21	 * Hard rule: ≤200ms wall budget end-to-end. Hooks must NEVER block the
22	 * harness. Exit 0 on success, 0 on timeout-skip (logged event), non-zero
23	 * only on programmer error (bad CLI flags, malformed stdin JSON).
24	 */
25	
26	import { readFile, writeFile, readdir, mkdir, stat } from "node:fs/promises";
27	import { existsSync } from "node:fs";
28	import { join } from "node:path";
29	
30	import {
31		appendEvent,
32		eventsDir,
33		eventsRoot,
34		inboxSizeBytes,
35		INBOX_MAX_BYTES,
36		loadProjectContext,
37		readInbox,
38		resolveProjectSlug,
39		searchInbox,
40		searchMemory,
41		type EventType,
42		type InboxEntry,
43		type SearchHit,
44	} from "./store.ts";
45	import { isQmdUnhealthyError } from "./qmd-health.ts";
46	// Lazy-load telemetry to avoid pulling opik → ai-sdk → js-tiktoken at boot.
47	let _hcTelModule: Promise<typeof import("./telemetry.ts")> | null = null;
48	function getHCTel() {
49		if (!_hcTelModule) _hcTelModule = import("./telemetry.ts");
50		return _hcTelModule;
51	}
52	
53	// ---------------------------------------------------------------------------
54	// Budgets (locked by GOAL CONSTRAINTS).
55	
56	export const SESSION_START_INJECTION_MS = 150;
57	export const SESSION_START_MAX_BYTES = 24 * 1024;
58	export const SESSION_START_MAX_FILES = 8;
59	/** Max inbox entries surfaced per UserPromptSubmit turn. */
60	export const USER_PROMPT_INBOX_TOP_N = 3;
61	/** Max bytes of inbox content injected per UserPromptSubmit turn. */
62	export const USER_PROMPT_INBOX_MAX_BYTES = 4 * 1024;
63	
64	export const USER_PROMPT_SEARCH_MS = 8000; // upper search budget (qmd query + LLM expansion can take 1-6s)
65	export const USER_PROMPT_MAX_BYTES = 10 * 1024;
66	export const USER_PROMPT_TOP_N = 5;
67	
68	export const TOTAL_WALL_BUDGET_MS = 200;
69	
70	// Dream cadence (locked):
71	//   min(events_since_watermark >= 50, inbox_size >= 64kB, 4h elapsed, manual)
72	//   force after 24h with non-zero events.
73	// The inbox-size trigger (D7) makes the inbox self-draining: heavy
74	// note-taking forces consolidation before the spill threshold so notes.md
75	// stays small + responsive.
76	export const DREAM_EVENTS_THRESHOLD = 50;
77	export const DREAM_INBOX_BYTES_THRESHOLD = INBOX_MAX_BYTES;
78	
79	function userPromptQmdSearchOptions(): Parameters<typeof searchMemory>[1] {
80		const qmdMode = process.env.RECALL_QMD_MODE === "search" ? "search" : "query";
81		const httpPort = process.env.DREAM_QMD_HTTP_PORT
82			? Number(process.env.DREAM_QMD_HTTP_PORT)
83			: 8181;
84		const candidateLimit = process.env.RECALL_CANDIDATE_LIMIT
85			? Number(process.env.RECALL_CANDIDATE_LIMIT)
86			: 80;
87		return {
88			pageSize: USER_PROMPT_TOP_N,
89			timeoutMs: USER_PROMPT_SEARCH_MS,
90			qmdMode,
91			candidateLimit,
92			...(httpPort > 0 ? { httpPort } : {}),
93		};
94	}
95	
96	// ---------------------------------------------------------------------------
97	// CLI flag parsing — minimal, no extra deps.
98	
99	export type Client = "pi" | "claude" | "codex";
100	
101	function parseArgs(argv: string[]): { client: Client; positional: string[] } {
102		let client: Client = "claude";
103		const positional: string[] = [];
104		for (let i = 0; i < argv.length; i++) {
105			const a = argv[i]!;
106			if (a === "--client") {
107				const next = argv[++i];
108				if (next !== "pi" && next !== "claude" && next !== "codex") {
109					throw new Error(`--client must be one of pi|claude|codex, got: ${String(next)}`);
110				}
111				client = next;
112			} else if (a.startsWith("--client=")) {
113				const val = a.slice("--client=".length);
114				if (val !== "pi" && val !== "claude" && val !== "codex") {
115					throw new Error(`--client must be one of pi|claude|codex, got: ${val}`);
116				}
117				client = val;
118			} else {
119				positional.push(a);
120			}
121		}
122		return { client, positional };
123	}
124	
125	// ---------------------------------------------------------------------------
126	// Normalisation across {pi, claude, codex} hook payloads.
127	
128	export type NormalisedHook = {
129		client: Client;
130		sessionId: string;
131		cwd: string;
132		eventType: EventType;
133		payload: Record<string, unknown>;
134	};
135	
136	const CANONICAL_EVENTS: ReadonlySet<EventType> = new Set([
137		"SessionStart",
138		"UserPromptSubmit",
139		"PreToolUse",
140		"PostToolUse",
141		"Stop",
142	]);
143	
144	function pascal(s: string): string {
145		return s
146			.split(/[_\-\s]+/)
147			.filter(Boolean)
148			.map((p) => p[0]!.toUpperCase() + p.slice(1))
149			.join("");
150	}
151	
152	function pickEventType(input: Record<string, unknown>): EventType {
153		const candidates = [
154			input.hook_event_name,
155			input.hookEventName,
156			input.event_type,
157			input.eventType,
158			input.event,
159		];
160		for (const c of candidates) {
161			if (typeof c === "string" && c.length > 0) {
162				const p = pascal(c);
163				if (CANONICAL_EVENTS.has(p)) return p;
164				return p; // pass through unknown but well-formed names (logged via appendEvent)
165			}
166		}
167		throw new Error("hook payload missing event type (hook_event_name / event_type)");
168	}
169	
170	function pickFirstString(input: Record<string, unknown>, keys: string[], dflt: string): string {
171		for (const k of keys) {
172			const v = input[k];
173			if (typeof v === "string" && v.length > 0) return v;
174		}
175		return dflt;
176	}
177	
178	export function normalise(client: Client, raw: unknown): NormalisedHook {
179		if (!raw || typeof raw !== "object") {
180			throw new Error("hook payload must be a JSON object");
181		}
182		const input = raw as Record<string, unknown>;
183		const eventType = pickEventType(input);
184		const sessionId = pickFirstString(input, ["session_id", "sessionId"], "unknown-session");
185		const cwd = pickFirstString(input, ["cwd", "workspace_dir", "workspaceDir"], process.cwd());
186	
187		// Strip meta fields from the payload echo (keep them in event header).
188		const META = new Set([
189			"hook_event_name",
190			"hookEventName",
191			"event_type",
192			"eventType",
193			"event",
194			"session_id",
195			"sessionId",
196			"cwd",
197			"workspace_dir",
198			"workspaceDir",
199			"transcript_path",
200			"transcriptPath",
201		]);
202		const payload: Record<string, unknown> = {};
203		for (const [k, v] of Object.entries(input)) {
204			if (!META.has(k)) payload[k] = v;
205		}
206		return { client, sessionId, cwd, eventType, payload };
207	}
208	
209	// ---------------------------------------------------------------------------
210	// Time-bounded helpers.
211	
212	export class TimeoutError extends Error {
213		constructor(public readonly ms: number, public readonly where: string) {
214			super(`${where} exceeded ${ms}ms`);
215			this.name = "TimeoutError";
216		}
217	}
218	
219	export function withTimeout<T>(promise: Promise<T>, ms: number, where: string): Promise<T> {
220		return new Promise<T>((resolveP, rejectP) => {
221			const timer = setTimeout(() => rejectP(new TimeoutError(ms, where)), ms);
222			promise.then(
223				(v) => {
224					clearTimeout(timer);
225					resolveP(v);
226				},
227				(err) => {
228					clearTimeout(timer);
229					rejectP(err);
230				},
231			);
232		});
233	}
234	
235	// ---------------------------------------------------------------------------
236	// Stdin reader — bounded; refuses huge payloads.
237	
238	const MAX_STDIN_BYTES = 1024 * 1024; // 1MB
239	
240	async function readStdin(): Promise<string> {
241		if (process.stdin.isTTY) return "";
242		const chunks: Buffer[] = [];
243		let total = 0;
244		for await (const chunk of process.stdin) {
245			const buf = typeof chunk === "string" ? Buffer.from(chunk) : (chunk as Buffer);
246			total += buf.length;
247			if (total > MAX_STDIN_BYTES) {
248				throw new Error(`stdin payload exceeded ${MAX_STDIN_BYTES} bytes`);
249			}
250			chunks.push(buf);
251		}
252		return Buffer.concat(chunks).toString("utf8");
253	}
254	
255	// ---------------------------------------------------------------------------
256	// Cadence — Stop-handler dream enqueue.
257	
258	export async function eventsSinceFor(
259		sessionId: string,
260		sinceEventId?: string,
261		opts: { excludeEventTypes?: Set<string> } = {},
262	): Promise<number> {
263		const file = join(eventsDir(), `${sessionId}.jsonl`);
264		if (!existsSync(file)) return 0;
265		const text = await readFile(file, "utf8");
266		let n = 0;
267		for (const line of text.split("\n")) {
268			if (!line) continue;
269			try {
270				const e = JSON.parse(line) as { event_id?: string; event_type?: string };
271				if (opts.excludeEventTypes && e.event_type && opts.excludeEventTypes.has(e.event_type)) continue;
272				if (sinceEventId) {
273					if (e.event_id && e.event_id > sinceEventId) n += 1;
274				} else {
275					n += 1;
276				}
277			} catch {
278				// torn write
279			}
280		}
281		return n;
282	}
283	
284	async function maybeEnqueueDream(sessionId: string): Promise<boolean> {
285		// Write dream-pending whenever >=1 meaningful new event exists since the
286		// watermark for this session. "Stop" events are excluded — they are session
287		// housekeeping, not durable work. Time/session gates live in runner.ts.
288		const { readWatermark } = await import("./store.ts");
289		const wm = await readWatermark();
290		const sinceEventId = wm[sessionId];
291		const count = await eventsSinceFor(sessionId, sinceEventId, { excludeEventTypes: new Set(["Stop"]) });
292		const inboxBytes = await inboxSizeBytes();
293		const eventsTrigger = count >= 1;
294		const inboxTrigger = inboxBytes >= DREAM_INBOX_BYTES_THRESHOLD;
295		if (!eventsTrigger && !inboxTrigger) return false;
296		const marker = join(eventsRoot(), "dream-pending");
297		await mkdir(eventsRoot(), { recursive: true });
298		await writeFile(
299			marker,
300			JSON.stringify({
301				at: new Date().toISOString(),
302				sessionId,
303				count,
304				inbox_bytes: inboxBytes,
305				reason: eventsTrigger
306					? (inboxTrigger ? "events+inbox" : "events")
307					: "inbox",
308			}) + "\n",
309		);
310		return true;
311	}
312	
313	// ---------------------------------------------------------------------------
314	// Per-event dispatch.
315	
316	export type DispatchResult = {
317		stdout: string;
318		timedOut: boolean;
319		enqueuedDream?: boolean;
320		recall?: {
321			bytes: number;
322			latency_ms?: number;
323			qmd?: {
324				state: "ok" | "timeout" | "unhealthy" | "error" | "skipped";
325				hits: number;
326				permalinks: string[];
327			};
328			inbox_hits?: number;
329			inbox_preview?: string[];
330		};
331	};
332	
333	export async function dispatchSessionStart(hook: NormalisedHook): Promise<DispatchResult> {
334		const slug = await resolveProjectSlug(hook.cwd);
335		const started = Date.now();
336		// CACHE CRITICAL: this dispatcher returns only the per-cwd persistent
337		// memory — project/<slug>/MEMORY.md. The stable, global profile/** snapshot
338		// is injected separately via the extension's systemPrompt:build filter so it
339		// joins the cross-cwd cacheable base instead of the per-cwd tail. Never
340		// inject inbox/raw capture here: it carries event ids and timestamps that
341		// change between sessions.
342		//
343		// DETERMINISM (no timeout): loadProjectContext is a single local readFile
344		// (readIndexFile → MEMORY.md) — no subprocess, no network, sub-millisecond.
345		// The old wall-clock race made the first-turn bytes nondeterministic (a fast
346		// session got the full file, a cold one timed out to ""), bursting the
347		// cross-session prompt cache for this cwd. Claude Code loads CLAUDE.md the
348		// same way — a plain file read. Regression: test/session-start.test.ts.
349		const { content, files } = await loadProjectContext(slug, {
350			maxBytes: SESSION_START_MAX_BYTES,
351			maxFiles: SESSION_START_MAX_FILES,
352		});
353		const bytes = Buffer.byteLength(content, "utf8");
354		void appendEvent({
355			sessionId: hook.sessionId,
356			client: hook.client,
357			cwd: hook.cwd,
358			projectSlug: slug,
359			eventType: "RecallInjected",
360			payload: {
361				where: "SessionStart",
362				bytes,
363				latency_ms: Date.now() - started,
364				files: files.length,
365				qmd: { state: "skipped", hits: 0, permalinks: [] },
366			},
367		});
368		void getHCTel().then(({ withSpan }) => withSpan("dispatch.sessionStart", {
369			bytes_returned: bytes,
370			files_returned: files.length,
371		}, async () => {}));
372		return { stdout: content, timedOut: false };
373	}
374	
375	export async function dispatchUserPromptSubmit(hook: NormalisedHook): Promise<DispatchResult> {
376		const slug = await resolveProjectSlug(hook.cwd);
377		const query = typeof hook.payload.prompt === "string" ? hook.payload.prompt : "";
378	
379		// P3-ISSUE-1 fix: persist the prompt itself before doing recall, so the
380		// dream consolidation phase can see what the user actually asked. Previous
381		// behaviour appended only MemoryInjectionTimeout / nothing, which made
382		// `dream events tail` blind to user intent inside Pi sessions.
383		// Fire-and-forget — we never want event-log latency to block the agent
384		// loop, and the redaction layer + payload_hash live in appendEvent itself.
385		void appendEvent({
386			sessionId: hook.sessionId,
387			client: hook.client,
388			cwd: hook.cwd,
389			projectSlug: slug,
390			eventType: "UserPromptSubmit",
391			payload: { prompt: query, ...(hook.payload.first_turn ? { first_turn: true } : {}) },
392		});
393	
394		if (!query.trim()) return { stdout: "", timedOut: false };
395		try {
396			const started = Date.now();
397			// Two recall sources in parallel under the SAME budget:
398			//   - qmd (canonical wiki, vector + BM25)
399			//   - inbox (raw same-session capture; no qmd dependency — fixes
400			//     the latency cliff that motivated this whole change)
401			// Either, both, or none may produce hits. We never let one tool's
402			// failure or absence suppress the other.
403			const [qmd, inboxEntries] = await withTimeout(
404				Promise.all([
405					searchMemory(query, userPromptQmdSearchOptions()),
406					readInbox().then((all) => searchInbox(all, query, USER_PROMPT_INBOX_TOP_N))
407						.catch(() => [] as InboxEntry[]),
408				]),
409				USER_PROMPT_SEARCH_MS + 50,
410				"UserPromptSubmit search",
411			);
412			const latency_ms = Date.now() - started;
413			const anyTimedOut = qmd.timedOut;
414			const qmdShortCircuit = isQmdUnhealthyError(qmd.error);
415			if (anyTimedOut && !qmdShortCircuit) {
416				void appendEvent({
417					sessionId: hook.sessionId,
418					client: hook.client,
419					cwd: hook.cwd,
420					projectSlug: slug,
421					eventType: "MemoryInjectionTimeout",
422					payload: {
423						where: "UserPromptSubmit",
424						budget_ms: USER_PROMPT_SEARCH_MS,
425						qmd_timed_out: qmd.timedOut,
426					},
427				});
428			}
429			// Render inbox first (raw, freshest) then ranked merged hits below.
430			const inboxBlock = renderInboxBlock(inboxEntries, USER_PROMPT_INBOX_MAX_BYTES);
431			const inboxBytes = Buffer.byteLength(inboxBlock, "utf8");
432			const remainingBytes = Math.max(0, USER_PROMPT_MAX_BYTES - inboxBytes - (inboxBlock ? 2 : 0));
433			const rankedStdout = mergeRecallBlocks(
434				[{ heading: "qmd notes", hits: qmd.results.slice(0, USER_PROMPT_TOP_N) }],
435				remainingBytes,
436			);
437			const stdout = [inboxBlock, rankedStdout].filter(Boolean).join("\n\n");
438			const recall = stdout
439				? {
440						bytes: Buffer.byteLength(stdout, "utf8"),
441						latency_ms,
442						qmd: {
443							state: qmd.timedOut ? "timeout" as const : qmdShortCircuit ? "unhealthy" as const : qmd.error ? "error" as const : "ok" as const,
444							hits: qmd.results.length,
445							permalinks: qmd.results.slice(0, USER_PROMPT_TOP_N).map((h) => h.permalink),
446						},
447						inbox_hits: inboxEntries.length,
448						inbox_preview: inboxEntries.slice(0, USER_PROMPT_INBOX_TOP_N).map((e) => previewText(e.text)),
449					}
450				: undefined;
451			// Fire-and-forget RecallInjected — records what was actually injected
452			// so `dream recall watch` and `dream recall last` have real data.
453			if (stdout && recall) {
454				void appendEvent({
455					sessionId: hook.sessionId,
456					client: hook.client,
457					cwd: hook.cwd,
458					projectSlug: slug,
459					eventType: "RecallInjected",
460					payload: {
461						where: "UserPromptSubmit",
462						...recall,
463					},
464				});
465			}
466	
467			// Telemetry: counters always recorded (D5), span at 10% head-sampling.
468			void getHCTel().then(({ recordCounter, recordHistogram, withSpan }) => {
469				recordCounter("dream_memory.recall.hits", qmd.results.length, { source: "qmd" });
470				recordCounter("dream_memory.recall.hits", inboxEntries.length, { source: "inbox" });
471				recordHistogram("dream_memory.recall.latency_ms", latency_ms, { source: "qmd" });
472				if (Math.random() < 0.1) {
473					void withSpan("dispatch.userPromptSubmit", {
474						prompt_chars: query.length,
475						inbox_hits: inboxEntries.length,
476						qmd_hits: qmd.results.length,
477					}, async () => {});
478				}
479			});
480	
481			return { stdout, timedOut: anyTimedOut, ...(recall ? { recall } : {}) };
482		} catch (err) {
483			if (err instanceof TimeoutError) {
484				void appendEvent({
485					sessionId: hook.sessionId,
486					client: hook.client,
487					cwd: hook.cwd,
488					projectSlug: slug,
489					eventType: "MemoryInjectionTimeout",
490					payload: { where: "UserPromptSubmit", budget_ms: USER_PROMPT_SEARCH_MS },
491				});
492				return { stdout: "", timedOut: true };
493			}
494			throw err;
495		}
496	}
497	
498	/** Collapse whitespace and truncate to a short single-line preview for UI notifications. */
499	export function previewText(text: string, max = 32): string {
500		const flat = text.replace(/\s+/g, " ").trim();
501		return flat.length > max ? `${flat.slice(0, max - 1)}…` : flat;
502	}
503	
504	/**
505	 * Render up to maxBytes of inbox entries as a `## inbox (inbox)` block.
506	 * Newest-first within the input order. Returns "" if no entries fit.
507	 */
508	export function renderInboxBlock(entries: InboxEntry[], maxBytes: number): string {
509		if (entries.length === 0 || maxBytes <= 0) return "";
510		const header = `## inbox (inbox)`;
511		let bytes = Buffer.byteLength(header, "utf8");
512		const parts: string[] = [header];
513		for (const e of entries) {
514			const block = `### ${e.event_id}  · ${e.ts}\n\n${e.text}`;
515			const sep = 2;
516			const sz = Buffer.byteLength(block, "utf8");
517			if (bytes + sep + sz > maxBytes) break;
518			parts.push(block);
519			bytes += sep + sz;
520		}
521		return parts.length > 1 ? parts.join("\n\n") : "";
522	}
523	
524	/**
525	 * Merge ranked hit lists into one `<recalled-memory>`-ready string.
526	 * Round-robin so no source can starve the others if several produce hits;
527	 * each hit gets a `## <heading>` group header the first time it appears.
528	 * Stops as soon as the next block would exceed `maxBytes`.
529	 */
530	export function mergeRecallBlocks(
531		blocks: Array<{ heading: string; hits: SearchHit[] }>,
532		maxBytes: number,
533	): string {
534		const sources = blocks.map((b) => ({ heading: b.heading, hits: b.hits, idx: 0, emitted: false }));
535		const out: string[] = [];
536		let bytes = 0;
537		let remaining = sources.reduce((n, s) => n + s.hits.length, 0);
538		while (remaining > 0) {
539			let progressed = false;
540			for (const s of sources) {
541				if (s.idx >= s.hits.length) continue;
542				const hit = s.hits[s.idx]!;
543				const body = hit.matched_chunk ?? hit.content ?? "";
544				const pieces: string[] = [];
545				if (!s.emitted) pieces.push(`## ${s.heading}`);
546				pieces.push(`### ${hit.permalink}\n\n${body}`);
547				const block = pieces.join("\n\n");
548				const sep = out.length ? 2 : 0;
549				const sz = Buffer.byteLength(block, "utf8");
550				if (bytes + sep + sz > maxBytes) {
551					remaining = 0;
552					break;
553				}
554				out.push(block);
555				bytes += sep + sz;
556				s.idx++;
557				s.emitted = true;
558				remaining--;
559				progressed = true;
560			}
561			if (!progressed) break;
562		}
563		return out.join("\n\n");
564	}
565	
566	export async function dispatchToolEvent(hook: NormalisedHook): Promise<DispatchResult> {
567		const slug = await resolveProjectSlug(hook.cwd);
568		await appendEvent({
569			sessionId: hook.sessionId,
570			client: hook.client,
571			cwd: hook.cwd,
572			projectSlug: slug,
573			eventType: hook.eventType,
574			payload: hook.payload,
575		});
576		return { stdout: "", timedOut: false };
577	}
578	
579	export async function dispatchStop(hook: NormalisedHook): Promise<DispatchResult> {
580		const slug = await resolveProjectSlug(hook.cwd);
581		await appendEvent({
582			sessionId: hook.sessionId,
583			client: hook.client,
584			cwd: hook.cwd,
585			projectSlug: slug,
586			eventType: "Stop",
587			payload: hook.payload,
588		});
589		const enqueued = await maybeEnqueueDream(hook.sessionId);
590		return { stdout: "", timedOut: false, enqueuedDream: enqueued };
591	}
592	
593	// ---------------------------------------------------------------------------
594	// Top-level dispatcher with the 200ms wall budget.
595	
596	export async function dispatch(hook: NormalisedHook): Promise<DispatchResult> {
597		const handler = (() => {
598			switch (hook.eventType) {
599				case "SessionStart":
600					return dispatchSessionStart(hook);
601				case "UserPromptSubmit":
602					return dispatchUserPromptSubmit(hook);
603				case "PreToolUse":
604				case "PostToolUse":
605					return dispatchToolEvent(hook);
606				case "Stop":
607					return dispatchStop(hook);
608				default:
609					return dispatchToolEvent(hook); // unknown → just log
610			}
611		})();
612		try {
613			return await withTimeout(handler, TOTAL_WALL_BUDGET_MS, `${hook.eventType} total`);
614		} catch (err) {
615			if (err instanceof TimeoutError) {
616				// Best-effort breadcrumb. Don't await — we're already over budget.
617				void (async () => {
618					try {
619						const slug = await resolveProjectSlug(hook.cwd);
620						await appendEvent({
621							sessionId: hook.sessionId,
622							client: hook.client,
623							cwd: hook.cwd,
624							projectSlug: slug,
625							eventType: "MemoryInjectionTimeout",
626							payload: { where: hook.eventType, budget_ms: TOTAL_WALL_BUDGET_MS },
627						});
628					} catch {
629						// swallow — we already missed the budget
630					}
631				})();
632				return { stdout: "", timedOut: true };
633			}
634			throw err;
635		}
636	}
637	
638	// ---------------------------------------------------------------------------
639	// main()
640	
641	export async function main(argv = process.argv.slice(2)): Promise<number> {
642		let parsed: ReturnType<typeof parseArgs>;
643		try {
644			parsed = parseArgs(argv);
645		} catch (err) {
646			console.error(`[harness-cli] ${(err as Error).message}`);
647			return 2;
648		}
649		let raw: unknown;
650		try {
651			const text = await readStdin();
652			if (!text.trim()) {
653				console.error("[harness-cli] empty stdin; expected hook JSON payload");
654				return 2;
655			}
656			raw = JSON.parse(text);
657		} catch (err) {
658			console.error(`[harness-cli] bad stdin JSON: ${(err as Error).message}`);
659			return 2;
660		}
661		let hook: NormalisedHook;
662		try {
663			hook = normalise(parsed.client, raw);
664		} catch (err) {
665			console.error(`[harness-cli] normalise failed: ${(err as Error).message}`);
666			return 2;
667		}
668		try {
669			const r = await dispatch(hook);
670			if (r.stdout) process.stdout.write(r.stdout);
671			return 0;
672		} catch (err) {
673			// Programmer error past every guard. Log + non-zero.
674			console.error(`[harness-cli] dispatch crashed: ${(err as Error).stack ?? String(err)}`);
675			return 1;
676		}
677	}
678	
679	const isEntry = (() => {
680		try {
681			const url = new URL(import.meta.url);
682			return url.pathname === process.argv[1] || url.pathname.endsWith(process.argv[1] ?? "");
683		} catch {
684			return false;
685		}
686	})();
687	if (isEntry) {
688		main()
689			.then((code) => process.exit(code))
690			.catch((err) => {
691				console.error(err);
692				process.exit(1);
693			});
694	}
695	
696	// Suppress unused-import lint when imports above are referenced only by types.
697	void readdir;
698	void stat;
699

