2	/**
3	 * Path helpers for the tool-agnostic ~/.agents/ memory root.
4	 *
5	 * Mirrors Claude Code's path resolution from:
6	 *   src/memdir/paths.ts       — getAutoMemPath()
7	 *   src/utils/sessionStoragePortable.ts — sanitizePath()
8	 *
9	 * Claude Code:  ~/.claude/projects/<sanitized-git-root>/memory/
10	 * Ours:         ~/.agents/projects/<sanitized-git-root>/memory/
11	 *
12	 * sanitizePath is identical to Claude Code's implementation. Keep in sync.
13	 */
14	
15	import { homedir } from "node:os";
16	import { join } from "node:path";
17	
18	const MAX_SANITIZED_LENGTH = 200;
19	
20	function simpleHash(s: string): string {
21		let h = 0;
22		for (let i = 0; i < s.length; i++) {
23			h = (Math.imul(31, h) + s.charCodeAt(i)) | 0;
24		}
25		return Math.abs(h).toString(36);
26	}
27	
28	/**
29	 * Replicate Claude Code's sanitizePath — replace every non-alphanumeric
30	 * character with '-', truncating with a hash suffix if over the length cap.
31	 */
32	export function sanitizePath(name: string): string {
33		const sanitized = name.replace(/[^a-zA-Z0-9]/g, "-");
34		if (sanitized.length <= MAX_SANITIZED_LENGTH) return sanitized;
35		const hash = simpleHash(name);
36		return `${sanitized.slice(0, MAX_SANITIZED_LENGTH)}-${hash}`;
37	}
38	
39	/**
40	 * ~/.agents/projects/<sanitized-git-root>/memory/
41	 * The write target for agentic dream mode.
42	 */
43	export function agentsMemoryRoot(gitRoot: string): string {
44		return join(homedir(), ".agents", "projects", sanitizePath(gitRoot), "memory");
45	}
