36	const FRONTMATTER_ORDER = [
37		"source_event_ids",
38		"source_event_ids_truncated_at",
39		"title",
40		"type",
41		"permalink",
42		"scope",
43		"project",
44		"last_dreamed_at",
45		"confidence",
46		"supersedes",
47	];
48	const PROVENANCE_CAP = 200;
49	
50	type ParsedWikiFile = WikiFile & {
51		frontmatter: Record<string, unknown>;
52		body: string;
53	};
54	
55	type PlannedPatch = {
56		patch: DreamPatch;
57		path: string;
58		existing?: ParsedWikiFile;
59	};
