138	function applyOne(existing: ParsedWikiFile | undefined, patch: DreamPatch, path: string): { content: string; action: PatchAuditEntry["action"]; detail?: string } {
139		if (patch.op === "replace_file") {
140			const frontmatter = mergeProvenance({ ...patch.frontmatter }, patch.source_event_ids);
141			const content = serialise(frontmatter, patch.markdown);
142			if (existing?.content === content) return { content, action: "noop" };
143			return { content, action: existing ? "replaced_file" : "created_file" };
144		}
145	
146		const existingFile = existing!;
147		const frontmatter = mergeSectionFrontmatter(existingFile.frontmatter, patch);
148		if (patch.op === "upsert_section") {
149			const body = upsertSection(existingFile.body, patch.heading, patch.content);
150			const content = serialise(frontmatter, body);
151			return { content, action: content === existingFile.content ? "noop" : "upserted_section" };
152		}
153	
154		const { body, appended } = appendToSection(existingFile.body, patch.heading, patch.content, patch.dedupe);
155		const content = serialise(frontmatter, body);
156		return { content, action: appended === 0 && content === existingFile.content ? "noop" : "appended_blocks", detail: `${appended} block(s)` };
157	}
158	
159	function mergeSectionFrontmatter(existing: Record<string, unknown>, patch: Extract<DreamPatch, { op: "upsert_section" | "append_to_section" }>): Record<string, unknown> {
160		const allowed = new Set(["title", "type", "last_dreamed_at", "confidence", "supersedes"]);
161		const next: Record<string, unknown> = { ...existing };
162		if (patch.op === "upsert_section" && patch.frontmatter) {
163			for (const [key, value] of Object.entries(patch.frontmatter)) {
164				if (value !== undefined && allowed.has(key)) next[key] = value;
165			}
166		}
167		return mergeProvenance(next, patch.source_event_ids);
168	}
