170	function mergeProvenance(frontmatter: Record<string, unknown>, ids: string[]): Record<string, unknown> {
171		const existing = Array.isArray(frontmatter.source_event_ids) ? frontmatter.source_event_ids.filter((id): id is string => typeof id === "string") : [];
172		const union = [...existing];
173		for (const id of ids) if (!union.includes(id)) union.push(id);
174		if (union.length > PROVENANCE_CAP) {
175			const retained = union.slice(-PROVENANCE_CAP);
176			frontmatter.source_event_ids = retained;
177			frontmatter.source_event_ids_truncated_at = retained[0];
178		} else {
179			frontmatter.source_event_ids = union;
180		}
181		return frontmatter;
182	}
183	
184	function parseWikiFile(file: WikiFile): ParsedWikiFile {
185		const match = /^---\n([\s\S]*?)\n---\n?([\s\S]*)$/.exec(file.content);
186		if (!match) return { ...file, frontmatter: {}, body: file.content.replace(/\s*$/, "") };
187		const [, frontmatterText = "", bodyText = ""] = match;
188		return { ...file, frontmatter: parseYamlish(frontmatterText), body: bodyText.replace(/\s*$/, "") };
189	}
