/**
 * dream-memory active-recall — collection routing.
 *
 * Decides which qmd collections a recall pass queries (memory vs
 * workspace-index vs project-docs) and builds anchored sub-queries.
 * Extracted from active-memory.ts (009). Pure: env + heuristics, no IO.
 */

import { HARNESS_IDS, type HarnessId } from "../canonical/paths.ts";

/**
 * Active-recall collections: pi-memory (live MEMORY.md, daily logs),
 * scars (durable failure patterns), and changes (dated history of
 * agent-scripts changes). Federating across all three on every prompt
 * gives the haiku-curator full context without forcing the user to
 * remember which kind of note they wrote.
 *
 * NOT included: `dream-memory-profile` and `dream-memory-project`. Those are
 * already injected deterministically every session — profile/** via the
 * systemPrompt:build base filter, project/<slug>/** via the SessionStart tail.
 * Recalling them here double-bills the same tokens and (because recall hits
 * land in the volatile region) hurts cross-session cache. Recall should surface
 * memory that is NOT otherwise in the prompt.
 */
export const DEFAULT_ACTIVE_RECALL_COLLECTIONS: readonly string[] = [
	"pi-memory",
	"scars",
	"changes",
] as const;

/** @deprecated single-collection accessor; use {@link activeRecallCollections}. */
export const DEFAULT_ACTIVE_RECALL_COLLECTION: string = DEFAULT_ACTIVE_RECALL_COLLECTIONS[0] ?? "pi-memory";

// ---------------------------------------------------------------------------
// Canonical collections + dual-read shim (P1). Recognised here BEFORE the qmd
// cutover (H3) so routing is ready when the canonical corpus lands (P2). The
// dual-read path is **default-OFF** — flipping it on is the cutover lever (P7).
// Default-off keeps daily-driver routing byte-identical, so P1 cannot churn the
// prompt-prefix cache (ADR 0008).

/** qmd collection-name prefix for the canonical store. */
export const CANONICAL_COLLECTION_PREFIX = "canonical";

/** Legacy collections still queried during the dual-read transition. */
export const LEGACY_RECALL_COLLECTIONS: readonly string[] = [
	"pi-memory",
	"dream-memory-profile",
	"dream-memory-project",
	"scars",
	"changes",
] as const;

/** Canonical qmd collections: `canonical-shared`, `canonical-harness-<id>` per
 * harness, `canonical-episodic`. Stable, alias-free names (one harness-ID enum). */
export function canonicalCollections(harnesses: readonly HarnessId[] = HARNESS_IDS): string[] {
	return [
		`${CANONICAL_COLLECTION_PREFIX}-shared`,
		...harnesses.map((h) => `${CANONICAL_COLLECTION_PREFIX}-harness-${h}`),
		`${CANONICAL_COLLECTION_PREFIX}-episodic`,
	];
}

/** Is canonical (dual-read) recall enabled? Default OFF. */
export function canonicalRecallEnabled(): boolean {
	return process.env.DREAM_CANONICAL_RECALL === "1" || process.env.DREAM_CANONICAL_RECALL === "true";
}

/** Dual-read collection list: the supplied base ∪ canonical collections, but
 * only when {@link canonicalRecallEnabled}. Returns the base unchanged otherwise
 * (the no-op path daily-driver sessions take). */
export function dualReadCollections(base: readonly string[]): string[] {
	if (!canonicalRecallEnabled()) return [...base];
	const out = [...base];
	for (const c of canonicalCollections()) if (!out.includes(c)) out.push(c);
	return out;
}

/** Minimal hit shape for tail-only dual-read dedup — structural, so it never
 * needs to import the heavy SearchHit type. */
export type DualReadHit = { source_id?: string; permalink?: string; title?: string; file_path?: string };

/** Stable identity for dedup across legacy + canonical reads: prefer an exact
 * source id, then permalink, then a title∕path composite. (Exact-ID/permalink
 * match only — never embedding similarity; ADR 0007 D5.) */
export function dualReadKey(hit: DualReadHit): string {
	return hit.source_id ?? hit.permalink ?? `${hit.title ?? ""}�${hit.file_path ?? ""}`;
}

/** Suppress duplicates across dual-read results, keeping the first occurrence.
 * Callers order canonical-vs-legacy by preference before calling. TAIL-ONLY —
 * this runs on volatile recall hits, never on cached-core bytes. */
export function dedupeDualRead<T extends DualReadHit>(hits: readonly T[]): T[] {
	const seen = new Set<string>();
	const out: T[] = [];
	for (const h of hits) {
		const k = dualReadKey(h);
		if (seen.has(k)) continue;
		seen.add(k);
		out.push(h);
	}
	return out;
}

/**
 * Resolve the collection list for active recall.
 *
 * Override priority:
 *   1. `DREAM_ACTIVE_RECALL_COLLECTIONS` (comma-separated list, plural)
 *   2. `DREAM_ACTIVE_RECALL_COLLECTION` (single, back-compat)
 *   3. `PI_MEMORY_QMD_COLLECTION` (legacy, single)
 *   4. {@link DEFAULT_ACTIVE_RECALL_COLLECTIONS}
 */
/**
 * Generic multi-topic decomposition for two-pass retrieval. Splits the prompt
 * on conjunctions (" and ", " plus ", " & ", "/") when the prompt has ≥6
 * words and ≥2 sub-parts of ≥2 words each. Returns the sub-parts to be used
 * as additional QMD sub-queries (excluding the full query, which the caller
 * still issues). Returns [] for single-topic prompts.
 *
 * Heuristic only — never overfits to specific test cases.
 */
export function decomposeMultiTopic(prompt: string): string[] {
	const trimmed = prompt.trim();
	if (trimmed.split(/\s+/).length < 6) return [];
	const parts = trimmed
		.split(/\s+and\s+|\s+plus\s+|\s+&\s+|\s*\/\s*|\s*,\s*/i)
		.map((p) => p.replace(/[?.!]+$/, "").trim())
		.filter((p) => p.split(/\s+/).length >= 2);
	if (parts.length < 2) return [];
	return parts.slice(0, 4);
}

/**
 * Build anchored follow-up queries for QMD. Smoke prompts and user asks often
 * contain policy prose plus exact file/repo tokens; BM25 can miss the useful
 * docs when everything is searched as one long sentence. Keep the full query,
 * then add short evidence-shaped anchors.
 */
export function buildActiveRecallExtraQueries(prompt: string): string[] {
	const queries: string[] = [];
	const add = (q: string | undefined) => {
		const cleaned = q?.replace(/\s+/g, " ").replace(/[?.!]+$/, "").trim();
		if (!cleaned || cleaned.length < 3) return;
		if (cleaned === prompt.trim()) return;
		if (!queries.includes(cleaned)) queries.push(cleaned);
	};

	const question = /\bQuestion:\s*([\s\S]*?)(?:\n\s*\n|\bExpected\b|\bAnswer\b|$)/i.exec(prompt)?.[1];
	const corePrompt = question ?? prompt;
	add(question);
	add(corePrompt
		.replace(/\b(where|which|what|find|locate|path|repo|repository|project|workspace|checkout|source|stored|local|the|is|are|do|does|can|you|please)\b/gi, " ")
		.replace(/\bsrc\b/gi, "src source")
	);
	for (const q of decomposeMultiTopic(corePrompt)) add(q);

	for (const m of prompt.matchAll(/`([^`]+)`/g)) add(m[1]);
	for (const m of prompt.matchAll(/(?:^|\s)((?:[\w.-]+\/)+[\w.-]+\.md)\b/g)) add(m[1]);
	for (const m of prompt.matchAll(/\b[a-z0-9]+(?:-[a-z0-9]+){2,}\b/gi)) add(m[0]);

	return queries.slice(0, 12);
}

export function activeRecallCollections(): string[] {
	const plural = process.env.DREAM_ACTIVE_RECALL_COLLECTIONS;
	if (plural) {
		const list = plural.split(",").map((s) => s.trim()).filter(Boolean);
		if (list.length > 0) return list;
	}
	const single =
		process.env.DREAM_ACTIVE_RECALL_COLLECTION ??
		process.env.PI_MEMORY_QMD_COLLECTION;
	if (single) return [single];
	return [...DEFAULT_ACTIVE_RECALL_COLLECTIONS];
}

export type RecallCollectionRoute = {
	collections: string[];
	/** Collections that should be guaranteed representation before global memory hits. */
	primaryCollections?: string[];
	/** Global memory collections appended after primary project/workspace hits. */
	globalCollections?: string[];
	/** Force BM25-only QMD for collections not covered by the vector sidecar. */
	qmdMode?: "search" | "query";
	reason: "explicit-env" | "workspace" | "project-docs" | "default-memory";
};

function hasExplicitRecallCollectionsEnv(): boolean {
	return Boolean(process.env.DREAM_ACTIVE_RECALL_COLLECTIONS || process.env.DREAM_ACTIVE_RECALL_COLLECTION || process.env.PI_MEMORY_QMD_COLLECTION);
}

function looksLikeWorkspaceLookup(prompt: string): boolean {
	return /\b(where|which|what|find|locate|path|repo|repository|project|workspace|checkout|source|src|directory|folder)\b/i.test(prompt);
}

function looksLikeProjectDocsLookup(prompt: string): boolean {
	return /\b(doc|docs|documentation|research|spec|prd|plan|proposal|design|runbook|architecture|decision|adr|notes?)\b/i.test(prompt);
}

function projectDocsCollectionForSlug(slug: string | undefined): string | undefined {
	if (!slug || slug === "unknown") return undefined;
	return `project-docs-${slug}`;
}

export function resolveActiveRecallRoute(prompt: string, projectSlug?: string): RecallCollectionRoute {
	if (hasExplicitRecallCollectionsEnv()) {
		return { collections: activeRecallCollections(), reason: "explicit-env" };
	}
	const projectDocs = projectDocsCollectionForSlug(projectSlug);
	const globalMemory = activeRecallCollections();
	if (looksLikeWorkspaceLookup(prompt)) {
		const primaryCollections = ["workspace-index", "workspace-info", ...(projectDocs ? [projectDocs] : [])];
		return {
			collections: [...primaryCollections, ...globalMemory],
			primaryCollections,
			globalCollections: globalMemory,
			qmdMode: "search",
			reason: "workspace",
		};
	}
	if (projectDocs && looksLikeProjectDocsLookup(prompt)) {
		const primaryCollections = [projectDocs];
		return {
			collections: [...primaryCollections, ...globalMemory],
			primaryCollections,
			globalCollections: globalMemory,
			qmdMode: "search",
			reason: "project-docs",
		};
	}
	return { collections: activeRecallCollections(), reason: "default-memory" };
}

/** @deprecated returns only the first collection; use {@link activeRecallCollections}. */
export function activeRecallCollection(): string {
	return activeRecallCollections()[0] ?? DEFAULT_ACTIVE_RECALL_COLLECTION;
}

/**
 * Canonical store skeleton — create the namespaced directory tree.
 *
 * Idempotent: `mkdir -p` semantics, safe to call on every boot. Creating an
 * empty skeleton is harmless and touches no live recall/injection path, so it
 * cannot churn the prompt-prefix cache (ADR 0008).
 */

import { mkdir } from "node:fs/promises";

import { canonicalDirs, canonicalGlobalRoot, canonicalProjectRoot } from "./paths.ts";

/** Ensure every namespaced subdir exists under one root. Returns the dirs created/ensured. */
export async function ensureCanonicalSkeleton(root: string): Promise<string[]> {
	const dirs = canonicalDirs(root);
	for (const dir of dirs) {
		await mkdir(dir, { recursive: true });
	}
	return dirs;
}

/** Ensure the global root skeleton (`~/.agents/memory`). */
export async function ensureGlobalSkeleton(): Promise<string[]> {
	return ensureCanonicalSkeleton(canonicalGlobalRoot());
}

/** Ensure a project root skeleton (`~/.agents/projects/<slug>/memory`). */
export async function ensureProjectSkeleton(gitRoot: string): Promise<string[]> {
	return ensureCanonicalSkeleton(canonicalProjectRoot(gitRoot));
}

/**
 * Canonical record frontmatter — the structured contract every canonical
 * memory file carries (ADR 0007 D7, spec P1). Distinct from the legacy dream
 * wiki `FrontmatterSchema` (`dream/schema.ts`): this is what the P2 migration
 * and P3 harvest pipeline write, and what recall ACL-filters on.
 *
 * `origin ≠ visibility` is enforced structurally — they are separate fields,
 * never inferred from one another. New captures default to origin-private; a
 * classification pass promotes visibility.
 */

import { z } from "zod";

import { HARNESS_IDS } from "./paths.ts";

/** Where a fact was captured, in harness terms (provenance, not a visibility
 * decision). The finer source lives in {@link ProvenanceSchema.source_store}. */
export const OriginSchema = z.enum(HARNESS_IDS);

/** Who may see a fact. `private` = origin-only; templated forms scope to a
 * harness or project; `shared` = cross-harness. Never inferred from origin. */
export const VisibilitySchema = z.string().refine(
	(v) => v === "private" || v === "shared" || /^harness:.+$/.test(v) || /^project:.+$/.test(v),
	"visibility must be 'private' | 'shared' | 'harness:<x>' | 'project:<slug>'",
);

export const SensitivitySchema = z.enum(["public", "private", "secret"]);

/** Functional placement of a fact. `profile` = global/cross-project. */
export const CanonicalScopeSchema = z.string().refine(
	(v) => v === "profile" || /^project:.+$/.test(v) || /^tool:.+$/.test(v) || /^harness:.+$/.test(v),
	"scope must be 'profile' | 'project:<slug>' | 'tool:<name>' | 'harness:<x>'",
);

/** Maturity of a fact. Drives whether it may enter the cached core (P5). */
export const ConfidenceSchema = z.enum(["extracted", "consolidated", "confirmed"]);

export const SourceStoreSchema = z.enum([
	"pi",
	"obsidian",
	"claude-code",
	"codex-memories",
	"chronicle",
]);

export const CaptureMechanismSchema = z.enum(["native", "harvest", "dream", "manual"]);

/** Migration/dedup/audit/rollback provenance (spec M2). Content hash + span +
 * record id let the claim-level ledger map every source claim exactly once. */
export const ProvenanceSchema = z.object({
	source_store: SourceStoreSchema,
	source_path: z.string().min(1),
	source_span: z.string().optional(),
	source_content_hash: z.string().optional(),
	source_record_id: z.string().optional(),
	migration_batch_id: z.string().optional(),
	first_seen: z.string().optional(),
	last_seen: z.string().optional(),
	capture_mechanism: CaptureMechanismSchema,
});
export type Provenance = z.infer<typeof ProvenanceSchema>;

export const CanonicalFrontmatterSchema = z.object({
	title: z.string().min(1),
	permalink: z.string().min(1),
	origin: OriginSchema,
	visibility: VisibilitySchema,
	sensitivity: SensitivitySchema,
	scope: CanonicalScopeSchema,
	confidence: ConfidenceSchema,
	provenance: ProvenanceSchema,
	/** Corrections: permalinks this record supersedes. */
	supersedes: z.array(z.string().min(1)).optional(),
	/** Outbound graph edges (the backlink graph). Permalinks this note links to;
	 * also emitted inline as `[[permalink]]` so Obsidian renders the graph. */
	links: z.array(z.string().min(1)).optional(),
	/** Typed soft relations (looser than `links` — "see also"). */
	relates: z.array(z.string().min(1)).optional(),
});
export type CanonicalFrontmatter = z.infer<typeof CanonicalFrontmatterSchema>;

/** Safe defaults for a freshly captured (un-classified) record: origin-private,
 * lowest confidence, never shared until a classification pass promotes it. */
export function defaultCaptureVisibility(): { visibility: string; sensitivity: z.infer<typeof SensitivitySchema> } {
	return { visibility: "private", sensitivity: "private" };
}

