describe("canonical/skeleton — idempotent dir tree", () => {
	let scratch: string;
	beforeEach(async () => { scratch = await mkdtemp(join(tmpdir(), "canon-skel-")); });
	afterEach(async () => { await rm(scratch, { recursive: true, force: true }); });

	it("creates every namespaced subdir and is safe to re-run", async () => {
		const root = join(scratch, "memory");
		const made = await ensureCanonicalSkeleton(root);
		expect(made).toEqual(canonicalDirs(root));
		for (const dir of made) expect((await stat(dir)).isDirectory()).toBe(true);
		// idempotent
		await expect(ensureCanonicalSkeleton(root)).resolves.toEqual(canonicalDirs(root));
	});
});

// ---------------------------------------------------------------------------

describe("recall-routing — canonical collections + dual-read (default OFF)", () => {
	afterEach(() => { delete process.env.DREAM_CANONICAL_RECALL; });

	it("canonical collection names are stable and alias-free", () => {
		expect(canonicalCollections()).toEqual([
			"canonical-shared",
			"canonical-harness-pi",
			"canonical-harness-claude-code",
			"canonical-harness-codex",
			"canonical-episodic",
		]);
	});

	it("dual-read is OFF by default → base list returned unchanged", () => {
		expect(canonicalRecallEnabled()).toBe(false);
		const base = [...LEGACY_RECALL_COLLECTIONS];
		expect(dualReadCollections(base)).toEqual(base); // no daily-driver churn
	});

	it("dual-read ON → base ∪ canonical, no duplicates", () => {
		process.env.DREAM_CANONICAL_RECALL = "1";
		expect(canonicalRecallEnabled()).toBe(true);
		const merged = dualReadCollections(["pi-memory", "canonical-shared"]);
		expect(merged).toContain("pi-memory");
		expect(merged).toContain("canonical-episodic");
		expect(merged.filter((c) => c === "canonical-shared")).toHaveLength(1); // deduped
	});

	it("dedupes hits by exact source id / permalink, first occurrence wins", () => {
		expect(dualReadKey({ source_id: "evt-1" })).toBe("id:evt-1");
		expect(dualReadKey({ permalink: "shared/style" })).toBe("pl:shared/style");
		const deduped = dedupeDualRead([
			{ permalink: "shared/style", title: "canonical" },
			{ permalink: "shared/style", title: "legacy" },
			{ source_id: "evt-9" },
		]);
		expect(deduped).toHaveLength(2);
		expect(deduped[0]?.title).toBe("canonical"); // caller ordered canonical first
	});

	it("two identity-less hits do NOT collapse to one (no key collision)", () => {
		// Distinct hits with no source_id/permalink must survive — a sparse hit
		// shape must never silently drop real results.
		const deduped = dedupeDualRead([
			{ title: "alpha", file_path: "a.md" },
			{ title: "beta", file_path: "b.md" },
			{}, // wholly empty
			{ title: undefined },
		]);
		// alpha, beta, and one collapsed empty (the two empties share "tp: ")
		expect(deduped).toHaveLength(3);
		// a permalink hit and a same-named title hit must NOT collide
		expect(dualReadKey({ permalink: "x" })).not.toBe(dualReadKey({ title: "x" }));
	});
});

