/**
 * pi-memory extractor (`~/.pi/agent/memory`). Full member of the union.
 * `profile/` + `project/<slug>/` are consolidated facts (whole-file claims);
 * `daily/` + `inbox/` are dated raw logs (→ episodic). The `db/`, `snapshots/`,
 * `state/` subtrees are runtime state, not memory content, so they are outside
 * the scanned set. Frontmatter: flat `name`/`description`/`type`/`originSessionId`.
 */

import { makeClaim, type Claim, type ClaimSourceStore, type ScopeHint, type Skipped, type StoreExtraction } from "../ledger.ts";
import { parseFrontmatter } from "../parse.ts";
import { asString, dateFromFilename, listMarkdownFiles, mtimeIso, readText, scopeFromType } from "./util.ts";

const STORE: ClaimSourceStore = "pi";

export async function extractPi(root: string): Promise<StoreExtraction> {
	const files = await listMarkdownFiles(root, { subdirs: ["profile", "project", "daily", "inbox"] });
	const claims: Claim[] = [];
	const skipped: Skipped[] = [];

	for (const rel of files) {
		const text = await readText(root, rel);
		if (!text.trim()) {
			skipped.push({ source_store: STORE, path: rel, reason: "empty file" });
			continue;
		}
		const { data } = parseFrontmatter(text);
		const parts = rel.split("/");
		const top = parts[0];

		let scope_hint: ScopeHint;
		let project_slug: string | undefined;
		let captured_at: string | undefined;
		if (top === "project") {
			scope_hint = "project";
			project_slug = parts[1];
			captured_at = await mtimeIso(root, rel);
		} else if (top === "daily") {
			scope_hint = "episodic";
			captured_at = dateFromFilename(rel) ?? (await mtimeIso(root, rel));
		} else if (top === "inbox") {
			scope_hint = "inbox";
			captured_at = dateFromFilename(rel) ?? (await mtimeIso(root, rel));
		} else {
			// profile/: honour an explicit type, else treat as profile-scoped.
			const fromType = scopeFromType(data.type);
			scope_hint = fromType === "unknown" ? "profile" : fromType;
			captured_at = await mtimeIso(root, rel);
		}

		claims.push(
			makeClaim({
				source_store: STORE,
				source_path: rel,
				span: { kind: "whole" },
				scope_hint,
				project_slug,
				title: asString(data.name),
				captured_at,
				text,
				origin_meta: Object.keys(data).length ? data : undefined,
			}),
		);
	}
	return { source_store: STORE, root, files_seen: files, claims, skipped };
}

