/**
 * Codex memories extractor (`~/.codex/memories`). Read-only source. No
 * frontmatter — `MEMORY.md` (≈300 KB) and `raw_memories.md` (≈450 KB) are
 * heading-delimited, so each file is chunked into section claims with byte-span
 * fidelity (spans tile the file, gap-free). Most sections are rollout/task
 * episodes (→ episodic); preference/knowledge sections hint profile/reference.
 */

import { makeClaim, type Claim, type ClaimSourceStore, type ScopeHint, type Skipped, type StoreExtraction } from "../ledger.ts";
import { detectMinHeadingLevel, splitSections } from "../parse.ts";
import { asString, listMarkdownFiles, mtimeIso, readText } from "./util.ts";

const STORE: ClaimSourceStore = "codex";

function scopeFromHeading(heading: string | undefined): ScopeHint {
	const h = (heading ?? "").toLowerCase();
	if (h.includes("preference")) return "profile";
	if (h.includes("reusable knowledge") || h.includes("knowledge")) return "reference";
	if (h.includes("failure")) return "reference";
	return "episodic"; // task / rollout / keywords / default
}

export async function extractCodex(root: string): Promise<StoreExtraction> {
	const files = await listMarkdownFiles(root);
	const claims: Claim[] = [];
	const skipped: Skipped[] = [];

	for (const rel of files) {
		const text = await readText(root, rel);
		if (!text.trim()) {
			skipped.push({ source_store: STORE, path: rel, reason: "empty file" });
			continue;
		}
		const captured_at = await mtimeIso(root, rel);
		const level = detectMinHeadingLevel(text) ?? 2;
		const sections = splitSections(text, level);
		let made = 0;
		for (const s of sections) {
			if (!s.text.trim()) continue; // degenerate heading-only / blank slice
			made++;
			claims.push(
				makeClaim({
					source_store: STORE,
					source_path: rel,
					span: { kind: "section", start: s.start, end: s.end, heading: s.heading },
					scope_hint: scopeFromHeading(s.heading),
					title: asString(s.heading) ?? rel.split("/").pop(),
					captured_at,
					text: s.text,
				}),
			);
		}
		if (made === 0) skipped.push({ source_store: STORE, path: rel, reason: "no extractable sections" });
	}
	return { source_store: STORE, root, files_seen: files, claims, skipped };
}

