/**
 * P2 migration dry-run — extract every store into a ledger, prove claim
 * coverage, and write the ledger to a workdir for quarantine review. This is the
 * **read-only** half of the flow (spec P2): it never touches a real store; it
 * only reads sources and writes `manifest.json` + `claims.jsonl` to a caller-
 * supplied (ignored) workdir. Apply (P2c) is a separate, sign-off-gated step.
 */

import { mkdir, writeFile } from "node:fs/promises";
import { join } from "node:path";

import { EXTRACTORS } from "./extract/index.ts";
import {
	LedgerManifestSchema,
	type Claim,
	type ClaimSourceStore,
	type LedgerManifest,
	type Skipped,
	type SourceSummary,
	type StoreExtraction,
} from "./ledger.ts";

export type SourceRoots = Partial<Record<ClaimSourceStore, string>>;

/** Per-store proof that claims ∪ skips tile the scanned set. `unaccounted` must
 * be empty — a non-empty list is a silent drop and fails the gate. */
export type CoverageReport = {
	source_store: ClaimSourceStore;
	files_seen: number;
	claim_files: number;
	skipped: number;
	unaccounted: string[];
};

export type DryRunResult = {
	manifest: LedgerManifest;
	claims: Claim[];
	coverage: CoverageReport[];
	/** True iff every store accounts for every file it saw (the no-drops gate). */
	complete: boolean;
};

/** Run the configured extractors and assemble the ledger. Reads only. */
export async function runDryRun(roots: SourceRoots, opts?: { now?: string }): Promise<DryRunResult> {
	const extractions: StoreExtraction[] = [];
	for (const store of Object.keys(roots) as ClaimSourceStore[]) {
		const root = roots[store];
		if (!root) continue;
		extractions.push(await EXTRACTORS[store](root));
	}
	return assembleLedger(extractions, opts?.now);
}

/** Pure assembly + coverage accounting over already-run extractions. */
export function assembleLedger(extractions: StoreExtraction[], now?: string): DryRunResult {
	const claims: Claim[] = [];
	const coverage: CoverageReport[] = [];
	const sources: SourceSummary[] = [];
	const skippedAll: Skipped[] = [];

	for (const ex of extractions) {
		claims.push(...ex.claims);
		const claimFiles = new Set(ex.claims.map((c) => c.source_path));
		const skipFiles = new Set(ex.skipped.map((s) => s.path));
		const accounted = new Set([...claimFiles, ...skipFiles]);
		const unaccounted = ex.files_seen.filter((f) => !accounted.has(f));
		coverage.push({
			source_store: ex.source_store,
			files_seen: ex.files_seen.length,
			claim_files: claimFiles.size,
			skipped: skipFiles.size,
			unaccounted,
		});
		sources.push({
			source_store: ex.source_store,
			root: ex.root,
			file_count: ex.files_seen.length,
			claim_count: ex.claims.length,
		});
		skippedAll.push(...ex.skipped);
	}

	const manifest = LedgerManifestSchema.parse({
		version: 1,
		generated_at: now ?? new Date().toISOString(),
		sources,
		total_claims: claims.length,
		skipped: skippedAll,
	});
	const complete = coverage.every((c) => c.unaccounted.length === 0);
	return { manifest, claims, coverage, complete };
}

/** Persist the ledger to an (ignored) workdir for review. Writes only here —
 * never into a source or the canonical store. */
export async function writeLedger(workdir: string, result: DryRunResult): Promise<{ manifestPath: string; claimsPath: string }> {
	await mkdir(workdir, { recursive: true });
	const manifestPath = join(workdir, "manifest.json");
	const claimsPath = join(workdir, "claims.jsonl");
	await writeFile(manifestPath, `${JSON.stringify(result.manifest, null, 2)}\n`, "utf8");
	const lines = result.claims.map((c) => JSON.stringify(c)).join("\n");
	await writeFile(claimsPath, lines ? `${lines}\n` : "", "utf8");
	return { manifestPath, claimsPath };
}

