1	/**
2	 * pi-memory extractor (`~/.pi/agent/memory`). Full member of the union.
3	 * `profile/` + `project/<slug>/` are consolidated facts (whole-file claims);
4	 * `daily/` + `inbox/` are dated raw logs (→ episodic). The `db/`, `snapshots/`,
5	 * `state/` subtrees are runtime state, not memory content, so they are outside
6	 * the scanned set. Frontmatter: flat `name`/`description`/`type`/`originSessionId`.
7	 */
8	
9	import { makeClaim, type Claim, type ClaimSourceStore, type ScopeHint, type Skipped, type StoreExtraction } from "../ledger.ts";
10	import { parseFrontmatter } from "../parse.ts";
11	import { asString, dateFromFilename, listMarkdownFiles, mtimeIso, readText, scopeFromType } from "./util.ts";
12	
13	const STORE: ClaimSourceStore = "pi";
14	
15	export async function extractPi(root: string): Promise<StoreExtraction> {
16		const files = await listMarkdownFiles(root, { subdirs: ["profile", "project", "daily", "inbox"] });
17		const claims: Claim[] = [];
18		const skipped: Skipped[] = [];
19	
20		for (const rel of files) {
21			const text = await readText(root, rel);
22			if (!text.trim()) {
23				skipped.push({ source_store: STORE, path: rel, reason: "empty file" });
24				continue;
25			}
26			const { data } = parseFrontmatter(text);
27			const parts = rel.split("/");
28			const top = parts[0];
29	
30			let scope_hint: ScopeHint;
31			let project_slug: string | undefined;
32			let captured_at: string | undefined;
33			if (top === "project") {
34				scope_hint = "project";
35				project_slug = parts[1];
36				captured_at = await mtimeIso(root, rel);
37			} else if (top === "daily") {
38				scope_hint = "episodic";
39				captured_at = dateFromFilename(rel) ?? (await mtimeIso(root, rel));
40			} else if (top === "inbox") {
41				scope_hint = "inbox";
42				captured_at = dateFromFilename(rel) ?? (await mtimeIso(root, rel));
43			} else {
44				// profile/: honour an explicit type, else treat as profile-scoped.
45				const fromType = scopeFromType(data.type);
46				scope_hint = fromType === "unknown" ? "profile" : fromType;
47				captured_at = await mtimeIso(root, rel);
48			}
49	
50			claims.push(
51				makeClaim({
52					source_store: STORE,
53					source_path: rel,
54					span: { kind: "whole" },
55					scope_hint,
56					project_slug,
57					title: asString(data.name),
58					captured_at,
59					text,
60					origin_meta: Object.keys(data).length ? data : undefined,
61				}),
62			);
63		}
64		return { source_store: STORE, root, files_seen: files, claims, skipped };
65	}
66

