import { describe, it } from "vitest";
import { readdir, writeFile } from "node:fs/promises";
import { homedir } from "node:os";
import { join } from "node:path";

import {
	extractClaudeCode,
	extractCodex,
	extractObsidian,
	extractPi,
} from "../src/migration/extract/index.ts";
import { assembleLedger } from "../src/migration/dry-run.ts";
import type { Claim, StoreExtraction } from "../src/migration/ledger.ts";

const HOME = homedir();
const OUT = "/private/tmp/claude-501/-Users-luke-Projects-personal-my-pi/2af496dc-fa07-4164-a184-de979524291f/scratchpad/p2-survey.json";

function dist(claims: Claim[], key: (c: Claim) => string): Record<string, number> {
	const m: Record<string, number> = {};
	for (const c of claims) m[key(c)] = (m[key(c)] ?? 0) + 1;
	return Object.fromEntries(Object.entries(m).sort((a, b) => b[1] - a[1]));
}

describe("P2 corpus survey (read-only)", () => {
	it("surveys the real stores", async () => {
		const extractions: StoreExtraction[] = [];
		extractions.push(await extractPi(join(HOME, ".pi/agent/memory")));
		extractions.push(await extractObsidian(join(HOME, "obsidian/dream-memory/memory")));
		extractions.push(await extractCodex(join(HOME, ".codex/memories")));

		// CC: one root per project; merge into a single synthetic extraction,
		// prefixing source_path with the project slug so paths stay unique.
		const ccBase = join(HOME, ".claude/projects");
		const slugs = (await readdir(ccBase, { withFileTypes: true })).filter((d) => d.isDirectory()).map((d) => d.name);
		const ccClaims: Claim[] = [];
		const ccSkipped: { source_store: "claude-code"; path: string; reason: string }[] = [];
		const ccFiles: string[] = [];
		for (const slug of slugs) {
			const ex = await extractClaudeCode(join(ccBase, slug, "memory"));
			for (const c of ex.claims) ccClaims.push({ ...c, source_path: `${slug}/${c.source_path}` });
			for (const s of ex.skipped) ccSkipped.push({ ...s, path: `${slug}/${s.path}`, source_store: "claude-code" });
			for (const f of ex.files_seen) ccFiles.push(`${slug}/${f}`);
		}
		extractions.push({ source_store: "claude-code", root: ccBase, files_seen: ccFiles, claims: ccClaims, skipped: ccSkipped });

		const ledger = assembleLedger(extractions, "2026-06-23T00:00:00Z");
		const all = ledger.claims;

		// cross-store exact-hash collisions: same content_hash from >1 distinct store
		const byHash = new Map<string, Claim[]>();
		for (const c of all) (byHash.get(c.content_hash) ?? byHash.set(c.content_hash, []).get(c.content_hash)!).push(c);
		let exactDupGroups = 0;
		let exactDupClaims = 0;
		let crossStoreDupGroups = 0;
		const crossStoreExamples: { hash: string; stores: string[]; title?: string }[] = [];
		for (const [hash, group] of byHash) {
			if (group.length > 1) {
				exactDupGroups++;
				exactDupClaims += group.length;
				const stores = [...new Set(group.map((g) => g.source_store))];
				if (stores.length > 1) {
					crossStoreDupGroups++;
					if (crossStoreExamples.length < 15) crossStoreExamples.push({ hash: hash.slice(0, 12), stores, title: group[0]!.title });
				}
			}
		}

		// title collisions (near-dup heuristic): same normalised title, different hash
		const norm = (t?: string) => (t ?? "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
		const byTitle = new Map<string, Set<string>>();
		for (const c of all) {
			const t = norm(c.title);
			if (!t) continue;
			(byTitle.get(t) ?? byTitle.set(t, new Set()).get(t)!).add(c.content_hash);
		}
		let titleClashGroups = 0;
		const titleClashExamples: { title: string; variants: number }[] = [];
		for (const [t, hashes] of byTitle) {
			if (hashes.size > 1) {
				titleClashGroups++;
				if (titleClashExamples.length < 15) titleClashExamples.push({ title: t, variants: hashes.size });
			}
		}

		// section size profile (codex chunking)
		const sectionLens = all.filter((c) => c.span.kind === "section").map((c) => c.text.length).sort((a, b) => b - a);

		const report = {
			generated_at: ledger.manifest.generated_at,
			complete: ledger.complete,
			total_claims: all.length,
			per_store: ledger.manifest.sources.map((s) => ({
				store: s.source_store,
				files_seen: s.file_count,
				claims: s.claim_count,
			})),
			coverage: ledger.coverage,
			scope_hint_distribution: dist(all, (c) => c.scope_hint),
			scope_by_store: Object.fromEntries(
				extractions.map((ex) => [ex.source_store, dist(ex.source_store === "claude-code" ? ccClaims : ex.claims, (c) => c.scope_hint)]),
			),
			dedup: {
				exact_hash_dup_groups: exactDupGroups,
				exact_hash_dup_claims: exactDupClaims,
				cross_store_dup_groups: crossStoreDupGroups,
				cross_store_examples: crossStoreExamples,
			},
			near_dup_title_clashes: { groups: titleClashGroups, examples: titleClashExamples },
			missing_title_claims: all.filter((c) => !c.title).length,
			section_claims: { count: sectionLens.length, largest_chars: sectionLens.slice(0, 5), median_chars: sectionLens[Math.floor(sectionLens.length / 2)] ?? 0 },
			skipped_total: ledger.manifest.skipped.length,
			skipped_reasons: dist(ledger.manifest.skipped.map((s) => ({ scope_hint: s.reason }) as unknown as Claim), (c) => c.scope_hint),
		};
		await writeFile(OUT, JSON.stringify(report, null, 2), "utf8");
		console.log(`survey written to ${OUT}: ${all.length} claims, complete=${ledger.complete}`);
	});
});

