12	 *   on documents (per the model card). We apply the templates client-side so
13	 *   the embedder stays agnostic. The exact template strings are hashed into
14	 *   `promptHash()` — any change invalidates the index and forces a reindex,
15	 *   which is the correctness contract we want.
16	 */
17	
18	import { createHash } from "node:crypto";
19	
20	const DEFAULT_QUERY_TEMPLATE =
21		"Instruct: Given a web search query, retrieve relevant passages that answer the query\nQuery: {q}";
22	const DEFAULT_DOC_TEMPLATE = "{d}";
23	const DEFAULT_VERSION = "v1";
