40		return {
41			url: process.env.DREAM_EMBED_URL ?? "http://127.0.0.1:8186/v1/embeddings",
42			api: parseEmbedApi(process.env.DREAM_EMBED_API),
43			model:
44				process.env.DREAM_EMBED_MODEL ?? "mlx-community/Qwen3-Embedding-0.6B-4bit-DWQ",
45			batchSize: Number(process.env.DREAM_EMBED_BATCH ?? 32),
46			timeoutMs: Number(process.env.DREAM_EMBED_TIMEOUT_MS ?? 30_000),
47			queryTemplate: process.env.DREAM_EMBED_QUERY_TEMPLATE ?? DEFAULT_QUERY_TEMPLATE,
48			docTemplate: process.env.DREAM_EMBED_DOC_TEMPLATE ?? DEFAULT_DOC_TEMPLATE,
49			promptVersion: process.env.DREAM_EMBED_PROMPT_VERSION ?? DEFAULT_VERSION,
50		};
51	}
52	
53	function parseEmbedApi(raw: string | undefined): EmbedApi {
54		if (!raw || raw === "openai") return "openai";
55		if (raw === "tei") return "tei";
56		throw new Error(`unsupported DREAM_EMBED_API=${raw}; expected tei or openai`);
57	}
58	
59	/** Stable hash over the prompt policy. Bump to invalidate the index. */
60	export function promptHash(cfg: EmbedConfig): string {
61		const payload = JSON.stringify({
62			query: cfg.queryTemplate,
63			doc: cfg.docTemplate,
64			version: cfg.promptVersion,
65		});
66		return createHash("sha256").update(payload).digest("hex").slice(0, 16);
67	}
68	
69	function applyTemplate(text: string, kind: EmbedKind, cfg: EmbedConfig): string {
70		const tpl = kind === "query" ? cfg.queryTemplate : cfg.docTemplate;
71		return tpl.replace(kind === "query" ? "{q}" : "{d}", text);
72	}
73	
74	function embedRequestBody(inputs: string[], cfg: EmbedConfig): unknown {
75		if (cfg.api === "openai") return { model: cfg.model, input: inputs };
76		return { inputs };
77	}
78	
79	/**
80	 * Embed an array of texts. Batches at `cfg.batchSize`. Returns vectors in
81	 * input order. Throws on any HTTP/parse failure — caller is the boundary.
82	 */
83	export async function embedBatch(
84		texts: string[],
85		kind: EmbedKind,
86		cfg: EmbedConfig,
87	): Promise<number[][]> {
88		if (texts.length === 0) return [];
89		const out: number[][] = [];
90		for (let i = 0; i < texts.length; i += cfg.batchSize) {
91			const slice = texts.slice(i, i + cfg.batchSize).map((t) => applyTemplate(t, kind, cfg));
92			const batch = await embedOnce(slice, cfg);
93			out.push(...batch);
94		}
95		return out;
96	}
97	
98	async function embedOnce(inputs: string[], cfg: EmbedConfig): Promise<number[][]> {
99		const ctrl = new AbortController();
100		const timer = setTimeout(() => ctrl.abort(), cfg.timeoutMs);
101		try {
102			const resp = await fetch(cfg.url, {
103				method: "POST",
104				headers: { "Content-Type": "application/json" },
105				body: JSON.stringify(embedRequestBody(inputs, cfg)),
106				signal: ctrl.signal,
107			});
108			if (!resp.ok) {
109				const body = await resp.text().catch(() => "");
110				throw new Error(`embed HTTP ${resp.status}: ${body.slice(0, 300)}`);
111			}
112			return parseEmbedResponse(await resp.json(), cfg.api);
113		} finally {
114			clearTimeout(timer);
115		}
116	}
117	
118	export function parseEmbedResponse(data: unknown, api: EmbedApi): number[][] {
119		if (api === "tei") return parseTeiResponse(data);
120		return parseOpenAiResponse(data);
121	}
122	
123	function parseTeiResponse(data: unknown): number[][] {
124		if (Array.isArray(data) && data.every(isNumberArray)) return data;
125		throw new Error("embed response shape mismatch (expected TEI number[][])");
126	}
127	
128	function parseOpenAiResponse(data: unknown): number[][] {
129		if (!isRecord(data) || !Array.isArray(data.data)) {
130			throw new Error("embed response shape mismatch (expected OpenAI { data: [...] })");
131		}
132		const rows = data.data;
133		if (!rows.every(isOpenAiEmbeddingRow)) {
134			throw new Error("embed response shape mismatch (expected OpenAI embedding rows)");
135		}
136		const hasIndexes = rows.every((row) => typeof row.index === "number");
137		const ordered = hasIndexes
138			? [...rows].sort((a, b) => (a.index as number) - (b.index as number))
139			: rows;
140		return ordered.map((row) => row.embedding);
141	}
142	
143	function isRecord(value: unknown): value is Record<string, unknown> {
144		return typeof value === "object" && value !== null;
145	}
146	
147	function isNumberArray(value: unknown): value is number[] {
148		return Array.isArray(value) && value.every((n) => typeof n === "number");
149	}
150	
151	function isOpenAiEmbeddingRow(value: unknown): value is { index?: number; embedding: number[] } {
152		return isRecord(value) && isNumberArray(value.embedding);
153	}
154	
155	/**
156	 * Probe the embedder once for the vector dim. Used at boot to validate the
157	 * index dim matches what the embedder produces.
158	 */
159	export async function probeDim(cfg: EmbedConfig): Promise<number> {
160		const vec = await embedOnce(["warmup"], cfg);
161		const first = vec[0];
162		if (!first || first.length === 0) throw new Error("embedder returned empty vector");
163		return first.length;
164	}
