// semantics can never drift between migration and ingestion.

/** Maps a representative id to every raw claim id it covers (its exact-hash
 * fold), de-duplicating while preserving order. */
type Expander = (ids: string[]) => string[];

function makeExpander(folded: Map<string, string[]>): Expander {
	return (ids) => {
		const out: string[] = [];
		const seen = new Set<string>();
		for (const id of ids) {
			for (const m of folded.get(id) ?? [id]) {
				if (!seen.has(m)) {
					seen.add(m);
					out.push(m);
				}
			}
		}
		return out;
	};
}

/** A representative the judge didn't touch keeps its own record: a `novel` if it
 * stands alone, or an exact-hash `merge` folding the duplicates it covers. */
function soleDisposition(repId: string, coveredIds: string[]): Decision {
	if (coveredIds.length <= 1) return { verb: "novel", id: repId };
	return {
		verb: "merge",
		canonical_id: repId,
		member_ids: coveredIds,
		basis: "exact_hash",
		rationale: "identical normalised content",
	};
}

/** A judge group is usable only if its ids are real and its canonical is among
 * them — defends against model hallucination. */
function isUsable(group: JudgeOutput["groups"][number], idSet: Set<string>): boolean {
	if (!group.member_ids.includes(group.canonical_id)) return false;
	return group.member_ids.every((id) => idSet.has(id));
}

/** Translate one judge group into decisions, marking touched representatives in
 * `decided`. Representatives already decided (by an earlier group in the same
 * cluster) are skipped so a hallucinated overlap can't double-dispose a claim.
 * `expand` folds each representative's exact-hash duplicates into the decision so
 * no raw claim is dropped. */
function groupToDecisions(
	group: JudgeOutput["groups"][number],
	idSet: Set<string>,
	decided: Set<string>,
	expand: Expander,
): Decision[] {
	if (!isUsable(group, idSet)) return [];
	const reps = group.member_ids.filter((id) => !decided.has(id));
	if (!reps.includes(group.canonical_id) || reps.length < 2) return [];

	if (group.relation === "duplicate") {
		for (const id of reps) decided.add(id);
		return [
			{
				verb: "merge",
				canonical_id: group.canonical_id,
				member_ids: expand(reps),
				basis: "judge",
				rationale: group.rationale,
			},
		];
	}

	// supersedes: canonical is the newer claim; the rest are superseded by it.
	// Each side's exact-hash duplicates are folded in so they aren't dropped.
	const out: Decision[] = [];
	decided.add(group.canonical_id);
	const canonDups = expand([group.canonical_id]);
	if (canonDups.length > 1) out.push(soleDisposition(group.canonical_id, canonDups));
	for (const id of reps) {
		if (id === group.canonical_id) continue;
		decided.add(id);
		out.push({
			verb: "supersede",
			new_id: group.canonical_id,
			superseded_id: id,
			rationale: group.rationale,
		});
		const dups = expand([id]);
		if (dups.length > 1) out.push(soleDisposition(id, dups));
	}
	return out;
}

