 * The shared reconciliation core (ADR 0009 D1). One translation of
 * embedding-cluster → exact/judge authority → {novel|merge|supersede}, called
 * two ways:
 *   - `reconcileBulk` — the one-off migration over the whole claim ledger.
 *   - `reconcileOne`  — ongoing dream consolidation, one promoted claim vs the
 *     existing corpus (wired in a later phase; here to prove the core is shared,
 *     not migration-only).
 *
 * Both run the SAME exact-hash check, the SAME judge, and the SAME group→decision
 * mapping. Nothing here writes to disk or deletes — it returns proposals; a human
 * gate applies them (ADR 0009 D6).
 */

import { cosine } from "./embedder.ts";
import { clusterBySimilarity } from "./cluster.ts";
import type {
	Cluster,
	Decision,
	Embedder,
	Judge,
	JudgeOutput,
