/** Validate a judge group against the live id set and the already-`decided`
 * reps, returning a clean reduced group or null. Defends against model
 * hallucination (unknown ids, canonical not among members) and against an
 * earlier group in the same cluster having already claimed some members. */
function reduceGroup(
	group: JudgeOutput["groups"][number],
	idSet: Set<string>,
	decided: Set<string>,
): ReducedGroup | null {
	if (!group.member_ids.every((id) => idSet.has(id))) return null;
	const members = [...new Set(group.member_ids)].filter((id) => !decided.has(id));
	if (members.length < 2 || !members.includes(group.canonical_id)) return null;
	return {
		relation: group.relation,
		canonical_id: group.canonical_id,
		member_ids: members,
		rationale: group.rationale,
	};
