/** Translate a validated group into decisions. Pure — the SAME mapping for both
 * callers. `expand` folds each representative's exact-hash duplicates into the
 * decision so no raw claim is dropped.
 *
 * Disposition model (ADR 0009): every claim lands in exactly one *disposition* —
 * a `novel` or a `merge`. `supersede` is an edge layered on top: the superseding
 * claim is disposed by its OWN novel/merge, and each superseded claim (and its
 * exact duplicates) is disposed by a `supersede`. So a `supersedes` group emits
 * the canonical's own disposition plus one supersede per retired claim. */
function groupDecisions(group: ReducedGroup, expand: Expander): Decision[] {
	if (group.relation === "duplicate") {
		return [
			{
				verb: "merge",
				canonical_id: group.canonical_id,
				member_ids: expand(group.member_ids),
				basis: "judge",
				rationale: group.rationale,
			},
		];
	}

	// supersedes: canonical is the newer claim. It keeps its own record (its
	// disposition); every other rep — and each rep's exact duplicates — is retired.
	const out: Decision[] = [soleDisposition(group.canonical_id, expand([group.canonical_id]))];
	for (const id of group.member_ids) {
		if (id === group.canonical_id) continue;
		for (const supId of expand([id])) {
			out.push({
				verb: "supersede",
				new_id: group.canonical_id,
				superseded_id: supId,
				rationale: group.rationale,
			});
		}
	}
	return out;
}

