function decidedIds(decisions: Decision[]): Set<string> {
	const ids = new Set<string>();
	for (const d of decisions) {
		if (d.verb === "novel") ids.add(d.id);
		else if (d.verb === "merge") for (const m of d.member_ids) ids.add(m);
		else {
			ids.add(d.new_id);
			ids.add(d.superseded_id);
		}
	}
	return ids;
}

