/** Partition claims into reconcile-eligible facts and quarantined scaffolding. */
export function partitionClaims(
	claims: Claim[],
	options: ScaffoldingOptions = {},
): { eligible: Claim[]; quarantined: QuarantineEntry[] } {
	const eligible: Claim[] = [];
	const quarantined: QuarantineEntry[] = [];
	for (const claim of claims) {
		const reason = scaffoldingReason(claim, options);
		if (reason === null) {
			eligible.push(claim);
		} else {
			quarantined.push({
				claim_id: claim.claim_id,
				source_store: claim.source_store,
				source_path: claim.source_path,
				reason,
				bytes: Buffer.byteLength(claim.text, "utf8"),
			});
		}
	}
	return { eligible, quarantined };
}

/** How many times each claim_id is *disposed*. A disposition is where a claim's
 * record lands: a `novel` of it, a `merge` containing it, or a `supersede` that
 * retires it. A supersede's `new_id` is an *edge*, not a disposition — that claim
 * is disposed by its own novel/merge (ADR 0009) — so it is not counted here. */
function dispositionCounts(decisions: Decision[]): Map<string, number> {
	const counts = new Map<string, number>();
	const bump = (id: string) => counts.set(id, (counts.get(id) ?? 0) + 1);
	for (const d of decisions) {
		if (d.verb === "novel") bump(d.id);
		else if (d.verb === "merge") for (const m of d.member_ids) bump(m);
		else bump(d.superseded_id);
	}
	return counts;
}

/** Claim-level no-drops + clean-partition check: every eligible claim must have
 * exactly one disposition, and a quarantined claim must have none. */
export function accountReconciliation(
	claims: Claim[],
	quarantined: QuarantineEntry[],
	decisions: Decision[],
): { complete: boolean; unaccounted: string[]; over_disposed: string[] } {
	const counts = dispositionCounts(decisions);
	const quarantinedIds = new Set(quarantined.map((q) => q.claim_id));
	const unaccounted: string[] = [];
	const over_disposed: string[] = [];
	for (const claim of claims) {
		const n = counts.get(claim.claim_id) ?? 0;
		if (quarantinedIds.has(claim.claim_id)) {
			if (n > 0) over_disposed.push(claim.claim_id); // quarantined AND disposed
			continue;
		}
		if (n === 0) unaccounted.push(claim.claim_id);
		else if (n > 1) over_disposed.push(claim.claim_id);
	}
	return { complete: unaccounted.length === 0 && over_disposed.length === 0, unaccounted, over_disposed };
}

export type ReconcileLedgerOptions = ScaffoldingOptions & {
	/** ISO timestamp; injected so the function stays pure/testable. */
	generatedAt: string;
};

/** Run the full migration reconciliation and assemble the sign-off manifest. */
export async function reconcileLedger(
	claims: Claim[],
	deps: ReconcileDeps,
	options: ReconcileLedgerOptions,
): Promise<ReconciliationManifest> {
	const { eligible, quarantined } = partitionClaims(claims, options);
	const result = await reconcileBulk(eligible.map(claimToReconcileInput), deps);
	const { complete, unaccounted } = accountReconciliation(claims, quarantined, result.decisions);
	return ReconciliationManifestSchema.parse({
		version: 1,
		generated_at: options.generatedAt,
		threshold: deps.threshold ?? DEFAULT_SIM_THRESHOLD,
		total_claims: claims.length,
		eligible_claims: eligible.length,
		stats: result.stats,
		quarantined,
		decisions: result.decisions,
		complete,
		unaccounted,
	});
}

