/** Extract and validate a `JudgeOutput` from raw model text. Tolerates leading/
 * trailing prose by slicing the outermost `{ … }`. Throws on missing/invalid
 * JSON — the caller decides the conservative fallback. Exported for tests. */
export function parseJudgeOutput(text: string): JudgeOutput {
	const start = text.indexOf("{");
	const end = text.lastIndexOf("}");
	if (start < 0 || end <= start) {
		throw new Error(`judge output had no JSON object: ${text.slice(0, 200)}`);
	}
	let parsed: unknown;
	try {
		parsed = JSON.parse(text.slice(start, end + 1));
	} catch (err) {
		throw new Error(`judge output was not valid JSON: ${(err as Error).message}`);
	}
	return JudgeOutputSchema.parse(parsed);
}

input.new_string:
/** Extract and validate a `JudgeOutput` from raw model text. Tolerates prose or
 * code fences around the JSON — including a preamble that itself contains braces
 * — by scanning every balanced top-level `{ … }` block and preferring the first
 * that actually carries a `groups` key. Throws when no balanced object parses, so
 * the caller can apply its conservative fallback. Exported for tests. */
export function parseJudgeOutput(text: string): JudgeOutput {
	const parsedBlocks: Record<string, unknown>[] = [];
	for (const block of balancedObjects(text)) {
		try {
			const obj = JSON.parse(block);
			if (obj && typeof obj === "object" && !Array.isArray(obj)) {
				parsedBlocks.push(obj as Record<string, unknown>);
			}
		} catch {
			// Not a JSON object (e.g. a `{prose}` preamble) — try the next block.
		}
	}
	if (parsedBlocks.length === 0) {
		throw new Error(`judge output had no parseable JSON object: ${text.slice(0, 200)}`);
	}
	// Prefer a block that names `groups`; otherwise fall back to the first object
	// (lets `{}` validate to an empty result via the schema default).
	const chosen = parsedBlocks.find((b) => "groups" in b) ?? parsedBlocks[0];
	return JudgeOutputSchema.parse(chosen);
}

/** Yield each balanced, brace-matched top-level `{ … }` substring, in order.
 * String literals are respected so a `}` inside a JSON string never closes a
 * block early. */
function* balancedObjects(text: string): Generator<string> {
	let depth = 0;
	let start = -1;
	let inString = false;
	let escaped = false;
	for (let i = 0; i < text.length; i++) {
		const ch = text[i];
		if (inString) {
			if (escaped) escaped = false;
			else if (ch === "\\") escaped = true;
			else if (ch === '"') inString = false;
			continue;
		}
		if (ch === '"') {
			inString = true;
		} else if (ch === "{") {
			if (depth === 0) start = i;
			depth++;
		} else if (ch === "}") {
			if (depth > 0) {
				depth--;
				if (depth === 0 && start >= 0) yield text.slice(start, i + 1);
			}
		}
	}
}

