	for (const block of balancedObjects(text)) {
		try {
			const obj = JSON.parse(block);
			if (obj && typeof obj === "object" && !Array.isArray(obj)) {
				parsedBlocks.push(obj as Record<string, unknown>);
			}
		} catch {
			// Not a JSON object (e.g. a `{prose}` preamble) — try the next block.
		}
	}
	if (parsedBlocks.length === 0) {
		throw new Error(`judge output had no parseable JSON object: ${text.slice(0, 200)}`);
	}
	// Prefer a block that names `groups`; otherwise fall back to the first object
	// (lets `{}` validate to an empty result via the schema default).
	const chosen = parsedBlocks.find((b) => "groups" in b) ?? parsedBlocks[0];
	return JudgeOutputSchema.parse(chosen);
}

/** Yield each balanced, brace-matched top-level `{ … }` substring, in order.
 * String literals are respected so a `}` inside a JSON string never closes a
 * block early. */
function* balancedObjects(text: string): Generator<string> {
	let depth = 0;
	let start = -1;
	let inString = false;
	let escaped = false;
	for (let i = 0; i < text.length; i++) {
		const ch = text[i];
		if (inString) {
			if (escaped) escaped = false;
			else if (ch === "\\") escaped = true;
			else if (ch === '"') inString = false;
			continue;
		}
		if (ch === '"') {
			inString = true;
		} else if (ch === "{") {
			if (depth === 0) start = i;
			depth++;
		} else if (ch === "}") {
			if (depth > 0) {
				depth--;
				if (depth === 0 && start >= 0) yield text.slice(start, i + 1);
			}
		}
	}
}

