/**
 * The entailment judge (ADR 0009 D2): given a candidate cluster (claims that are
 * merely embedding-near), decide which members actually state the *same* fact
 * (→ merge) and which *correct/contradict* another (→ supersede). Similarity got
 * them into the same room; the judge alone has merge/supersede authority.
 *
 * The production judge runs over `callPiModel` (claude-bridge / the same path
 * the dream merger uses — no new dep, no API cost). `completeFn` is injectable
 * so tests exercise prompt + parse without a live model. Tests of the reconciler
 * itself inject a `Judge` stub directly and skip this module entirely.
 */

import { callPiModel } from "../lib/pi-model.ts";
import type { PiAuthResolver, PiCompleteFn, PiModelLike } from "../lib/pi-model.ts";
import { JudgeOutputSchema, type JudgeOutput, type ReconcileInput } from "./types.ts";

/** Bound per-member text so a large cluster can't blow the judge context. */
const MEMBER_TEXT_CAP = 4000;

export const JUDGE_SYSTEM =
	"You reconcile a personal-memory store. You are given a small cluster of " +
	"memory claims that an embedding model flagged as similar. Decide which " +
	"claims state the SAME fact, and which one CORRECTS or CONTRADICTS another " +
	"(a newer date, number, name, decision, or negation). Similarity is not " +
	"sameness: a correction sits near the fact it replaces. When unsure, keep " +
	"claims separate — never collapse distinct facts. Reply with STRICT JSON only.";

/** Build the judge user prompt for one cluster. Pure; exported for tests. */
export function buildJudgePrompt(cluster: ReconcileInput[]): string {
	const members = cluster
		.map((c, i) => {
			const header = `[${i + 1}] id=${c.id}${c.source ? ` source=${c.source}` : ""}${
				c.title ? ` title=${JSON.stringify(c.title)}` : ""
			}`;
			const body = c.text.length > MEMBER_TEXT_CAP ? `${c.text.slice(0, MEMBER_TEXT_CAP)}…` : c.text;
			return `${header}\n${body}`;
		})
		.join("\n\n---\n\n");

	return [
		"Cluster members:",
		"",
		members,
		"",
		"Return JSON of this exact shape (no prose, no code fence):",
		'{ "groups": [ { "member_ids": ["<id>", "<id>"], "relation": "duplicate" | "supersedes", "canonical_id": "<id>", "rationale": "<one sentence>" } ] }',
		"",
		'Rules:',
		'- "duplicate": every listed member states the same fact; "canonical_id" is the clearest/most complete member to keep.',
		'- "supersedes": "canonical_id" is the NEWER/correcting claim; the other listed members are the ones it supersedes.',
		'- A member that is distinct from all others: omit it from every group (it is left as-is).',
		'- Use only ids that appear above. If nothing is related, return { "groups": [] }.',
	].join("\n");
}

/** Extract and validate a `JudgeOutput` from raw model text. Tolerates leading/
 * trailing prose by slicing the outermost `{ … }`. Throws on missing/invalid
 * JSON — the caller decides the conservative fallback. Exported for tests. */
export function parseJudgeOutput(text: string): JudgeOutput {
	const start = text.indexOf("{");
	const end = text.lastIndexOf("}");
	if (start < 0 || end <= start) {
		throw new Error(`judge output had no JSON object: ${text.slice(0, 200)}`);
	}
	let parsed: unknown;
	try {
		parsed = JSON.parse(text.slice(start, end + 1));
	} catch (err) {
		throw new Error(`judge output was not valid JSON: ${(err as Error).message}`);
	}
	return JudgeOutputSchema.parse(parsed);
}

export type PiModelJudgeDeps = {
	registry: PiAuthResolver;
	model: PiModelLike;
	/** Test injection; defaults to the real `@valkyriweb/pi-ai` complete(). */
	completeFn?: PiCompleteFn | undefined;
	maxTokens?: number | undefined;
	signal?: AbortSignal | undefined;
};

/** Production judge over `callPiModel`. Reconcile depends on the `Judge` type,
 * not on this — tests inject a stub `Judge` and never load the model layer. */
export function createPiModelJudge(deps: PiModelJudgeDeps): (cluster: ReconcileInput[]) => Promise<JudgeOutput> {
	return async (cluster) => {
		const res = await callPiModel({
			registry: deps.registry,
			model: deps.model,
			system: JUDGE_SYSTEM,
			prompt: buildJudgePrompt(cluster),
			// Reconcile clusters do not share a stable prefix across calls; skip the
			// 25% cache-write surcharge for slots that will never be re-read.
			cacheRetention: "none",
			...(deps.maxTokens !== undefined ? { maxTokens: deps.maxTokens } : {}),
			...(deps.completeFn ? { completeFn: deps.completeFn } : {}),
			...(deps.signal ? { signal: deps.signal } : {}),
		});
		return parseJudgeOutput(res.text);
	};
}

