import { describe, expect, it } from "vitest";

import { makeClaim, type Claim, type ClaimSourceStore, type ScopeHint, type Span } from "../src/migration/ledger.ts";
import {
	accountReconciliation,
	claimToReconcileInput,
	partitionClaims,
	reconcileLedger,
	scaffoldingReason,
	ReconciliationManifestSchema,
	DEFAULT_MAX_CLAIM_BYTES,
} from "../src/migration/reconcile-step.ts";
import type { Embedder, Judge } from "../src/reconcile/types.ts";

// ---------------------------------------------------------------------------

function claim(over: {
	store?: ClaimSourceStore;
	path?: string;
	span?: Span;
	scope?: ScopeHint;
	project?: string;
	title?: string;
	text?: string;
}): Claim {
	return makeClaim({
		source_store: over.store ?? "pi",
		source_path: over.path ?? "note.md",
		span: over.span ?? { kind: "whole" },
		scope_hint: over.scope ?? "project",
		text: over.text ?? "a fact",
		...(over.project !== undefined ? { project_slug: over.project } : {}),
		...(over.title !== undefined ? { title: over.title } : {}),
	});
}

function fixedEmbedder(byText: Record<string, number[]>): Embedder {
	let n = 0;
	return { embed: async (texts) => texts.map((t) => byText[t] ?? [0, 0, ++n]) };
}
const emptyJudge: Judge = async () => ({ groups: [] });

// ---------------------------------------------------------------------------

describe("migration/reconcile-step — scaffolding filter", () => {
	it("quarantines codex boilerplate section headings (case-insensitive)", () => {
		const c = claim({
			store: "codex",
			scope: "episodic",
			span: { kind: "section", start: 0, end: 10, heading: "Memory Summary" },
			text: "blah",
		});
		expect(scaffoldingReason(c)).toMatch(/codex boilerplate/);
	});

	it("keeps a codex section whose heading is a real fact", () => {
		const c = claim({
			store: "codex",
			scope: "episodic",
			span: { kind: "section", start: 0, end: 10, heading: "Decided to use Postgres" },
			text: "blah",
		});
		expect(scaffoldingReason(c)).toBeNull();
	});

	it("does not treat a non-codex section titled 'Citations' as boilerplate", () => {
		const c = claim({
			store: "obsidian",
			span: { kind: "section", start: 0, end: 10, heading: "Citations" },
			text: "blah",
		});
		expect(scaffoldingReason(c)).toBeNull();
	});

	it("quarantines oversized claims regardless of store", () => {
		const big = claim({ text: "x".repeat(DEFAULT_MAX_CLAIM_BYTES + 1) });
		expect(scaffoldingReason(big)).toMatch(/oversized/);
		const ok = claim({ text: "x".repeat(100) });
		expect(scaffoldingReason(ok)).toBeNull();
	});
});

describe("migration/reconcile-step — mapping", () => {
	it("blocks scope by hint, narrowed by project slug", () => {
		expect(claimToReconcileInput(claim({ scope: "project", project: "my-pi" })).scope).toBe("project/my-pi");
		expect(claimToReconcileInput(claim({ scope: "profile" })).scope).toBe("profile");
	});

	it("carries id, hash, title, and source through", () => {
		const c = claim({ store: "codex", title: "T", text: "hello" });
		const ri = claimToReconcileInput(c);
		expect(ri).toMatchObject({ id: c.claim_id, content_hash: c.content_hash, title: "T", source: "codex" });
	});
});

describe("migration/reconcile-step — partition", () => {
	it("splits eligible facts from quarantined scaffolding", () => {
		const claims = [
			claim({ text: "real fact" }),
			claim({ store: "codex", span: { kind: "section", start: 0, end: 5, heading: "Citations" }, text: "x" }),
		];
		const { eligible, quarantined } = partitionClaims(claims);
		expect(eligible).toHaveLength(1);
		expect(quarantined).toHaveLength(1);
		expect(quarantined[0]?.reason).toMatch(/boilerplate/);
		expect(quarantined[0]?.bytes).toBe(1);
	});
});

describe("migration/reconcile-step — accounting", () => {
	it("is complete when every claim is quarantined or decided", () => {
		const a = claim({ path: "a.md", text: "x" });
		const b = claim({ path: "b.md", text: "y" });
		const { complete, unaccounted } = accountReconciliation(
			[a, b],
			[{ claim_id: b.claim_id, source_store: "pi", source_path: "b.md", reason: "oversized", bytes: 1 }],
			[{ verb: "novel", id: a.claim_id }],
		);
		expect(complete).toBe(true);
		expect(unaccounted).toEqual([]);
	});

	it("flags a silently dropped claim", () => {
		const a = claim({ path: "a.md", text: "x" });
		const { complete, unaccounted } = accountReconciliation([a], [], []);
		expect(complete).toBe(false);
		expect(unaccounted).toEqual([a.claim_id]);
	});
});

describe("migration/reconcile-step — reconcileLedger end-to-end", () => {
	it("quarantines scaffolding, reconciles the rest, and accounts for every claim", async () => {
		const boilerplate = claim({
			store: "codex",
			scope: "episodic",
			span: { kind: "section", start: 0, end: 5, heading: "Recording summary" },
			text: "noise",
		});
		// Two byte-identical facts in different files → same content_hash → exact fold.
		const dupA = claim({ path: "a.md", text: "shared fact" });
		const dupB = claim({ path: "b.md", text: "shared fact" });
		const lone = claim({ path: "c.md", text: "distinct fact" });

		const manifest = await reconcileLedger(
			[boilerplate, dupA, dupB, lone],
			{
				embedder: fixedEmbedder({ "shared fact": [1, 0], "distinct fact": [0, 1] }),
				judge: emptyJudge,
			},
			{ generatedAt: "2026-06-23T00:00:00Z" },
		);

		expect(() => ReconciliationManifestSchema.parse(manifest)).not.toThrow();
		expect(manifest.complete).toBe(true);
		expect(manifest.unaccounted).toEqual([]);
		expect(manifest.total_claims).toBe(4);
		expect(manifest.eligible_claims).toBe(3);
		expect(manifest.quarantined.map((q) => q.claim_id)).toEqual([boilerplate.claim_id]);

		const merge = manifest.decisions.find((d) => d.verb === "merge");
		expect(merge).toMatchObject({ basis: "exact_hash" });
		// Canonical is the lexicographically-smaller derived claim_id (deterministic).
		const expectedCanonical = [dupA.claim_id, dupB.claim_id].sort()[0];
		expect(merge).toMatchObject({ canonical_id: expectedCanonical });
		expect(merge && merge.verb === "merge" && [...merge.member_ids].sort()).toEqual(
			[dupA.claim_id, dupB.claim_id].sort(),
		);
		expect(manifest.decisions).toContainEqual({ verb: "novel", id: lone.claim_id });
	});
});

