	// Return the single actionable decision for the candidate, by priority:
	//   1. candidate is retired by an existing record (it's the stale one),
	//   2. candidate merges into / is the canonical of a duplicate group,
	//   3. candidate supersedes an existing record (surface that edge, not the
	//      candidate's own novel disposition).
	// A candidate that supersedes several neighbours yields the edge to its
	// nearest one (neighbours are similarity-ordered); bulk emits the full fan-out.
	return (
		decisions.find((d) => d.verb === "supersede" && d.superseded_id === candidate.id) ??
		decisions.find((d) => d.verb === "merge" && d.member_ids.includes(candidate.id)) ??
		decisions.find((d) => d.verb === "supersede" && d.new_id === candidate.id) ??
		{ verb: "novel", id: candidate.id }
	);
}

toolUseResult.oldString:
	const decisions = groupDecisions(reduced, (ids) => ids);
	// Return the single decision that disposes the candidate. A candidate that
	// supersedes several neighbours yields the edge to its nearest one (neighbours
	// are similarity-ordered); bulk reconciliation emits the full fan-out.
	return (
		decisions.find((d) => disposes(d, candidate.id)) ??
		decisions.find((d) => d.verb === "supersede" && d.new_id === candidate.id) ??
		{ verb: "novel", id: candidate.id }
	);
}

/** Whether a decision is the *disposition* of `id` (where its record lands):
 * a novel of it, a merge that contains it, or a supersede that retires it.
 * A supersede's `new_id` is an edge, not a disposition — the new claim is
 * disposed by its own novel/merge. */
function disposes(d: Decision, id: string): boolean {
	if (d.verb === "novel") return d.id === id;
	if (d.verb === "merge") return d.member_ids.includes(id);
	return d.superseded_id === id;
}

