it("emits a supersede per superseded member, plus the survivor's own disposition", async () => {
	const inputs = [input("old", { text: "t" }), input("new", { text: "t" })];
	const res = await reconcileBulk(inputs, {
		embedder: fixedEmbedder({ t: [1, 0] }),
		judge: cannedJudge({
			groups: [{ member_ids: ["old", "new"], relation: "supersedes", canonical_id: "new", rationale: "newer date" }],
		}),
	});
	expect(res.decisions).toContainEqual({
		verb: "supersede",
		new_id: "new",
		superseded_id: "old",
		rationale: "newer date",
	});
	// The superseding claim keeps its own record — disposed as novel, not via
	// the supersede edge (ADR 0009 disposition model).
	expect(res.decisions).toContainEqual({ verb: "novel", id: "new" });
	expect(res.stats).toMatchObject({ supersedes: 1, novel: 1 });
	// "new" is disposed exactly once (its novel); the supersede new_id is an edge.
	expect(res.decisions.filter((d) => d.verb === "novel" && d.id === "new")).toHaveLength(1);
});

it("never double-disposes a survivor that also has exact duplicates (supersede corner)", async () => {
	// "new" + "new2" are byte-identical; "new" supersedes "old".
	const inputs = [
		input("new", { content_hash: "H", text: "t" }),
		input("new2", { content_hash: "H", text: "t" }),
		input("old", { content_hash: "Hold", text: "t" }),
	];
	const res = await reconcileBulk(inputs, {
		embedder: fixedEmbedder({ t: [1, 0] }),
		judge: cannedJudge({
			// Reps are the canonical of each hash group: min("new","new2")="new", and "old".
			groups: [{ member_ids: ["new", "old"], relation: "supersedes", canonical_id: "new", rationale: "newer" }],
		}),
	});
	// "new"+"new2" fold into one exact-hash merge (the survivor's disposition);
	// "old" is superseded. Every raw id disposed exactly once.
	const dispositions = new Map<string, number>();
	for (const d of res.decisions) {
		if (d.verb === "novel") dispositions.set(d.id, (dispositions.get(d.id) ?? 0) + 1);
		else if (d.verb === "merge")
			for (const m of d.member_ids) dispositions.set(m, (dispositions.get(m) ?? 0) + 1);
		else dispositions.set(d.superseded_id, (dispositions.get(d.superseded_id) ?? 0) + 1);
	}
	expect([...dispositions.entries()].sort()).toEqual([
		["new", 1],
		["new2", 1],
		["old", 1],
	]);
	expect(res.decisions).toContainEqual({
		verb: "supersede",
		new_id: "new",
		superseded_id: "old",
		rationale: "newer",
	});
});

it("skips a second overlapping group whose members an earlier group already claimed", async () => {
	const inputs = [input("a", { text: "t" }), input("b", { text: "t" }), input("c", { text: "t" })];
	const res = await reconcileBulk(inputs, {
		embedder: fixedEmbedder({ t: [1, 0] }),
		judge: cannedJudge({
			groups: [
				{ member_ids: ["a", "b", "c"], relation: "duplicate", canonical_id: "a", rationale: "all same" },
				// Overlaps the first group — every member already decided → skipped.
				{ member_ids: ["b", "c"], relation: "supersedes", canonical_id: "c", rationale: "stale overlap" },
			],
		}),
	});
	expect(res.decisions).toEqual([
		{ verb: "merge", canonical_id: "a", member_ids: ["a", "b", "c"], basis: "judge", rationale: "all same" },
	]);
	expect(res.stats.supersedes).toBe(0);
});

