			text: "noise",
		});
		// Two byte-identical facts in different files → same content_hash → exact fold.
		const dupA = claim({ path: "a.md", text: "shared fact" });
		const dupB = claim({ path: "b.md", text: "shared fact" });
		const lone = claim({ path: "c.md", text: "distinct fact" });

		const manifest = await reconcileLedger(
			[boilerplate, dupA, dupB, lone],
			{
				embedder: fixedEmbedder({ "shared fact": [1, 0], "distinct fact": [0, 1] }),
				judge: emptyJudge,
			},
			{ generatedAt: "2026-06-23T00:00:00Z" },
		);

		expect(() => ReconciliationManifestSchema.parse(manifest)).not.toThrow();
		expect(manifest.complete).toBe(true);
		expect(manifest.unaccounted).toEqual([]);
		expect(manifest.total_claims).toBe(4);
		expect(manifest.eligible_claims).toBe(3);
		expect(manifest.quarantined.map((q) => q.claim_id)).toEqual([boilerplate.claim_id]);

		const merge = manifest.decisions.find((d) => d.verb === "merge");
		expect(merge).toMatchObject({ basis: "exact_hash" });
		// Canonical is the lexicographically-smaller derived claim_id (deterministic).
		const expectedCanonical = [dupA.claim_id, dupB.claim_id].sort()[0];
		expect(merge).toMatchObject({ canonical_id: expectedCanonical });
		expect(merge && merge.verb === "merge" && [...merge.member_ids].sort()).toEqual(
			[dupA.claim_id, dupB.claim_id].sort(),
		);
		expect(manifest.decisions).toContainEqual({ verb: "novel", id: lone.claim_id });
	});

	it("handles a supersede with exact duplicates on the survivor and stays a clean partition", async () => {
		// Two byte-identical 'new' facts fold to one survivor; it supersedes 'old'.
		const newA = claim({ path: "a.md", text: "new fact" });
		const newB = claim({ path: "b.md", text: "new fact" });
		const old = claim({ path: "c.md", text: "old fact" });
		const survivor = [newA.claim_id, newB.claim_id].sort()[0] as string;

		const manifest = await reconcileLedger(
			[newA, newB, old],
			{
				embedder: fixedEmbedder({ "new fact": [1, 0], "old fact": [1, 0] }),
				judge: async () => ({
					groups: [
						{ member_ids: [survivor, old.claim_id], relation: "supersedes", canonical_id: survivor, rationale: "newer" },
					],
				}),
			},
			{ generatedAt: "2026-06-23T00:00:00Z" },
		);

		expect(() => ReconciliationManifestSchema.parse(manifest)).not.toThrow();
		expect(manifest.complete).toBe(true);
		expect(manifest.unaccounted).toEqual([]);
		expect(manifest.over_disposed).toEqual([]);
		// Survivor's exact-dup pair folds into one merge; 'old' is superseded.
		expect(manifest.decisions).toContainEqual({
			verb: "supersede",
			new_id: survivor,
			superseded_id: old.claim_id,
			rationale: "newer",
		});
		const merge = manifest.decisions.find((d) => d.verb === "merge");
		expect(merge && merge.verb === "merge" && [...merge.member_ids].sort()).toEqual(
			[newA.claim_id, newB.claim_id].sort(),
		);
	});
});

/**
 * The shared reconciliation core (ADR 0009 D1). One translation of
 * embedding-cluster → exact/judge authority → {novel|merge|supersede}, called
 * two ways:
 *   - `reconcileBulk` — the one-off migration over the whole claim ledger.
 *   - `reconcileOne`  — ongoing dream consolidation, one promoted claim vs the
 *     existing corpus (wired in a later phase; here to prove the core is shared,
 *     not migration-only).
 *
 * Both run the SAME exact-hash check, the SAME judge, and the SAME group→decision
 * mapping. Nothing here writes to disk or deletes — it returns proposals; a human
 * gate applies them (ADR 0009 D6).
 */

import { cosine } from "./embedder.ts";
import { clusterBySimilarity } from "./cluster.ts";
import type {
	Cluster,
	Decision,
	Embedder,
	Judge,
	JudgeOutput,
	ReconcileInput,
	ReconcileResult,
	ReconcileStats,
} from "./types.ts";

export const DEFAULT_SIM_THRESHOLD = 0.83;
const DEFAULT_TOP_K = 8;

export type ReconcileDeps = {
	embedder: Embedder;
	judge: Judge;
	/** Cosine cut-off for candidate clustering. Higher = fewer, tighter clusters. */
	threshold?: number;
};

/**
 * Reconcile a whole ledger of claims. Exact-content duplicates collapse first
 * (cheap, deterministic); the survivors are embedded, scope-blocked, clustered,
 * and each multi-member cluster is sent to the judge.
 */
export async function reconcileBulk(
	inputs: ReconcileInput[],
	deps: ReconcileDeps,
): Promise<ReconcileResult> {
	const threshold = deps.threshold ?? DEFAULT_SIM_THRESHOLD;
	const decisions: Decision[] = [];
	let exactDupGroups = 0;

	// 1. Fold exact-content duplicates onto a representative. (The real corpus has
	//    zero of these cross-store, but ingestion hits them constantly, and it's a
	//    free, deterministic pre-pass.) We don't emit decisions yet — the fold is
	//    expanded into each representative's single final decision in steps 3/4, so
	//    every raw claim lands in exactly one decision (no double-disposition).
	const byHash = new Map<string, ReconcileInput[]>();
	for (const input of inputs) {
		const group = byHash.get(input.content_hash);
		if (group) group.push(input);
		else byHash.set(input.content_hash, [input]);
	}
	const representatives: ReconcileInput[] = [];
	const folded = new Map<string, string[]>(); // repId → every raw claim id it covers (incl. itself)
	for (const group of byHash.values()) {
		const sorted = [...group].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
		const canonical = sorted[0] as ReconcileInput;
		representatives.push(canonical);
		folded.set(canonical.id, sorted.map((c) => c.id));
		if (sorted.length > 1) exactDupGroups++;
	}
	const expand = makeExpander(folded);

	// 2. Embed + cluster the representatives.
	const vectors = await deps.embedder.embed(representatives.map((r) => r.text));
	const clusters = clusterBySimilarity(representatives, vectors, threshold);
	const byId = new Map(representatives.map((r) => [r.id, r] as const));

	// 3. Judge each multi-member cluster; map its groups to decisions.
	const decided = new Set<string>();
	let clustersJudged = 0;
	let judgeFailures = 0;
	for (const cluster of clusters) {
		const members = cluster.member_ids
			.map((id) => byId.get(id))
			.filter((m): m is ReconcileInput => m !== undefined);
		const idSet = new Set(members.map((m) => m.id));
		let output: JudgeOutput;
		try {
			output = await deps.judge(members);
			clustersJudged++;
		} catch {
			// Conservative: leave the whole cluster's members to fall through to
			// `novel`/exact-fold and surface the failure in stats (ADR 0009 D2 —
			// never drop).
			judgeFailures++;
			continue;
		}
		for (const group of output.groups) {
			// Drop reps an earlier group in this cluster already consumed, so a
			// hallucinated overlap can't double-dispose a claim.
			const reduced = reduceGroup(group, idSet, decided);
			if (!reduced) continue;
			for (const id of reduced.member_ids) decided.add(id);
			decisions.push(...groupDecisions(reduced, expand));
		}
	}

	// 4. Every representative the judge didn't consume keeps its own record:
	//    novel, or an exact-hash merge if it folded duplicates.
	for (const rep of representatives) {
		if (decided.has(rep.id)) continue;
		const ids = folded.get(rep.id) ?? [rep.id];
		decisions.push(soleDisposition(rep.id, ids));
	}

	return { decisions, clusters, stats: tally(inputs.length, exactDupGroups, clustersJudged, judgeFailures, decisions) };
}

export type ReconcileOneDeps = ReconcileDeps & { topK?: number };
export type CorpusEntry = { input: ReconcileInput; vector: number[] };

/**
 * Reconcile a single candidate against an already-embedded corpus. The ingestion
 * (dream-consolidation) entry point — same authority order as bulk: exact hash,
 * then judge over the nearest same-scope neighbours. Returns one decision.
 */
export async function reconcileOne(
	candidate: ReconcileInput,
	corpus: CorpusEntry[],
	deps: ReconcileOneDeps,
): Promise<Decision> {
	const threshold = deps.threshold ?? DEFAULT_SIM_THRESHOLD;
	const topK = deps.topK ?? DEFAULT_TOP_K;

	const exact = corpus.find((e) => e.input.content_hash === candidate.content_hash);
	if (exact) {
		return {
			verb: "merge",
			canonical_id: exact.input.id,
			member_ids: [exact.input.id, candidate.id],
			basis: "exact_hash",
			rationale: "identical normalised content",
		};
	}

	const [vec] = await deps.embedder.embed([candidate.text]);
	if (!vec) return { verb: "novel", id: candidate.id };

	const neighbours = corpus
		.filter((e) => e.input.scope === candidate.scope)
		.map((e) => ({ entry: e, sim: cosine(vec, e.vector) }))
		.filter((n) => n.sim >= threshold)
		.sort((a, b) => b.sim - a.sim)
		.slice(0, topK)
		.map((n) => n.entry.input);

	if (neighbours.length === 0) return { verb: "novel", id: candidate.id };

	const members = [candidate, ...neighbours];
	const idSet = new Set(members.map((m) => m.id));
	let output: JudgeOutput;
	try {
		output = await deps.judge(members);
	} catch {
		return { verb: "novel", id: candidate.id };
	}

	// Find the candidate's group and translate it with the SAME mapping bulk uses
	// (ingestion has no exact-fold map, so each corpus entry stands for itself).
	const raw = output.groups.find((g) => g.member_ids.includes(candidate.id));
	const reduced = raw ? reduceGroup(raw, idSet, new Set()) : null;
	if (!reduced || !reduced.member_ids.includes(candidate.id)) {
		return { verb: "novel", id: candidate.id };
	}
	const decisions = groupDecisions(reduced, (ids) => ids);
	// Return the single actionable decision for the candidate, by priority:
	//   1. candidate is retired by an existing record (it's the stale one),
	//   2. candidate merges into / is the canonical of a duplicate group,
	//   3. candidate supersedes an existing record (surface that edge, not the
	//      candidate's own novel disposition).
	// A candidate that supersedes several neighbours yields the edge to its
	// nearest one (neighbours are similarity-ordered); bulk emits the full fan-out.
	return (
		decisions.find((d) => d.verb === "supersede" && d.superseded_id === candidate.id) ??
		decisions.find((d) => d.verb === "merge" && d.member_ids.includes(candidate.id)) ??
		decisions.find((d) => d.verb === "supersede" && d.new_id === candidate.id) ??
		{ verb: "novel", id: candidate.id }
	);
}

// ---------------------------------------------------------------------------
// Shared group → decision translation. Used by both callers so merge/supersede
// semantics can never drift between migration and ingestion.

/** Maps a representative id to every raw claim id it covers (its exact-hash
 * fold), de-duplicating while preserving order. */
type Expander = (ids: string[]) => string[];

function makeExpander(folded: Map<string, string[]>): Expander {
	return (ids) => {
		const out: string[] = [];
		const seen = new Set<string>();
		for (const id of ids) {
			for (const m of folded.get(id) ?? [id]) {
				if (!seen.has(m)) {
					seen.add(m);
					out.push(m);
				}
			}
		}
		return out;
	};
}

/** A representative the judge didn't touch keeps its own record: a `novel` if it
 * stands alone, or an exact-hash `merge` folding the duplicates it covers. */
function soleDisposition(repId: string, coveredIds: string[]): Decision {
	if (coveredIds.length <= 1) return { verb: "novel", id: repId };
	return {
		verb: "merge",
		canonical_id: repId,
		member_ids: coveredIds,
		basis: "exact_hash",
		rationale: "identical normalised content",
	};
}

type ReducedGroup = {
	relation: JudgeOutput["groups"][number]["relation"];
	canonical_id: string;
	/** Distinct representative ids, canonical guaranteed present, length ≥ 2. */
	member_ids: string[];
	rationale: string;
};

/** Validate a judge group against the live id set and the already-`decided`
 * reps, returning a clean reduced group or null. Defends against model
 * hallucination (unknown ids, canonical not among members) and against an
 * earlier group in the same cluster having already claimed some members. */
function reduceGroup(
	group: JudgeOutput["groups"][number],
	idSet: Set<string>,
	decided: Set<string>,
): ReducedGroup | null {
	if (!group.member_ids.every((id) => idSet.has(id))) return null;
	const members = [...new Set(group.member_ids)].filter((id) => !decided.has(id));
	if (members.length < 2 || !members.includes(group.canonical_id)) return null;
	return {
		relation: group.relation,
		canonical_id: group.canonical_id,
		member_ids: members,
		rationale: group.rationale,
	};
}

/** Translate a validated group into decisions. Pure — the SAME mapping for both
 * callers. `expand` folds each representative's exact-hash duplicates into the
 * decision so no raw claim is dropped.
 *
 * Disposition model (ADR 0009): every claim lands in exactly one *disposition* —
 * a `novel` or a `merge`. `supersede` is an edge layered on top: the superseding
 * claim is disposed by its OWN novel/merge, and each superseded claim (and its
 * exact duplicates) is disposed by a `supersede`. So a `supersedes` group emits
 * the canonical's own disposition plus one supersede per retired claim. */
function groupDecisions(group: ReducedGroup, expand: Expander): Decision[] {
	if (group.relation === "duplicate") {
		return [
			{
				verb: "merge",
				canonical_id: group.canonical_id,
				member_ids: expand(group.member_ids),
				basis: "judge",
				rationale: group.rationale,
			},
		];
	}

	// supersedes: canonical is the newer claim. It keeps its own record (its
	// disposition); every other rep — and each rep's exact duplicates — is retired.
	const out: Decision[] = [soleDisposition(group.canonical_id, expand([group.canonical_id]))];
	for (const id of group.member_ids) {
		if (id === group.canonical_id) continue;
		for (const supId of expand([id])) {
			out.push({
				verb: "supersede",
				new_id: group.canonical_id,
				superseded_id: supId,
				rationale: group.rationale,
			});
		}
	}
	return out;
}

function tally(
	inputs: number,
	exactDupGroups: number,
	clustersJudged: number,
	judgeFailures: number,
	decisions: Decision[],
): ReconcileStats {
	let merges = 0;
	let supersedes = 0;
	let novel = 0;
	for (const d of decisions) {
		if (d.verb === "merge") merges++;
		else if (d.verb === "supersede") supersedes++;
		else novel++;
	}
	return {
		inputs,
		exact_dup_groups: exactDupGroups,
		clusters_judged: clustersJudged,
		judge_failures: judgeFailures,
		merges,
		supersedes,
		novel,
	};
}

