/**
 * Claude Code native-memory extractor (`~/.claude/projects/<slug>/memory`).
 * Read-only source. Each file is one fact (whole-file claim) with nested
 * frontmatter `name`/`description`/`metadata.{node_type,type}`. `MEMORY.md` is
 * the generated index, not a fact — skipped with a reason.
 */

import { makeClaim, type Claim, type ClaimSourceStore, type Skipped, type StoreExtraction } from "../ledger.ts";
import { parseFrontmatter } from "../parse.ts";
import { asString, listMarkdownFiles, mtimeIso, readText, scopeFromType } from "./util.ts";

const STORE: ClaimSourceStore = "claude-code";

function metaType(data: Record<string, unknown>): unknown {
	const meta = data.metadata;
	if (meta && typeof meta === "object" && !Array.isArray(meta)) return (meta as Record<string, unknown>).type;
	return undefined;
}

export async function extractClaudeCode(root: string): Promise<StoreExtraction> {
	const files = await listMarkdownFiles(root);
	const claims: Claim[] = [];
	const skipped: Skipped[] = [];

	for (const rel of files) {
		const base = rel.split("/").pop() ?? rel;
		if (base === "MEMORY.md") {
			skipped.push({ source_store: STORE, path: rel, reason: "generated index, not a fact" });
			continue;
		}
		const text = await readText(root, rel);
		if (!text.trim()) {
			skipped.push({ source_store: STORE, path: rel, reason: "empty file" });
			continue;
		}
		const { data } = parseFrontmatter(text);

		claims.push(
			makeClaim({
				source_store: STORE,
				source_path: rel,
				span: { kind: "whole" },
				scope_hint: scopeFromType(metaType(data)),
				title: asString(data.name),
				captured_at: await mtimeIso(root, rel),
				text,
				origin_meta: Object.keys(data).length ? data : undefined,
			}),
		);
	}
	return { source_store: STORE, root, files_seen: files, claims, skipped };
}

