287	export type ModelAlias = "sonnet-class" | "haiku-class" | "fast-class";
288	
289	type AliasMatcher = (m: PiModelLike) => boolean;
290	
291	const FAST_MODEL_PER_PROVIDER: Record<string, string> = {
292		anthropic: "claude-haiku-4-5",
293		"amazon-bedrock": "us.anthropic.claude-haiku-4-5-20251001-v1:0",
294		openai: "gpt-5.4-mini",
295		"openai-codex": "gpt-5.4-mini",
296		"azure-openai-responses": "gpt-5.4-mini",
297		"github-copilot": "gpt-5.4-mini",
298		google: "gemini-3.1-flash-lite",
299		"google-vertex": "gemini-3.1-flash-lite",
300		groq: "openai/gpt-oss-20b",
301		xai: "grok-4-fast",
302		"claude-bridge": "claude-haiku-4-5",
303	};
304	
305	const ALIAS_MATCHERS: Record<ModelAlias, AliasMatcher[]> = {
306		"sonnet-class": [
307			// Anthropic Sonnet line, newest first.
308			(m) => m.provider === "anthropic" && /sonnet-4-6/i.test(m.id),
309			(m) => m.provider === "anthropic" && /sonnet-4-5/i.test(m.id),
310			(m) => m.provider === "anthropic" && /sonnet-4(?!-\d)/i.test(m.id),
311			(m) => m.provider === "anthropic" && /3-7-sonnet|3-5-sonnet/i.test(m.id),
312			(m) => m.provider === "anthropic" && /sonnet/i.test(m.id),
313			// OpenAI codex (via Pi's openai-codex provider) — capable peers.
314			(m) => m.provider === "openai-codex" && /^gpt-5(-codex)?$/i.test(m.id),
315			(m) => m.provider === "openai" && /^o3$|^o1$/i.test(m.id),
316			(m) => m.provider === "openai" && /^gpt-4(\.|o)/i.test(m.id),
317		],
318		"haiku-class": [
319			(m) => m.provider === "anthropic" && /haiku-4-5/i.test(m.id),
320			(m) => m.provider === "anthropic" && /haiku-4/i.test(m.id),
321			(m) => m.provider === "anthropic" && /3-5-haiku/i.test(m.id),
322			(m) => m.provider === "anthropic" && /haiku/i.test(m.id),
323			(m) => m.provider === "openai" && /4o-mini|gpt-4-mini|nano/i.test(m.id),
324			(m) => m.provider === "openai-codex" && /mini|nano/i.test(m.id),
325		],
326		"fast-class": [
327			(m) => m.provider === "openai-codex" && m.id === "gpt-5.4-mini",
328			(m) => m.provider === "openai" && m.id === "gpt-5.4-mini",
329			(m) => m.provider === "claude-bridge" && m.id === "claude-haiku-4-5",
330			(m) => m.provider === "anthropic" && /haiku-4-5/i.test(m.id),
331			(m) => m.provider === "google" && /flash-lite/i.test(m.id),
332			(m) => m.provider === "google-vertex" && /flash-lite/i.test(m.id),
333			(m) => /mini|nano|haiku|flash-lite|fast/i.test(m.id),
334		],
335	};
336	
337	/**
338	 * Pick a model by alias from an existing registry.
339	 *
340	 * Resolution order:
341	 *   1. If `envOverride` is set (e.g. `DREAM_MODEL=anthropic/claude-haiku-4-5`)
342	 *      use it verbatim. Throws if the registry can't find it.
343	 *   2. Walk `ALIAS_MATCHERS[alias]` against `registry.getAvailable()` (which
344	 *      filters to models with configured auth) and return the first match.
345	 *   3. Throw a clear `PiModelError` if nothing matches — caller is expected
346	 *      to surface this to the user, not silently degrade.
347	 */
348	export function pickModel(
349		registry: Pick<PiModelRegistryLike, "getAvailable" | "find">,
350		alias: ModelAlias,
351		envOverride?: string,
352		parentModel?: PiModelLike,
353	): PiModelLike {
354		if (envOverride) {
355			const slash = envOverride.indexOf("/");
356			if (slash > 0) {
357				const provider = envOverride.slice(0, slash);
358				const id = envOverride.slice(slash + 1);
359				const found = registry.find(provider, id);
360				if (found) return found;
361				throw new PiModelError(
362					`pickModel: env override ${envOverride} not in registry`,
363				);
364			}
365			throw new PiModelError(
366				`pickModel: env override must be 'provider/model-id', got: ${envOverride}`,
367			);
368		}
369		const available = registry.getAvailable();
370		if (available.length === 0) {
371			throw new PiModelError(
372				"pickModel: no models with configured auth — run `pi auth login` first",
373			);
374		}
375		if (alias === "fast-class" && parentModel) {
376			const fastId = FAST_MODEL_PER_PROVIDER[parentModel.provider];
377			if (fastId) {
378				const providerFast = registry.find(parentModel.provider, fastId);
379				if (providerFast) return providerFast;
380			}
381			const sameProviderFast = available.find((m) =>
382				m.provider === parentModel.provider && /mini|nano|haiku|flash-lite|fast/i.test(m.id),
383			);
384			if (sameProviderFast) return sameProviderFast;
385			const parent = registry.find(parentModel.provider, parentModel.id);
386			if (parent) return parent;
387		}
388		for (const matcher of ALIAS_MATCHERS[alias]) {
389			const found = available.find(matcher);
390			if (found) return found;
391		}
392		const sample = available
393			.slice(0, 5)
