export type ModelAlias = "sonnet-class" | "haiku-class" | "fast-class";

type AliasMatcher = (m: PiModelLike) => boolean;

const FAST_MODEL_PER_PROVIDER: Record<string, string> = {
	anthropic: "claude-haiku-4-5",
	"amazon-bedrock": "us.anthropic.claude-haiku-4-5-20251001-v1:0",
	openai: "gpt-5.4-mini",
	"openai-codex": "gpt-5.4-mini",
	"azure-openai-responses": "gpt-5.4-mini",
	"github-copilot": "gpt-5.4-mini",
	google: "gemini-3.1-flash-lite",
	"google-vertex": "gemini-3.1-flash-lite",
	groq: "openai/gpt-oss-20b",
	xai: "grok-4-fast",
	"claude-bridge": "claude-haiku-4-5",
};

const ALIAS_MATCHERS: Record<ModelAlias, AliasMatcher[]> = {
	"sonnet-class": [
		// Anthropic Sonnet line, newest first.
		(m) => m.provider === "anthropic" && /sonnet-4-6/i.test(m.id),
		(m) => m.provider === "anthropic" && /sonnet-4-5/i.test(m.id),
		(m) => m.provider === "anthropic" && /sonnet-4(?!-\d)/i.test(m.id),
		(m) => m.provider === "anthropic" && /3-7-sonnet|3-5-sonnet/i.test(m.id),
		(m) => m.provider === "anthropic" && /sonnet/i.test(m.id),
		// OpenAI codex (via Pi's openai-codex provider) — capable peers.
		(m) => m.provider === "openai-codex" && /^gpt-5(-codex)?$/i.test(m.id),
		(m) => m.provider === "openai" && /^o3$|^o1$/i.test(m.id),
		(m) => m.provider === "openai" && /^gpt-4(\.|o)/i.test(m.id),
	],
	"haiku-class": [
		(m) => m.provider === "anthropic" && /haiku-4-5/i.test(m.id),
		(m) => m.provider === "anthropic" && /haiku-4/i.test(m.id),
		(m) => m.provider === "anthropic" && /3-5-haiku/i.test(m.id),
		(m) => m.provider === "anthropic" && /haiku/i.test(m.id),
		(m) => m.provider === "openai" && /4o-mini|gpt-4-mini|nano/i.test(m.id),
		(m) => m.provider === "openai-codex" && /mini|nano/i.test(m.id),
	],
	"fast-class": [
		(m) => m.provider === "openai-codex" && m.id === "gpt-5.4-mini",
		(m) => m.provider === "openai" && m.id === "gpt-5.4-mini",
		(m) => m.provider === "claude-bridge" && m.id === "claude-haiku-4-5",
		(m) => m.provider === "anthropic" && /haiku-4-5/i.test(m.id),
		(m) => m.provider === "google" && /flash-lite/i.test(m.id),
		(m) => m.provider === "google-vertex" && /flash-lite/i.test(m.id),
		(m) => /mini|nano|haiku|flash-lite|fast/i.test(m.id),
	],
};

/**
 * Pick a model by alias from an existing registry.
 *
 * Resolution order:
 *   1. If `envOverride` is set (e.g. `DREAM_MODEL=anthropic/claude-haiku-4-5`)
 *      use it verbatim. Throws if the registry can't find it.
 *   2. Walk `ALIAS_MATCHERS[alias]` against `registry.getAvailable()` (which
 *      filters to models with configured auth) and return the first match.
 *   3. Throw a clear `PiModelError` if nothing matches — caller is expected
 *      to surface this to the user, not silently degrade.
 */
export function pickModel(
	registry: Pick<PiModelRegistryLike, "getAvailable" | "find">,
	alias: ModelAlias,
	envOverride?: string,
	parentModel?: PiModelLike,
): PiModelLike {
	if (envOverride) {
		const slash = envOverride.indexOf("/");
		if (slash > 0) {
			const provider = envOverride.slice(0, slash);
			const id = envOverride.slice(slash + 1);
			const found = registry.find(provider, id);
			if (found) return found;
			throw new PiModelError(
				`pickModel: env override ${envOverride} not in registry`,
			);
		}
		throw new PiModelError(
			`pickModel: env override must be 'provider/model-id', got: ${envOverride}`,
		);
	}
	const available = registry.getAvailable();
	if (available.length === 0) {
		throw new PiModelError(
			"pickModel: no models with configured auth — run `pi auth login` first",
		);
	}
	if (alias === "fast-class" && parentModel) {
		const fastId = FAST_MODEL_PER_PROVIDER[parentModel.provider];
		if (fastId) {
			const providerFast = registry.find(parentModel.provider, fastId);
			if (providerFast) return providerFast;
		}
		const sameProviderFast = available.find((m) =>
			m.provider === parentModel.provider && /mini|nano|haiku|flash-lite|fast/i.test(m.id),
		);
		if (sameProviderFast) return sameProviderFast;
		const parent = registry.find(parentModel.provider, parentModel.id);
		if (parent) return parent;
	}
	for (const matcher of ALIAS_MATCHERS[alias]) {
		const found = available.find(matcher);
		if (found) return found;
	}
	const sample = available
		.slice(0, 5)
		.map((m) => `${m.provider}/${m.id}`)
		.join(", ");
	throw new PiModelError(
		`pickModel: no available model matches alias '${alias}' (tried ${ALIAS_MATCHERS[alias].length} matchers; sample: ${sample})`,
	);
}

// ---------------------------------------------------------------------------
// Standalone registry construction — used by the dream CLI (not by the Pi
// extension, which gets the registry from ctx.modelRegistry).

export interface PiRegistryHandle {
	registry: PiModelRegistry;
	close(): void;
}

/**
 * Construct an in-process ModelRegistry that resolves auth from Pi's
 * keychain (~/.pi/agent/auth.json) and Pi's models.json overrides.
 *
 * This is the only place we touch `@valkyriweb/pi-coding-agent` outside
 * of types — tests that don't go through the dream CLI won't load it.
 */
export async function createPiRegistry(): Promise<PiRegistryHandle> {
	const mod = await import("@valkyriweb/pi-coding-agent");
	const auth = mod.AuthStorage.create();
	const registry = mod.ModelRegistry.create(auth) as unknown as PiModelRegistry;
	return { registry, close: () => undefined };
}

// Type-only re-export so callers depending on the real registry shape can
// share the type without re-importing pi-coding-agent themselves.
export type PiCodingAgentModelRegistry = ModelRegistry;

