/**
 * scripts/migrate-reconcile.ts — run the P2 memory reconciler against the real
 * migrated claim corpus and write a sign-off manifest (ADR 0009).
 *
 * This is the production caller the reconcile core was built for: it loads every
 * source store (read-only), wires the REAL embedder (MLX, port 8186) and the REAL
 * entailment judge (claude-bridge via Pi auth), runs `reconcileLedger`, and writes
 * the `ReconciliationManifest` for Luke to review. It is PROPOSE-ONLY — nothing
 * here writes to the canonical store or deletes anything. Apply (P2c) is a
 * separate, sign-off-gated step that does not exist yet.
 *
 * Two modes:
 *   --preview   load → quarantine → embed → cluster, then COUNT clusters with a
 *               stub judge (no model calls). Reports scale + how many real judge
 *               calls a full run would cost. Spends zero judge quota.
 *   (default)   full run: the real judge decides each cluster; writes manifest.
 *
 * Usage:
 *   pnpm tsx scripts/migrate-reconcile.ts --preview
 *   pnpm tsx scripts/migrate-reconcile.ts
 *
 * Env:
 *   PI_MEMORY_DIR            pi store root        (default ~/.pi/agent/memory)
 *   DREAM_WIKI_HOME          obsidian vault root  (default ~/obsidian/dream-memory; +/memory)
 *   CODEX_MEMORY_DIR         codex store root     (default ~/.codex/memories)
 *   DREAM_RECONCILE_THRESHOLD  cosine cut-off     (default 0.83)
 *   DREAM_RECONCILE_MODEL    judge model override 'provider/id' (default sonnet-class)
 *   DREAM_RECONCILE_OUT      output dir           (default ~/.dream-memory/migration-reconcile)
 *   DREAM_EMBED_*            embedder wiring (already in Luke's env; defaults hit :8186)
 *
 * Requires: MLX embedder on :8186, Pi auth (~/.pi/agent/auth.json) for the judge.
 */

import { mkdir, readdir, writeFile } from "node:fs/promises";
import { homedir } from "node:os";
import { join } from "node:path";

import {
	assembleLedger,
	type DryRunResult,
} from "../src/migration/dry-run.ts";
import { extractClaudeCode } from "../src/migration/extract/cc.ts";
import { EXTRACTORS } from "../src/migration/extract/index.ts";
import type { ClaimSourceStore, StoreExtraction } from "../src/migration/ledger.ts";
import {
	DEFAULT_SIM_THRESHOLD,
	reconcileLedger,
	type ReconciliationManifest,
} from "../src/migration/reconcile-step.ts";
import { createHttpEmbedder, createPiModelJudge } from "../src/reconcile/index.ts";
import type { Judge, JudgeOutput, ReconcileInput } from "../src/reconcile/index.ts";
import { createPiRegistry, pickModel } from "../src/lib/pi-model.ts";

const HOME = homedir();

function envRoot(key: string, fallback: string): string {
	const v = process.env[key];
	return v && v.trim() ? v : fallback;
}

/** Resolve every source root from env/defaults. claude-code is special: native
 * memory lives under one dir per project, so we return each existing
 * `~/.claude/projects/<slug>/memory` as its own root. */
async function resolveSources(): Promise<{
	singles: Partial<Record<ClaimSourceStore, string>>;
	claudeProjectDirs: string[];
}> {
	const wiki = process.env.DREAM_WIKI_HOME?.trim();
	const singles: Partial<Record<ClaimSourceStore, string>> = {
		pi: envRoot("PI_MEMORY_DIR", join(HOME, ".pi", "agent", "memory")),
		obsidian: wiki ? join(wiki, "memory") : join(HOME, "obsidian", "dream-memory", "memory"),
		codex: envRoot("CODEX_MEMORY_DIR", join(HOME, ".codex", "memories")),
	};

	const projectsRoot = join(HOME, ".claude", "projects");
	const claudeProjectDirs: string[] = [];
	let entries: string[] = [];
	try {
		entries = await readdir(projectsRoot);
	} catch {
		entries = [];
	}
	for (const slug of entries) {
		const memDir = join(projectsRoot, slug, "memory");
		try {
			const st = await readdir(memDir); // throws if absent
			if (st.length > 0) claudeProjectDirs.push(memDir);
		} catch {
			// no memory/ in this project — skip
		}
	}
	return { singles, claudeProjectDirs };
}

/** Extract every store (read-only) and assemble one ledger. claude-code is run
 * once per project dir; each is its own `StoreExtraction` so coverage accounting
 * stays exact per project. */
async function loadLedger(now: string): Promise<DryRunResult> {
	const { singles, claudeProjectDirs } = await resolveSources();
	const extractions: StoreExtraction[] = [];

	for (const store of Object.keys(singles) as ClaimSourceStore[]) {
		const root = singles[store];
		if (!root) continue;
		try {
			extractions.push(await EXTRACTORS[store](root));
		} catch (err) {
			console.warn(`  ! ${store} extract failed at ${root}: ${(err as Error).message}`);
		}
	}
	for (const dir of claudeProjectDirs) {
		try {
			extractions.push(await extractClaudeCode(dir));
		} catch (err) {
			console.warn(`  ! claude-code extract failed at ${dir}: ${(err as Error).message}`);
		}
	}
	return assembleLedger(extractions, now);
}

/** Aggregate per-store claim counts for a human summary (claude-code is split
 * across many extractions in the manifest; collapse it back to one line). */
function storeBreakdown(result: DryRunResult): Map<string, number> {
	const byStore = new Map<string, number>();
	for (const c of result.claims) {
		byStore.set(c.source_store, (byStore.get(c.source_store) ?? 0) + 1);
	}
	return byStore;
}

function tallyReasons(manifest: ReconciliationManifest): Map<string, number> {
	const byReason = new Map<string, number>();
	for (const q of manifest.quarantined) {
		// reasons carry specifics (byte counts); bucket by leading phrase.
		const bucket = q.reason.split("(")[0]?.trim() ?? q.reason;
		byReason.set(bucket, (byReason.get(bucket) ?? 0) + 1);
	}
	return byReason;
}

function histogram(sizes: number[]): string {
	const buckets = new Map<number, number>();
	for (const s of sizes) buckets.set(s, (buckets.get(s) ?? 0) + 1);
	return [...buckets.entries()]
		.sort((a, b) => a[0] - b[0])
		.map(([size, count]) => `${size}-member×${count}`)
		.join(", ");
}

async function main(): Promise<void> {
	const preview = process.argv.includes("--preview") || process.env.RECONCILE_PREVIEW === "1";
	const now = new Date().toISOString();
	const threshold = process.env.DREAM_RECONCILE_THRESHOLD
		? Number(process.env.DREAM_RECONCILE_THRESHOLD)
		: DEFAULT_SIM_THRESHOLD;
	const outDir = envRoot("DREAM_RECONCILE_OUT", join(HOME, ".dream-memory", "migration-reconcile"));

	console.log(`\n=== P2 migration reconcile ${preview ? "(PREVIEW — no judge calls)" : "(FULL RUN)"} ===`);
	console.log(`threshold=${threshold}  out=${outDir}`);

	// 1. Load the real corpus (read-only).
	const t0 = Date.now();
	const ledger = await loadLedger(now);
	console.log(`\nloaded ${ledger.claims.length} claims from ${ledger.manifest.sources.length} source roots in ${Date.now() - t0}ms`);
	for (const [store, n] of storeBreakdown(ledger)) console.log(`  ${store}: ${n}`);
	if (!ledger.complete) {
		const dropped = ledger.coverage.filter((c) => c.unaccounted.length > 0);
		console.warn(`  ! ledger coverage incomplete — ${dropped.length} store(s) have unaccounted files`);
	}

