		const { registry } = await createPiRegistry();
		const model = pickModel(
			registry,
			"sonnet-class",
			process.env.DREAM_RECONCILE_MODEL,
		);
		console.log(`judge model: ${model.provider}/${model.id}`);
		judge = createPiModelJudge({ registry, model });
	}

	// 3. Run the shared reconciler (propose-only).
	const t1 = Date.now();
	const manifest = await reconcileLedger(ledger.claims, { embedder, judge, threshold }, { generatedAt: now });
	console.log(`\nreconcile finished in ${Date.now() - t1}ms`);

	// 4. Report.
	console.log(`\n--- manifest ---`);
	console.log(`total_claims:     ${manifest.total_claims}`);
	console.log(`eligible_claims:  ${manifest.eligible_claims}`);
	console.log(`quarantined:      ${manifest.quarantined.length}`);
	for (const [reason, n] of tallyReasons(manifest)) console.log(`    ${reason}: ${n}`);
	console.log(`exact_dup_groups: ${manifest.stats.exact_dup_groups}`);
	console.log(`clusters_judged:  ${manifest.stats.clusters_judged}`);
	console.log(`judge_failures:   ${manifest.stats.judge_failures}`);
	console.log(`decisions:        merge=${manifest.stats.merges} supersede=${manifest.stats.supersedes} novel=${manifest.stats.novel}`);
	console.log(`complete:         ${manifest.complete}  unaccounted=${manifest.unaccounted.length}  over_disposed=${manifest.over_disposed.length}`);
	if (preview) {
		console.log(`\nPREVIEW: a full run would make ${clusterSizes.length} judge call(s).`);
		if (clusterSizes.length) console.log(`  cluster sizes: ${histogram(clusterSizes)}`);
	}

	// 5. Persist artifacts (outside every source store).
	await mkdir(outDir, { recursive: true });
	const name = preview ? "preview" : "manifest";
	const manifestPath = join(outDir, `${name}.json`);
	await writeFile(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`, "utf8");
	const ledgerPath = join(outDir, "ledger-claims.jsonl");
	await writeFile(ledgerPath, ledger.claims.map((c) => JSON.stringify(c)).join("\n") + "\n", "utf8");
	console.log(`\nwrote ${manifestPath}`);
	console.log(`wrote ${ledgerPath}`);
	if (!preview && !manifest.complete) {
		console.error(`\n! manifest NOT complete — do not apply. Inspect unaccounted/over_disposed before sign-off.`);
		process.exitCode = 1;
	}
}

main().catch((err) => {
	console.error(err);
	process.exit(1);
});

