} from "../src/migration/reconcile-step.ts";
import { createHttpEmbedder, createPiModelJudge } from "../src/reconcile/index.ts";
import type { Judge, JudgeOutput, ReconcileInput } from "../src/reconcile/index.ts";
import { createPiRegistry, pickModel } from "../src/lib/pi-model.ts";

const HOME = homedir();

function envRoot(key: string, fallback: string): string {
	const v = process.env[key];
	return v && v.trim() ? v : fallback;
}

/** Resolve every source root from env/defaults. claude-code is special: native
 * memory lives under one dir per project, so we return each existing
 * `~/.claude/projects/<slug>/memory` as its own root. */
async function resolveSources(): Promise<{
	singles: Partial<Record<ClaimSourceStore, string>>;
	claudeProjectDirs: string[];
}> {
	const wiki = process.env.DREAM_WIKI_HOME?.trim();
	const singles: Partial<Record<ClaimSourceStore, string>> = {
		pi: envRoot("PI_MEMORY_DIR", join(HOME, ".pi", "agent", "memory")),
		obsidian: wiki ? join(wiki, "memory") : join(HOME, "obsidian", "dream-memory", "memory"),
		codex: envRoot("CODEX_MEMORY_DIR", join(HOME, ".codex", "memories")),
	};

	const projectsRoot = join(HOME, ".claude", "projects");
	const claudeProjectDirs: string[] = [];
	let entries: string[] = [];
	try {
		entries = await readdir(projectsRoot);
	} catch {
		entries = [];
	}
	for (const slug of entries) {
		const memDir = join(projectsRoot, slug, "memory");
		try {
			const st = await readdir(memDir); // throws if absent
			if (st.length > 0) claudeProjectDirs.push(memDir);
		} catch {
			// no memory/ in this project — skip
		}
	}
	return { singles, claudeProjectDirs };
}

/** Extract every store (read-only) and assemble one ledger. claude-code is run
 * once per project dir; each is its own `StoreExtraction` so coverage accounting
 * stays exact per project. */
async function loadLedger(now: string): Promise<DryRunResult> {
	const { singles, claudeProjectDirs } = await resolveSources();
	const extractions: StoreExtraction[] = [];

	for (const store of Object.keys(singles) as ClaimSourceStore[]) {
		const root = singles[store];
		if (!root) continue;
		try {
			extractions.push(await EXTRACTORS[store](root));
		} catch (err) {
			console.warn(`  ! ${store} extract failed at ${root}: ${(err as Error).message}`);
		}
	}
	for (const dir of claudeProjectDirs) {
		try {
			extractions.push(await extractClaudeCode(dir));
		} catch (err) {
			console.warn(`  ! claude-code extract failed at ${dir}: ${(err as Error).message}`);
		}
	}
	return assembleLedger(extractions, now);
}

/** Aggregate per-store claim counts for a human summary (claude-code is split
 * across many extractions in the manifest; collapse it back to one line). */
function storeBreakdown(result: DryRunResult): Map<string, number> {
	const byStore = new Map<string, number>();
	for (const c of result.claims) {
		byStore.set(c.source_store, (byStore.get(c.source_store) ?? 0) + 1);
	}
	return byStore;
}

function tallyReasons(manifest: ReconciliationManifest): Map<string, number> {
	const byReason = new Map<string, number>();
	for (const q of manifest.quarantined) {
		// reasons carry specifics (byte counts); bucket by leading phrase.
		const bucket = q.reason.split("(")[0]?.trim() ?? q.reason;
		byReason.set(bucket, (byReason.get(bucket) ?? 0) + 1);
	}
	return byReason;
}

function histogram(sizes: number[]): string {
	const buckets = new Map<number, number>();
	for (const s of sizes) buckets.set(s, (buckets.get(s) ?? 0) + 1);
	return [...buckets.entries()]
		.sort((a, b) => a[0] - b[0])
		.map(([size, count]) => `${size}-member×${count}`)
		.join(", ");
