function storeBreakdown(result: DryRunResult): Map<string, number> {
	const byStore = new Map<string, number>();
	for (const c of result.claims) {
		byStore.set(c.source_store, (byStore.get(c.source_store) ?? 0) + 1);
	}
	return byStore;
}

function tallyReasons(manifest: ReconciliationManifest): Map<string, number> {
	const byReason = new Map<string, number>();
	for (const q of manifest.quarantined) {
		// reasons carry specifics (byte counts); bucket by leading phrase.
		const bucket = q.reason.split("(")[0]?.trim() ?? q.reason;
		byReason.set(bucket, (byReason.get(bucket) ?? 0) + 1);
	}
	return byReason;
}

function histogram(sizes: number[]): string {
	const buckets = new Map<number, number>();
	for (const s of sizes) buckets.set(s, (buckets.get(s) ?? 0) + 1);
	return [...buckets.entries()]
		.sort((a, b) => a[0] - b[0])
		.map(([size, count]) => `${size}-member×${count}`)
		.join(", ");
}

async function main(): Promise<void> {
	const preview = process.argv.includes("--preview") || process.env.RECONCILE_PREVIEW === "1";
	const now = new Date().toISOString();
	const threshold = process.env.DREAM_RECONCILE_THRESHOLD
		? Number(process.env.DREAM_RECONCILE_THRESHOLD)
		: DEFAULT_SIM_THRESHOLD;
	const outDir = envRoot("DREAM_RECONCILE_OUT", join(HOME, ".dream-memory", "migration-reconcile"));

	console.log(`\n=== P2 migration reconcile ${preview ? "(PREVIEW — no judge calls)" : "(FULL RUN)"} ===`);
	console.log(`threshold=${threshold}  out=${outDir}`);

	// 1. Load the real corpus (read-only).
	const t0 = Date.now();
	const ledger = await loadLedger(now);
	console.log(`\nloaded ${ledger.claims.length} claims from ${ledger.manifest.sources.length} source roots in ${Date.now() - t0}ms`);
	for (const [store, n] of storeBreakdown(ledger)) console.log(`  ${store}: ${n}`);
	if (!ledger.complete) {
		const dropped = ledger.coverage.filter((c) => c.unaccounted.length > 0);
		console.warn(`  ! ledger coverage incomplete — ${dropped.length} store(s) have unaccounted files`);
	}

	// 2. Real embedder (MLX) always; judge depends on mode.
	const embedder = createHttpEmbedder();
	const clusterSizes: number[] = [];
	let judge: Judge;
	if (preview) {
		// Counting judge: reuse the real fold→embed→cluster pipeline, but record
		// cluster sizes and return no groups (so a full run's judge-call count and
		// cluster shape are known before spending any quota).
		judge = async (cluster: ReconcileInput[]): Promise<JudgeOutput> => {
			clusterSizes.push(cluster.length);
			return { groups: [] };
		};
	} else {
		const { registry } = await createPiRegistry();
		const model = pickModel(
			registry,
			"sonnet-class",
			process.env.DREAM_RECONCILE_MODEL,
		);
		console.log(`judge model: ${model.provider}/${model.id}`);
		judge = createPiModelJudge({ registry, model });
	}

	// 3. Run the shared reconciler (propose-only).
	const t1 = Date.now();
	const manifest = await reconcileLedger(ledger.claims, { embedder, judge, threshold }, { generatedAt: now });
	console.log(`\nreconcile finished in ${Date.now() - t1}ms`);

	// 4. Report.
	console.log(`\n--- manifest ---`);
	console.log(`total_claims:     ${manifest.total_claims}`);
	console.log(`eligible_claims:  ${manifest.eligible_claims}`);
	console.log(`quarantined:      ${manifest.quarantined.length}`);
	for (const [reason, n] of tallyReasons(manifest)) console.log(`    ${reason}: ${n}`);
	console.log(`exact_dup_groups: ${manifest.stats.exact_dup_groups}`);
	console.log(`clusters_judged:  ${manifest.stats.clusters_judged}`);
	console.log(`judge_failures:   ${manifest.stats.judge_failures}`);
	console.log(`decisions:        merge=${manifest.stats.merges} supersede=${manifest.stats.supersedes} novel=${manifest.stats.novel}`);
	console.log(`complete:         ${manifest.complete}  unaccounted=${manifest.unaccounted.length}  over_disposed=${manifest.over_disposed.length}`);
	if (preview) {
		console.log(`\nPREVIEW: a full run would make ${clusterSizes.length} judge call(s).`);
		if (clusterSizes.length) console.log(`  cluster sizes: ${histogram(clusterSizes)}`);
	}

	// 5. Persist artifacts (outside every source store).
	await mkdir(outDir, { recursive: true });
	const name = preview ? "preview" : "manifest";
	const manifestPath = join(outDir, `${name}.json`);
	await writeFile(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`, "utf8");
	const ledgerPath = join(outDir, "ledger-claims.jsonl");
	await writeFile(ledgerPath, ledger.claims.map((c) => JSON.stringify(c)).join("\n") + "\n", "utf8");
	console.log(`\nwrote ${manifestPath}`);
	console.log(`wrote ${ledgerPath}`);
	if (!preview && !manifest.complete) {
		console.error(`\n! manifest NOT complete — do not apply. Inspect unaccounted/over_disposed before sign-off.`);
		process.exitCode = 1;
	}
}

main().catch((err) => {
	console.error(err);
	process.exit(1);
});

