1	/**
2	 * The `Embedder` seam (ADR 0009 D3): reconcile depends on this interface, never
3	 * on a concrete service. Tests inject a deterministic stub; production wires
4	 * `createHttpEmbedder`, which speaks the same OpenAI wire shape and honours the
5	 * same `DREAM_EMBED_*` env contract as `services/qmd-vector-sidecar/src/embed.ts`
6	 * (the resident local MLX embedder). No new dependency, no API cost.
7	 *
8	 * Documents are embedded as raw text — Qwen3-Embedding's document template is
9	 * the identity `{d}` (per the model card), so reconcile needs no query prefix.
10	 */
11	
12	import type { Embedder } from "./types.ts";
13	
14	/** Cosine similarity of two equal-rank vectors. Returns 0 if either is zero.
15	 * Throws on a dimension mismatch: a ragged embedding would otherwise score as
16	 * near-1 over its shared prefix and silently corrupt clustering — fail loud. */
17	export function cosine(a: number[], b: number[]): number {
18		if (a.length !== b.length) {
19			throw new Error(`cosine: dimension mismatch (${a.length} vs ${b.length})`);
20		}
21		let dot = 0;
22		let na = 0;
23		let nb = 0;
24		for (let i = 0; i < a.length; i++) {
25			const ai = a[i] ?? 0;
26			const bi = b[i] ?? 0;
27			dot += ai * bi;
28			na += ai * ai;
29			nb += bi * bi;
30		}
31		if (na === 0 || nb === 0) return 0;
32		return dot / (Math.sqrt(na) * Math.sqrt(nb));
33	}
34	
35	export type HttpEmbedderOptions = {
36		url?: string;
37		model?: string;
38		batchSize?: number;
39		timeoutMs?: number;
40	};
41	
42	/** Production embedder. Batches at `batchSize`, returns vectors in input order,
43	 * throws on any HTTP/parse failure — the caller is the IO boundary. */
44	export function createHttpEmbedder(options: HttpEmbedderOptions = {}): Embedder {
45		const url =
46			options.url ?? process.env.DREAM_EMBED_URL ?? "http://127.0.0.1:8186/v1/embeddings";
47		const model =
48			options.model ??
49			process.env.DREAM_EMBED_MODEL ??
