/**
 * The `Embedder` seam (ADR 0009 D3): reconcile depends on this interface, never
 * on a concrete service. Tests inject a deterministic stub; production wires
 * `createHttpEmbedder`, which speaks the same OpenAI wire shape and honours the
 * same `DREAM_EMBED_*` env contract as `services/qmd-vector-sidecar/src/embed.ts`
 * (the resident local MLX embedder). No new dependency, no API cost.
 *
 * Documents are embedded as raw text — Qwen3-Embedding's document template is
 * the identity `{d}` (per the model card), so reconcile needs no query prefix.
 */

import type { Embedder } from "./types.ts";

/** Cosine similarity of two equal-rank vectors. Returns 0 if either is zero.
 * Throws on a dimension mismatch: a ragged embedding would otherwise score as
 * near-1 over its shared prefix and silently corrupt clustering — fail loud. */
export function cosine(a: number[], b: number[]): number {
	if (a.length !== b.length) {
		throw new Error(`cosine: dimension mismatch (${a.length} vs ${b.length})`);
	}
	let dot = 0;
	let na = 0;
	let nb = 0;
	for (let i = 0; i < a.length; i++) {
		const ai = a[i] ?? 0;
		const bi = b[i] ?? 0;
		dot += ai * bi;
		na += ai * ai;
		nb += bi * bi;
	}
	if (na === 0 || nb === 0) return 0;
	return dot / (Math.sqrt(na) * Math.sqrt(nb));
}

export type HttpEmbedderOptions = {
	url?: string;
	model?: string;
	batchSize?: number;
	timeoutMs?: number;
};

/** Production embedder. Batches at `batchSize`, returns vectors in input order,
 * throws on any HTTP/parse failure — the caller is the IO boundary. */
export function createHttpEmbedder(options: HttpEmbedderOptions = {}): Embedder {
	const url =
		options.url ?? process.env.DREAM_EMBED_URL ?? "http://127.0.0.1:8186/v1/embeddings";
	const model =
		options.model ??
		process.env.DREAM_EMBED_MODEL ??
		"mlx-community/Qwen3-Embedding-0.6B-4bit-DWQ";
	const batchSize = options.batchSize ?? Number(process.env.DREAM_EMBED_BATCH ?? 32);
	const timeoutMs = options.timeoutMs ?? Number(process.env.DREAM_EMBED_TIMEOUT_MS ?? 30_000);

	return {
		async embed(texts: string[]): Promise<number[][]> {
			if (texts.length === 0) return [];
			const out: number[][] = [];
			for (let i = 0; i < texts.length; i += batchSize) {
				const slice = texts.slice(i, i + batchSize);
				out.push(...(await embedOnce(slice, { url, model, timeoutMs })));
			}
			return out;
		},
	};
}

async function embedOnce(
	inputs: string[],
	cfg: { url: string; model: string; timeoutMs: number },
): Promise<number[][]> {
	const ctrl = new AbortController();
	const timer = setTimeout(() => ctrl.abort(), cfg.timeoutMs);
	try {
		const resp = await fetch(cfg.url, {
			method: "POST",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify({ model: cfg.model, input: inputs }),
			signal: ctrl.signal,
		});
		if (!resp.ok) {
			const body = await resp.text().catch(() => "");
			throw new Error(`embed HTTP ${resp.status}: ${body.slice(0, 300)}`);
		}
		return parseOpenAiEmbeddings(await resp.json());
	} finally {
		clearTimeout(timer);
	}
}

/** Parse an OpenAI `{ data: [{ index, embedding }] }` response into row-ordered
 * vectors. Exported for tests. */
export function parseOpenAiEmbeddings(data: unknown): number[][] {
	if (!isRecord(data) || !Array.isArray(data.data)) {
		throw new Error("embed response shape mismatch (expected OpenAI { data: [...] })");
	}
	const rows = data.data;
	if (!rows.every(isEmbeddingRow)) {
		throw new Error("embed response shape mismatch (expected OpenAI embedding rows)");
	}
	const hasIndexes = rows.every((row) => typeof row.index === "number");
	const ordered = hasIndexes
		? [...rows].sort((a, b) => (a.index as number) - (b.index as number))
		: rows;
	return ordered.map((row) => row.embedding);
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null;
}

function isNumberArray(value: unknown): value is number[] {
	return Array.isArray(value) && value.every((n) => typeof n === "number");
}

function isEmbeddingRow(value: unknown): value is { index?: number; embedding: number[] } {
	return isRecord(value) && isNumberArray(value.embedding);
}

