// Throwaway: validate the real judge path with ONE claude-bridge call.
import { createPiModelJudge } from "../src/reconcile/index.ts";
import type { ReconcileInput } from "../src/reconcile/index.ts";
import { createPiRegistry, pickModel } from "../src/lib/pi-model.ts";

const { registry } = await createPiRegistry();
const model = pickModel(registry, "sonnet-class", process.env.DREAM_RECONCILE_MODEL ?? "claude-bridge/claude-sonnet-4-6");
console.log("model:", model.provider + "/" + model.id);

const judge = createPiModelJudge({ registry, model });
const cluster: ReconcileInput[] = [
	{ id: "x1", content_hash: "h1", scope: "project", source: "pi", title: "cloudflared tunnel egress blocked", text: "agenticmail cloudflared tunnel — port 7844 egress blocked by lue-kube NetworkPolicy; add egress allow." },
	{ id: "x2", content_hash: "h2", scope: "project", source: "obsidian", title: "lue-kube NetworkPolicy Cloudflare Tunnel", text: "lue-kube NetworkPolicy blocked Cloudflare Tunnel egress on 7844; fixed by allowing egress." },
];
const t = Date.now();
const out = await judge(cluster);
console.log("judge ok in", Date.now() - t, "ms");
console.log(JSON.stringify(out, null, 2));

/**
 * Memory reconciliation contract (ADR 0009). The shared core used by BOTH the
 * one-off migration (`reconcileBulk`) and ongoing dream consolidation
 * (`reconcileOne`). Pure types + zod schemas, no IO.
 *
 * Two non-destructive verbs: `merge` (parallel captures of one fact → one
 * canonical record citing all sources) and `supersede` (a new claim corrects an
 * older one; the old is retained but flagged). `novel` keeps a claim as-is.
 * Nothing here ever deletes — the judge proposes; a human gate applies.
 */

import { z } from "zod";

/** The minimal claim shape the reconciler needs — deliberately decoupled from
 * migration's `Claim` so the ingestion path (an `inbox/` event) can map onto the
 * same core. `scope` is the blocking key; `content_hash` is the exact-dup key. */
export type ReconcileInput = {
	id: string;
	text: string;
	content_hash: string;
	scope: string;
	title?: string | undefined;
	/** Provenance label (e.g. source store / harness), surfaced to the judge. */
	source?: string | undefined;
};

// ---------------------------------------------------------------------------
// Decisions — the reconciler's output, one per resolved claim/group.

export const DecisionSchema = z
	.discriminatedUnion("verb", [
		/** Keep the claim as its own canonical record. */
		z.object({ verb: z.literal("novel"), id: z.string().min(1) }),
		/** Parallel captures of one fact: collapse into `canonical_id`, recording
		 * every member (incl. the canonical) as provenance. `basis` distinguishes
		 * exact-hash from judge. `member_ids` are distinct and include the canonical. */
		z.object({
			verb: z.literal("merge"),
			canonical_id: z.string().min(1),
			member_ids: z
				.array(z.string().min(1))
				.min(2)
				.refine((ids) => new Set(ids).size === ids.length, "member_ids must be distinct"),
			basis: z.enum(["exact_hash", "judge"]),
			rationale: z.string().min(1),
		}),
		/** Temporal correction: `new_id` supersedes `superseded_id`. The superseded
		 * record is retained (status flips at apply) but drops out of active recall. */
		z.object({
			verb: z.literal("supersede"),
			new_id: z.string().min(1),
			superseded_id: z.string().min(1),
			rationale: z.string().min(1),
		}),
	])
	.superRefine((d, ctx) => {
		if (d.verb === "merge" && !d.member_ids.includes(d.canonical_id)) {
			ctx.addIssue({ code: z.ZodIssueCode.custom, message: "canonical_id must be among member_ids" });
		}
		if (d.verb === "supersede" && d.new_id === d.superseded_id) {
			ctx.addIssue({ code: z.ZodIssueCode.custom, message: "new_id must differ from superseded_id" });
		}
	});
export type Decision = z.infer<typeof DecisionSchema>;

// ---------------------------------------------------------------------------
// Judge IO — the LLM proposes relations within a candidate cluster.

/** One related group the judge found inside a cluster. `relation: "duplicate"`
 * ⇒ all members state the same fact, keep `canonical_id`. `relation:
 * "supersedes"` ⇒ `canonical_id` is the newer/correcting claim; the other
 * members it supersedes. Members of the cluster absent from every group are
 * distinct (→ novel). */
export const JudgeGroupSchema = z
	.object({
		member_ids: z.array(z.string().min(1)).min(2),
		relation: z.enum(["duplicate", "supersedes"]),
		canonical_id: z.string().min(1),
		rationale: z.string().min(1),
	})
	.refine((g) => new Set(g.member_ids).size === g.member_ids.length, "member_ids must be distinct");
export const JudgeOutputSchema = z.object({
	groups: z.array(JudgeGroupSchema).default([]),
});
export type JudgeOutput = z.infer<typeof JudgeOutputSchema>;

// ---------------------------------------------------------------------------
// Injected seams (tests stub these; production wires the real services).

export type Embedder = { embed(texts: string[]): Promise<number[][]> };
export type Judge = (cluster: ReconcileInput[]) => Promise<JudgeOutput>;

export type Cluster = { scope: string; member_ids: string[] };

export const ReconcileStatsSchema = z.object({
	inputs: z.number().int().nonnegative(),
	exact_dup_groups: z.number().int().nonnegative(),
	clusters_judged: z.number().int().nonnegative(),
	/** Clusters whose judge call threw/parsed-invalid; members fall through to
	 * `novel` (conservative — no silent drop) but a non-zero count signals the
	 * judge is unhealthy and the run should be retried before sign-off. */
	judge_failures: z.number().int().nonnegative(),
	/** Clusters skipped because they exceeded `maxJudgeClusterSize`; members fall
	 * through to `novel` (kept as distinct — no drop). Large clusters are usually
	 * topically-similar-but-distinct families (e.g. codex episodic session logs)
	 * where one mega judge call is both costly and unreliable. */
	clusters_skipped_oversize: z.number().int().nonnegative().default(0),
	merges: z.number().int().nonnegative(),
	supersedes: z.number().int().nonnegative(),
	novel: z.number().int().nonnegative(),
});
export type ReconcileStats = z.infer<typeof ReconcileStatsSchema>;

export type ReconcileResult = {
	decisions: Decision[];
	clusters: Cluster[];
	stats: ReconcileStats;
};

