import { readFileSync, writeFileSync } from "node:fs";

const DIR = "/Users/luke/.dream-memory/migration-reconcile";
const manifest = JSON.parse(readFileSync(`${DIR}/manifest.json`, "utf8"));

// Build claim_id -> claim lookup from the ledger.
const byId = new Map();
for (const line of readFileSync(`${DIR}/ledger-claims.jsonl`, "utf8").split("\n")) {
	if (!line.trim()) continue;
	const c = JSON.parse(line);
	byId.set(c.claim_id, c);
}

const oneLine = (s) => (s ?? "").replace(/\s+/g, " ").trim();
const snippet = (c, n = 140) => {
	if (!c) return "(claim not found)";
	const t = oneLine(c.text);
	return t.length > n ? t.slice(0, n) + "…" : t;
};
const tag = (c) => (c ? `${c.source_store}/${c.scope_hint ?? "?"}` : "?");
const when = (c) => (c?.captured_at ? c.captured_at.slice(0, 10) : "????-??-??");

const out = [];
const w = (s = "") => out.push(s);

const merges = manifest.decisions.filter((d) => d.verb === "merge");
const supersedes = manifest.decisions.filter((d) => d.verb === "supersede");

w(`# P2 reconciliation — sign-off report`);
w("");
w(`Generated: ${manifest.generated_at}  ·  threshold ${manifest.threshold}`);
w(`Corpus: ${manifest.total_claims} claims → ${manifest.eligible_claims} eligible (${manifest.quarantined.length} quarantined)`);
w(`Stats: ${JSON.stringify(manifest.stats)}`);
w(`Accounting: complete=${manifest.complete} unaccounted=${manifest.unaccounted.length} over_disposed=${manifest.over_disposed.length}`);
w("");
w(`**${merges.length} merges · ${supersedes.length} supersedes · ${manifest.stats.novel} novel**`);
w("");
w(`---`);
w("");
w(`## MERGE — ${merges.length} (parallel captures of one fact → one canonical record)`);
w("");
merges.forEach((d, i) => {
	const canon = byId.get(d.canonical_id);
	w(`### M${i + 1}. [${d.basis}] keep \`${d.canonical_id}\` (${tag(canon)})`);
	w(`- **canonical** ${when(canon)} — ${snippet(canon)}`);
	for (const m of d.member_ids.filter((x) => x !== d.canonical_id)) {
		const c = byId.get(m);
		w(`-   merge \`${m}\` (${tag(c)}) ${when(c)} — ${snippet(c)}`);
	}
	w(`- _rationale:_ ${oneLine(d.rationale)}`);
	w("");
});
w(`---`);
w("");
w(`## SUPERSEDE — ${supersedes.length} (newer claim corrects an older one; old retained, dropped from recall)`);
w("");
supersedes.forEach((d, i) => {
	const nw = byId.get(d.new_id);
	const old = byId.get(d.superseded_id);
	w(`### S${i + 1}. \`${d.new_id}\` supersedes \`${d.superseded_id}\``);
	w(`- **new** (${tag(nw)}) ${when(nw)} — ${snippet(nw)}`);
	w(`- ~~old~~ (${tag(old)}) ${when(old)} — ${snippet(old)}`);
	w(`- _rationale:_ ${oneLine(d.rationale)}`);
	w("");
});

writeFileSync(`${DIR}/SIGNOFF.md`, out.join("\n"));
console.log(`wrote ${DIR}/SIGNOFF.md  (${out.length} lines)`);
console.log(`merges=${merges.length} supersedes=${supersedes.length} novel=${manifest.stats.novel}`);

