1	/**
2	 * P2 claim-level migration ledger — the data contract (issue #382, design
3	 * `docs/specs/p2-claim-ledger-design.md`).
4	 *
5	 * A {@link Claim} is an atomic, content-addressed span of a legacy memory store.
6	 * The migration maps every claim to exactly one of {canonical record, conflict
7	 * group, quarantine} — so "no data lost" is proven by *claim* coverage, not file
8	 * counts. claim_id is derived deterministically (never LLM-invented) so reruns
9	 * are idempotent. Pure: hashing + zod, no IO.
10	 */
11	
12	import { createHash } from "node:crypto";
13	import { z } from "zod";
14	
15	/** The four physical legacy roots. Distinct from the canonical `SourceStoreSchema`
16	 * (which also splits `codex-memories`/`chronicle`); the reconciler (P2b) maps a
17	 * claim's physical store to a canonical provenance store when it writes. */
18	export const CLAIM_SOURCE_STORES = ["pi", "obsidian", "claude-code", "codex"] as const;
19	export type ClaimSourceStore = (typeof CLAIM_SOURCE_STORES)[number];
20	
21	/** A claim's location within its source file: the whole file, or a byte range
22	 * (chunked big files). Sections of one file are contiguous + gap-free. */
23	export const SpanSchema = z.discriminatedUnion("kind", [
24		z.object({ kind: z.literal("whole") }),
25		z.object({
26			kind: z.literal("section"),
27			start: z.number().int().nonnegative(),
28			end: z.number().int().nonnegative(),
29			heading: z.string().min(1).optional(),
30		}),
31	]);
32	export type Span = z.infer<typeof SpanSchema>;
33	
34	export const SCOPE_HINTS = ["profile", "project", "reference", "tool", "episodic", "inbox", "unknown"] as const;
35	export const ScopeHintSchema = z.enum(SCOPE_HINTS);
36	export type ScopeHint = z.infer<typeof ScopeHintSchema>;
37	
38	export const ClaimSchema = z.object({
39		claim_id: z.string().min(1),
40		source_store: z.enum(CLAIM_SOURCE_STORES),
41		/** Root-relative path within the source store. */
42		source_path: z.string().min(1),
43		span: SpanSchema,
44		/** sha256 of the normalised claim text — the dedup / idempotency key. */
45		content_hash: z.string().min(1),
46		captured_at: z.string().min(1).optional(),
47		scope_hint: ScopeHintSchema,
48		project_slug: z.string().min(1).optional(),
49		title: z.string().min(1).optional(),
50		/** The raw claim text (frontmatter + body, or the section slice). */
51		text: z.string(),
52		/** Raw parsed frontmatter, retained for audit/reconciliation. */
53		origin_meta: z.record(z.unknown()).optional(),
54	});
55	export type Claim = z.infer<typeof ClaimSchema>;
56	
57	// ---------------------------------------------------------------------------
58	// Deterministic derivation
59	
60	/** Normalise for stable hashing: CRLF→LF, strip per-line trailing whitespace,
61	 * trim leading/trailing blank lines. Two byte-different-but-semantically-equal
62	 * captures hash identically. */
63	export function normaliseText(text: string): string {
64		return text
65			.replace(/\r\n?/g, "\n")
66			.split("\n")
67			.map((line) => line.replace(/[ \t]+$/, ""))
68			.join("\n")
69			.replace(/^\n+/, "")
70			.replace(/\n+$/, "");
71	}
72	
73	export function contentHash(text: string): string {
74		return createHash("sha256").update(normaliseText(text)).digest("hex");
75	}
76	
77	/** Stable string form of a span, for the claim_id pre-image. */
78	export function spanKey(span: Span): string {
79		return span.kind === "whole" ? "whole" : `section:${span.start}-${span.end}`;
80	}
81	
82	/** Content-addressed claim id: sha256 over the locating tuple, hex-truncated.
83	 * Same source span + same content ⇒ same id across runs (idempotency). */
84	export function deriveClaimId(
85		source_store: ClaimSourceStore,
86		source_path: string,
87		span: Span,
88		content_hash: string,
89	): string {
90		// NUL-join (the \u0000 escape, never a raw NUL — a raw NUL byte makes git
91		// treat this source file as binary). NUL is the one byte a path can't
92		// contain, so distinct tuples can't alias: a space join would let path "a b"
93		// + span "whole" collide with path "a" + span "b whole".
94		const preimage = [source_store, source_path, spanKey(span), content_hash].join("\u0000");
95		return createHash("sha256").update(preimage).digest("hex").slice(0, 32);
96	}
97	
98	/** Claim fields the extractor supplies; `content_hash`/`claim_id` are derived.
99	 * Optionals admit `undefined` explicitly so call sites can pass a maybe-absent
100	 * value without an `exactOptionalPropertyTypes` dance. */
101	export type ClaimInput = {
102		source_store: ClaimSourceStore;
103		source_path: string;
104		span: Span;
105		scope_hint: ScopeHint;
106		text: string;
107		captured_at?: string | undefined;
108		project_slug?: string | undefined;
109		title?: string | undefined;
110		origin_meta?: Record<string, unknown> | undefined;
111	};
112	
113	/** Build a validated claim, deriving `content_hash` + `claim_id` from `text`.
114	 * Undefined optionals are dropped so the parsed record stays clean. */
115	export function makeClaim(input: ClaimInput): Claim {
116		const content_hash = contentHash(input.text);
117		const claim_id = deriveClaimId(input.source_store, input.source_path, input.span, content_hash);
118		const candidate: Record<string, unknown> = { ...input, content_hash, claim_id };
119		for (const k of Object.keys(candidate)) if (candidate[k] === undefined) delete candidate[k];
120		return ClaimSchema.parse(candidate);
121	}
122	
123	// ---------------------------------------------------------------------------
124	// Ledger manifest (the no-drops accounting)
125	
126	/** A source file skipped during extraction, with the reason — so every source
127	 * file is accounted for as either a claim source or an explicit skip. */
128	export const SkippedSchema = z.object({
129		source_store: z.enum(CLAIM_SOURCE_STORES),
130		path: z.string().min(1),
131		reason: z.string().min(1),
132	});
133	export type Skipped = z.infer<typeof SkippedSchema>;
134	
135	export const SourceSummarySchema = z.object({
136		source_store: z.enum(CLAIM_SOURCE_STORES),
137		root: z.string().min(1),
138		file_count: z.number().int().nonnegative(),
139		claim_count: z.number().int().nonnegative(),
140	});
141	export type SourceSummary = z.infer<typeof SourceSummarySchema>;
142	
143	export const LedgerManifestSchema = z.object({
144		version: z.literal(1),
145		generated_at: z.string().min(1),
146		sources: z.array(SourceSummarySchema),
147		total_claims: z.number().int().nonnegative(),
148		skipped: z.array(SkippedSchema),
149	});
150	export type LedgerManifest = z.infer<typeof LedgerManifestSchema>;
151	
152	/** One store's extraction output: its claims + the files it deliberately skipped. */
153	export type StoreExtraction = {
154		source_store: ClaimSourceStore;
155		root: string;
156		/** Every file the extractor saw (claim sources ∪ skips must equal this set). */
157		files_seen: string[];
158		claims: Claim[];
159		skipped: Skipped[];
160	};
161

