1	/**
2	 * Migration parse helpers — frontmatter + markdown section chunking.
3	 *
4	 * Deliberately small: the legacy stores use a narrow YAML subset (flat
5	 * `key: value`, string-arrays, one level of nesting for `metadata:`) and
6	 * heading-delimited sections. A full YAML/Markdown parser would be overkill and
7	 * a new dependency. Pure: string ops only.
8	 *
9	 * Span offsets are **code-unit offsets into the decoded text** (what `String`
10	 * slicing uses), so a span always round-trips: `text.slice(start, end)`.
11	 */
12	
13	export type Frontmatter = { data: Record<string, unknown>; body: string };
14	
15	const FRONTMATTER = /^---\r?\n([\s\S]*?)\r?\n---[ \t]*\r?\n?/;
16	
17	/** Parse leading `---`-delimited frontmatter. Returns `{}` data + the original
18	 * text as body when absent. Supports flat scalars, `- ` string lists, and a
19	 * single level of nested maps (e.g. CC's `metadata:`). */
20	export function parseFrontmatter(text: string): Frontmatter {
21		const m = FRONTMATTER.exec(text);
22		if (!m) return { data: {}, body: text };
23		return { data: parseYamlSubset(m[1] ?? ""), body: text.slice(m[0].length) };
24	}
25	
26	function unquote(raw: string): string {
27		const v = raw.trim();
28		if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) {
29			return v.slice(1, -1).replace(/\\"/g, '"').replace(/\\\\/g, "\\");
30		}
31		return v;
32	}
33	
34	/** A block-scalar header value: `|`, `>`, with optional chomp/indent indicators
35	 * (`|-`, `>+`, `|2`, `|2-`). Its body is indented lines we must NOT parse as
36	 * keys (else an indented `type:` inside a multi-line `description: |` hoists to
37	 * a top-level `type`, corrupting the scope hint). */
38	const BLOCK_SCALAR = /^[|>](?:[+-]?\d?|\d?[+-]?)$/;
39	
40	function parseYamlSubset(src: string): Record<string, unknown> {
41		const data: Record<string, unknown> = {};
42		let lastKey: string | null = null;
43		let nested: Record<string, string> | null = null;
44		let inBlock = false;
45		for (const rawLine of src.split("\n")) {
46			const indented = /^\s/.test(rawLine);
47			if (inBlock) {
48				// block-scalar body: blank or indented lines belong to the value
49				if (!rawLine.trim() || indented) continue;
50				inBlock = false; // dedented → block ended; parse this line normally
51			}
52			if (!rawLine.trim()) continue;
53			const line = rawLine.trim();
54	
55			// `- item` under the last top-level key → string list
56			const listItem = /^-\s+(.*)$/.exec(line);
57			if (indented && listItem && lastKey) {
58				const arr = Array.isArray(data[lastKey]) ? (data[lastKey] as string[]) : [];
59				arr.push(unquote(listItem[1] ?? ""));
60				data[lastKey] = arr;
61				continue;
62			}
63	
64			const kv = /^([A-Za-z0-9_-]+):\s*(.*)$/.exec(line);
65			if (!kv) continue;
66			const key = kv[1] ?? "";
67			const value = kv[2] ?? "";
68	
