/**
 * Migration parse helpers — frontmatter + markdown section chunking.
 *
 * Deliberately small: the legacy stores use a narrow YAML subset (flat
 * `key: value`, string-arrays, one level of nesting for `metadata:`) and
 * heading-delimited sections. A full YAML/Markdown parser would be overkill and
 * a new dependency. Pure: string ops only.
 *
 * Span offsets are **code-unit offsets into the decoded text** (what `String`
 * slicing uses), so a span always round-trips: `text.slice(start, end)`.
 */

export type Frontmatter = { data: Record<string, unknown>; body: string };

const FRONTMATTER = /^---\r?\n([\s\S]*?)\r?\n---[ \t]*\r?\n?/;

/** Parse leading `---`-delimited frontmatter. Returns `{}` data + the original
 * text as body when absent. Supports flat scalars, `- ` string lists, and a
 * single level of nested maps (e.g. CC's `metadata:`). */
export function parseFrontmatter(text: string): Frontmatter {
	const m = FRONTMATTER.exec(text);
	if (!m) return { data: {}, body: text };
	return { data: parseYamlSubset(m[1] ?? ""), body: text.slice(m[0].length) };
}

function unquote(raw: string): string {
	const v = raw.trim();
	if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) {
		return v.slice(1, -1).replace(/\\"/g, '"').replace(/\\\\/g, "\\");
	}
	return v;
}

/** A block-scalar header value: `|`, `>`, with optional chomp/indent indicators
 * (`|-`, `>+`, `|2`, `|2-`). Its body is indented lines we must NOT parse as
 * keys (else an indented `type:` inside a multi-line `description: |` hoists to
 * a top-level `type`, corrupting the scope hint). */
const BLOCK_SCALAR = /^[|>](?:[+-]?\d?|\d?[+-]?)$/;

function parseYamlSubset(src: string): Record<string, unknown> {
	const data: Record<string, unknown> = {};
	let lastKey: string | null = null;
	let nested: Record<string, string> | null = null;
	let inBlock = false;
	for (const rawLine of src.split("\n")) {
		const indented = /^\s/.test(rawLine);
		if (inBlock) {
			// block-scalar body: blank or indented lines belong to the value
			if (!rawLine.trim() || indented) continue;
			inBlock = false; // dedented → block ended; parse this line normally
		}
		if (!rawLine.trim()) continue;
		const line = rawLine.trim();

		// `- item` under the last top-level key → string list
		const listItem = /^-\s+(.*)$/.exec(line);
		if (indented && listItem && lastKey) {
			const arr = Array.isArray(data[lastKey]) ? (data[lastKey] as string[]) : [];
			arr.push(unquote(listItem[1] ?? ""));
			data[lastKey] = arr;
			continue;
		}

		const kv = /^([A-Za-z0-9_-]+):\s*(.*)$/.exec(line);
		if (!kv) continue;
		const key = kv[1] ?? "";
		const value = kv[2] ?? "";

		if (indented && nested) {
			// nested map entry under the last empty top-level key
			nested[key] = unquote(value);
			continue;
		}

		// top-level key
		lastKey = key;
		nested = null;
		if (value === "") {
			// could open a list or a nested map; commit a nested object lazily
			nested = {};
			data[key] = nested;
		} else if (BLOCK_SCALAR.test(value)) {
			// block scalar: keep the indicator, skip its indented body
			data[key] = value;
			inBlock = true;
		} else {
			data[key] = unquote(value);
		}
	}
	// drop empty nested objects that turned out to be list anchors handled above
	for (const [k, v] of Object.entries(data)) {
		if (v && typeof v === "object" && !Array.isArray(v) && Object.keys(v).length === 0) delete data[k];
	}
	return data;
}

// ---------------------------------------------------------------------------
// Section chunking

