/**
 * Canonical record serializer — {@link CanonicalFrontmatter} + body → a Markdown
 * file string. The inverse of `migration/parse.ts`'s `parseFrontmatter`.
 *
 * Hand-rolled to match the repo's no-YAML-dependency convention. It emits
 * exactly the narrow YAML subset `parseYamlSubset` understands, so every record
 * this writes round-trips back through `parseFrontmatter` → `CanonicalFrontmatterSchema`:
 * JSON-quoted scalars (mirroring `dream/patch-applier.ts`'s `serialise`), block
 * `- ` string lists, and `provenance` as the one nested map (the single level of
 * nesting the parser supports, mirroring CC's `metadata:`). Pure: string ops only.
 */

import type { CanonicalFrontmatter } from "./frontmatter.ts";

/** Scalar fields, in a stable, diff-friendly order. All are required-after-parse
 * strings on the schema (`status` via its default). */
const SCALAR_ORDER = [
	"title",
	"permalink",
	"origin",
	"visibility",
	"sensitivity",
	"scope",
	"confidence",
	"status",
] as const;

/** Provenance sub-keys, stable order; absent optionals are omitted. */
const PROVENANCE_ORDER = [
	"source_store",
	"source_path",
	"source_span",
	"source_content_hash",
	"source_record_id",
	"migration_batch_id",
	"first_seen",
	"last_seen",
	"capture_mechanism",
] as const;

function stringArrayLines(key: string, items: readonly string[]): string[] {
	return [`${key}:`, ...items.map((item) => `  - ${JSON.stringify(item)}`)];
}

function provenanceLines(provenance: CanonicalFrontmatter["provenance"]): string[] {
	const lines = ["provenance:"];
	const record = provenance as Record<string, unknown>;
	for (const key of PROVENANCE_ORDER) {
		const value = record[key];
		if (typeof value === "string" && value.length > 0) {
			lines.push(`  ${key}: ${JSON.stringify(value)}`);
		}
	}
	return lines;
}

/** Serialize a canonical record to its on-disk Markdown form. */
export function serializeCanonical(frontmatter: CanonicalFrontmatter, body: string): string {
	const lines: string[] = ["---"];

	for (const key of SCALAR_ORDER) {
		const value = frontmatter[key];
		if (typeof value === "string" && value.length > 0) {
			lines.push(`${key}: ${JSON.stringify(value)}`);
		}
	}

	lines.push(...provenanceLines(frontmatter.provenance));

	// Optional string-array edges — emitted only when non-empty so absent edges
	// don't litter the file (and so the parser never sees an empty `key:` anchor).
	if (frontmatter.merged_from?.length) lines.push(...stringArrayLines("merged_from", frontmatter.merged_from));
	if (frontmatter.supersedes?.length) lines.push(...stringArrayLines("supersedes", frontmatter.supersedes));
	if (frontmatter.superseded_by?.length) lines.push(...stringArrayLines("superseded_by", frontmatter.superseded_by));
	if (frontmatter.links?.length) lines.push(...stringArrayLines("links", frontmatter.links));
	if (frontmatter.relates?.length) lines.push(...stringArrayLines("relates", frontmatter.relates));

	lines.push("---", "");
	return `${lines.join("\n")}${body.replace(/\s*$/, "")}\n`;
}

