import { describe, expect, it } from "vitest";

import { CanonicalFrontmatterSchema } from "../src/canonical/frontmatter.ts";
import { serializeCanonical } from "../src/canonical/serialize.ts";
import { parseFrontmatter } from "../src/migration/parse.ts";

/** Parse a serialized record back into a validated frontmatter object. */
function roundTrip(fm: ReturnType<typeof CanonicalFrontmatterSchema.parse>, body: string) {
	const text = serializeCanonical(fm, body);
	const parsed = parseFrontmatter(text);
	return { text, body: parsed.body, fm: CanonicalFrontmatterSchema.parse(parsed.data) };
}

const base = {
	title: "lue-kube NetworkPolicy blocked Cloudflare Tunnel egress",
	permalink: "lue-kube-networkpolicy-tunnel-abc12345",
	origin: "pi" as const,
	visibility: "private",
	sensitivity: "private" as const,
	scope: "project:lue-kube",
	confidence: "extracted" as const,
	provenance: {
		source_store: "obsidian" as const,
		source_path: "memory/project/lue-kube-networkpolicy.md",
		source_content_hash: "deadbeef",
		capture_mechanism: "dream" as const,
	},
};

describe("serializeCanonical — round-trips through parseFrontmatter", () => {
	it("a plain active record survives serialize → parse → schema", () => {
		const fm = CanonicalFrontmatterSchema.parse(base);
		const { fm: out, body } = roundTrip(fm, "The egress block on port 7844 was fixed by adding an allow rule.");
		expect(out).toEqual(fm);
		expect(out.status).toBe("active");
		expect(body).toBe("The egress block on port 7844 was fixed by adding an allow rule.");
	});

	it("preserves the nested provenance map exactly", () => {
		const fm = CanonicalFrontmatterSchema.parse(base);
		const { fm: out } = roundTrip(fm, "body");
		expect(out.provenance).toEqual(base.provenance);
	});

	it("carries merge provenance (merged_from)", () => {
		const fm = CanonicalFrontmatterSchema.parse({
			...base,
			merged_from: ["hash-of-member-a", "hash-of-member-b"],
		});
		const { fm: out } = roundTrip(fm, "merged canonical record");
		expect(out.merged_from).toEqual(["hash-of-member-a", "hash-of-member-b"]);
	});

	it("carries a superseded record's status + reverse edge", () => {
		const fm = CanonicalFrontmatterSchema.parse({
			...base,
			status: "superseded",
			superseded_by: ["newer-record-permalink"],
		});
		const { fm: out } = roundTrip(fm, "old, corrected truth");
		expect(out.status).toBe("superseded");
		expect(out.superseded_by).toEqual(["newer-record-permalink"]);
	});

	it("omits absent optional edges (no empty anchors)", () => {
		const fm = CanonicalFrontmatterSchema.parse(base);
		const text = serializeCanonical(fm, "body");
		expect(text).not.toContain("merged_from:");
		expect(text).not.toContain("superseded_by:");
		expect(text).not.toContain("links:");
	});
});

