10	 * common AWS keys, and inline `*_KEY|_SECRET|_TOKEN|_PASSWORD = ...` env
11	 * assignments. Add new patterns here, never silently in callers.
12	 */
13	
14	export type RedactionHit = {
15		pattern: string;
16		count: number;
17	};
18	
19	export type RedactResult<T> = {
20		value: T;
21		hits: RedactionHit[];
22		hitCount: number;
23	};
24	
25	const REPLACEMENT = "[REDACTED:%s]";
26	
27	type Pattern = { name: string; re: RegExp };
28	
29	// All patterns are case-sensitive on the secret prefix and word-bounded so
30	// that prose mentioning "Bearer-style auth" doesn't false-positive.
31	const PATTERNS: Pattern[] = [
32		// OpenAI / Anthropic-style sk- keys (e.g. sk-ant-..., sk-proj-...)
33		{ name: "openai-sk", re: /\bsk-[A-Za-z0-9_\-]{20,}\b/g },
34		// GitHub PATs and tokens: ghp_, gho_, ghu_, ghs_, ghr_
35		{ name: "github-token", re: /\bgh[pousr]_[A-Za-z0-9]{20,}\b/g },
36		// 1Password secret references: op://vault/item/field
37		{ name: "1password-ref", re: /\bop:\/\/[^\s"'`]+/g },
38		// JWTs: three base64url segments separated by '.'
39		{ name: "jwt", re: /\beyJ[A-Za-z0-9_\-]{6,}\.[A-Za-z0-9_\-]{6,}\.[A-Za-z0-9_\-]{6,}\b/g },
40		// Authorization: Bearer <token>
41		{ name: "bearer", re: /\bBearer\s+[A-Za-z0-9._~+/=\-]{20,}/g },
42		// AWS access key ID (deterministic shape)
43		{ name: "aws-akid", re: /\bAKIA[0-9A-Z]{16}\b/g },
44		// Inline env-style secret assignments: FOO_API_KEY=..., MY_SECRET: "..."
45		// Match the *value* and replace it; we keep the key visible for context.
46		{
47			name: "env-secret",
48			re: /\b([A-Z][A-Z0-9_]*(?:KEY|SECRET|TOKEN|PASSWORD|PASSWD|API_KEY))\s*[:=]\s*["']?([^\s"'`]{4,})["']?/g,
49		},
50	];
51	
52	function redactString(input: string): { value: string; hits: RedactionHit[] } {
53		let value = input;
54		const hits: RedactionHit[] = [];
55		for (const p of PATTERNS) {
56			// Reset lastIndex defensively — these regexes are global.
57			p.re.lastIndex = 0;
58			let count = 0;
59			if (p.name === "env-secret") {
60				value = value.replace(p.re, (_m, key) => {
61					count += 1;
62					return `${key}=${REPLACEMENT.replace("%s", p.name)}`;
63				});
64			} else {
65				value = value.replace(p.re, () => {
66					count += 1;
67					return REPLACEMENT.replace("%s", p.name);
68				});
69			}
