 * common AWS keys, and inline `*_KEY|_SECRET|_TOKEN|_PASSWORD = ...` env
 * assignments. Add new patterns here, never silently in callers.
 */

export type RedactionHit = {
	pattern: string;
	count: number;
};

export type RedactResult<T> = {
	value: T;
	hits: RedactionHit[];
	hitCount: number;
};

const REPLACEMENT = "[REDACTED:%s]";

type Pattern = { name: string; re: RegExp };

// All patterns are case-sensitive on the secret prefix and word-bounded so
// that prose mentioning "Bearer-style auth" doesn't false-positive.
const PATTERNS: Pattern[] = [
	// OpenAI / Anthropic-style sk- keys (e.g. sk-ant-..., sk-proj-...)
	{ name: "openai-sk", re: /\bsk-[A-Za-z0-9_\-]{20,}\b/g },
	// GitHub PATs and tokens: ghp_, gho_, ghu_, ghs_, ghr_
	{ name: "github-token", re: /\bgh[pousr]_[A-Za-z0-9]{20,}\b/g },
	// 1Password secret references: op://vault/item/field
	{ name: "1password-ref", re: /\bop:\/\/[^\s"'`]+/g },
	// JWTs: three base64url segments separated by '.'
	{ name: "jwt", re: /\beyJ[A-Za-z0-9_\-]{6,}\.[A-Za-z0-9_\-]{6,}\.[A-Za-z0-9_\-]{6,}\b/g },
	// Authorization: Bearer <token>
	{ name: "bearer", re: /\bBearer\s+[A-Za-z0-9._~+/=\-]{20,}/g },
	// AWS access key ID (deterministic shape)
	{ name: "aws-akid", re: /\bAKIA[0-9A-Z]{16}\b/g },
	// Inline env-style secret assignments: FOO_API_KEY=..., MY_SECRET: "..."
	// Match the *value* and replace it; we keep the key visible for context.
	{
		name: "env-secret",
		re: /\b([A-Z][A-Z0-9_]*(?:KEY|SECRET|TOKEN|PASSWORD|PASSWD|API_KEY))\s*[:=]\s*["']?([^\s"'`]{4,})["']?/g,
	},
];

function redactString(input: string): { value: string; hits: RedactionHit[] } {
	let value = input;
	const hits: RedactionHit[] = [];
	for (const p of PATTERNS) {
		// Reset lastIndex defensively — these regexes are global.
		p.re.lastIndex = 0;
		let count = 0;
		if (p.name === "env-secret") {
			value = value.replace(p.re, (_m, key) => {
				count += 1;
				return `${key}=${REPLACEMENT.replace("%s", p.name)}`;
			});
		} else {
			value = value.replace(p.re, () => {
				count += 1;
				return REPLACEMENT.replace("%s", p.name);
			});
		}
		if (count > 0) hits.push({ pattern: p.name, count });
	}
	return { value, hits };
}

/**
 * Recursively redact a JSON-like value. Strings are scanned; objects/arrays
 * are walked. Other primitives pass through. Returns a new value plus the
 * aggregated hit list.
 */
export function redact<T>(input: T): RedactResult<T> {
	const aggregate = new Map<string, number>();

	const walk = (v: unknown): unknown => {
		if (typeof v === "string") {
			const { value, hits } = redactString(v);
			for (const h of hits) {
				aggregate.set(h.pattern, (aggregate.get(h.pattern) ?? 0) + h.count);
			}
			return value;
		}
		if (Array.isArray(v)) return v.map(walk);
		if (v && typeof v === "object") {
			const out: Record<string, unknown> = {};
			for (const [k, val] of Object.entries(v as Record<string, unknown>)) {
				out[k] = walk(val);
			}
			return out;
		}
		return v;
	};

	const value = walk(input) as T;
	const hits: RedactionHit[] = [...aggregate.entries()].map(([pattern, count]) => ({
		pattern,
		count,
	}));
	const hitCount = hits.reduce((a, b) => a + b.count, 0);
	return { value, hits, hitCount };
}

/**
 * Strict variant for the dream LLM pre-flight: throws if any pattern matches.
 * Fail closed — we never ship raw secrets to a remote model.
 */
export function assertRedacted<T>(input: T, where: string): T {
	const { hitCount, hits } = redact(input);
	if (hitCount > 0) {
		const summary = hits.map((h) => `${h.pattern}×${h.count}`).join(", ");
		throw new Error(`redaction tripped in ${where}: ${summary}`);
	}
	return input;
}

