/**
 * Claim → canonical record mapping (P2c apply, ADR 0009 / spec P2).
 *
 * The first writer of real canonical records. Turns a legacy {@link Claim} into a
 * {@link CanonicalRecord}: structured frontmatter + body + a content-addressed
 * permalink + a target path within the two-root canonical store.
 *
 * The mapping is **conservative and reversible**, pinned by spec/ADR — it makes
 * no cross-harness or sharing decisions (P4 owns those):
 *  - `origin` is the capturing harness (`obsidian` is Pi's dream wiki → `pi`).
 *  - `visibility` is always `private`; a later classification pass promotes to
 *    `shared`. So every migrated record lands in `harness/<origin>/` (X-specific),
 *    never `shared/`, except episodic captures which land in `episodic/`.
 *  - `sensitivity` is `secret` iff a secret/PII pattern matches (the body is kept
 *    intact on disk; redaction happens at index/inject time — spec M3), else `private`.
 *  - `permalink` is content-addressed (`slug-<claim_id[:8]>`) — never LLM-invented,
 *    so reruns are idempotent (spec P2).
 *  - `scope` follows the claim's scope hint / project slug; unknowns fall to `profile`.
 * Pure: no IO.
 */

import { z } from "zod";

import {
	type CanonicalFrontmatter,
	CanonicalFrontmatterSchema,
	type CaptureMechanismSchema,
	type OriginSchema,
	type SourceStoreSchema,
} from "../../canonical/frontmatter.ts";
import { redact } from "../../redact.ts";
import { type Claim, type ClaimSourceStore, spanKey } from "../ledger.ts";
import { parseFrontmatter } from "../parse.ts";

type Origin = z.infer<typeof OriginSchema>;
type SourceStore = z.infer<typeof SourceStoreSchema>;
type CaptureMechanism = z.infer<typeof CaptureMechanismSchema>;

/** Which canonical root a record belongs to. */
export type RootKind = "global" | "project";

/** A canonical record, resolved enough to write: frontmatter + body + the path
 * within its root. `claim_id` is the source disposition this record realises
 * (apply accounting joins on it). */
export type CanonicalRecord = {
	claim_id: string;
	permalink: string;
	rootKind: RootKind;
	/** Set iff `rootKind === "project"`. */
	projectSlug?: string;
	/** Path within the root, e.g. `harness/pi/<permalink>.md` or `episodic/<permalink>.md`. */
	relPath: string;
	frontmatter: CanonicalFrontmatter;
	body: string;
};

/** Legacy physical store → the capturing harness (`origin`). Obsidian is Pi's
 * dream wiki, so it originates as `pi`. */
const ORIGIN_BY_STORE: Record<ClaimSourceStore, Origin> = {
	pi: "pi",
	obsidian: "pi",
	"claude-code": "claude-code",
	codex: "codex",
};

/** Legacy physical store → the finer canonical provenance store. */
const PROVENANCE_STORE_BY_STORE: Record<ClaimSourceStore, SourceStore> = {
	pi: "pi",
	obsidian: "obsidian",
	"claude-code": "claude-code",
	codex: "codex-memories",
};

/** How the source originally captured the fact. */
const CAPTURE_BY_STORE: Record<ClaimSourceStore, CaptureMechanism> = {
	pi: "native",
	obsidian: "dream",
	"claude-code": "native",
	codex: "native",
};

/** Obsidian notes are already dream-consolidated; everything else is raw extract. */
function confidenceFor(store: ClaimSourceStore): CanonicalFrontmatter["confidence"] {
	return store === "obsidian" ? "consolidated" : "extracted";
}

/** Slugify a title for the permalink stem: lowercase, non-alphanumeric → `-`,
 * collapse, trim, cap length. Empty → `untitled`. */
function slugify(title: string): string {
	const slug = title
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, "-")
		.replace(/^-+|-+$/g, "")
		.slice(0, 60)
		.replace(/-+$/g, "");
	return slug.length > 0 ? slug : "untitled";
}

/** Title from the claim, else the first heading / first non-empty body line. */
function deriveTitle(claim: Claim, body: string): string {
	if (claim.title && claim.title.trim().length > 0) return claim.title.trim();
	for (const raw of body.split("\n")) {
		const line = raw.replace(/^#+\s*/, "").trim();
		if (line.length > 0) return line.slice(0, 120);
	}
	return "Untitled";
}

/** `scope` frontmatter from the claim's hint + project slug. Unknowns → profile. */
function scopeFor(claim: Claim): string {
	if (claim.project_slug && claim.project_slug.trim().length > 0) {
		return `project:${claim.project_slug.trim()}`;
	}
	return "profile";
}

export type MapClaimOptions = { migrationBatchId?: string | undefined };

/** Map one claim to its canonical record. */
export function claimToCanonical(claim: Claim, opts: MapClaimOptions = {}): CanonicalRecord {
	const origin = ORIGIN_BY_STORE[claim.source_store];
	const body = parseFrontmatter(claim.text).body.trim() || claim.text.trim();
	const title = deriveTitle(claim, body);
	const permalink = `${slugify(title)}-${claim.claim_id.slice(0, 8)}`;
	const scope = scopeFor(claim);
	const sensitivity = redact(claim.text).hitCount > 0 ? "secret" : "private";

	const provenance: CanonicalFrontmatter["provenance"] = {
		source_store: PROVENANCE_STORE_BY_STORE[claim.source_store],
		source_path: claim.source_path,
		source_content_hash: claim.content_hash,
		source_record_id: claim.claim_id,
		capture_mechanism: CAPTURE_BY_STORE[claim.source_store],
		...(claim.span.kind === "section" ? { source_span: spanKey(claim.span) } : {}),
		...(claim.captured_at ? { first_seen: claim.captured_at } : {}),
		...(opts.migrationBatchId ? { migration_batch_id: opts.migrationBatchId } : {}),
	};

	const frontmatter = CanonicalFrontmatterSchema.parse({
		title,
		permalink,
		origin,
		visibility: "private",
		sensitivity,
		scope,
		confidence: confidenceFor(claim.source_store),
		status: "active",
		provenance,
	});

	// Placement: episodic captures → episodic/; everything else is origin-private
	// → harness/<origin>/. shared/ is reserved for P4 promotion.
	const dir = claim.scope_hint === "episodic" ? "episodic" : `harness/${origin}`;
	const rootKind: RootKind = scope.startsWith("project:") ? "project" : "global";

	return {
		claim_id: claim.claim_id,
		permalink,
		rootKind,
		...(rootKind === "project" && claim.project_slug ? { projectSlug: claim.project_slug.trim() } : {}),
		relPath: `${dir}/${permalink}.md`,
		frontmatter,
		body,
	};
}

