/**
 * Apply planner (P2c, ADR 0009 / spec P2) — turn a {@link ReconciliationManifest}
 * into the exact set of canonical records to write, applying the
 * **disposition-vs-edge** model. Pure: no IO.
 *
 * Every eligible claim has exactly one *disposition* — `novel` or `merge` — that
 * decides where its record lands; `supersede` is an *edge* layered on top:
 *  - `novel{id}`            → one active record for that claim.
 *  - `merge{canonical,…}`   → one active record for the canonical claim; the other
 *                              members collapse into it (no own record), recorded
 *                              in `merged_from`.
 *  - `supersede{new,old}`   → the *new* claim is a record bearer via its own
 *                              novel/merge; the *old* claim still gets a record but
 *                              flagged `status: superseded` + `superseded_by:[new]`
 *                              so it drops out of active recall (ADR 0009 §5).
 *
 * A no-drops accounting proves every eligible claim is either a record bearer or
 * collapsed into a merge — never silently lost.
 */

import type { ReconciliationManifest } from "../reconcile-step.ts";
import type { Claim } from "../ledger.ts";
import { type CanonicalRecord, claimToCanonical, type MapClaimOptions } from "./map-claim.ts";

export type ApplyStats = {
	total_records: number;
	active: number;
	superseded: number;
	/** Records that collapsed ≥2 claims (a merge canonical). */
	merged_records: number;
	/** Claims absorbed by a merge — they get no record of their own. */
	collapsed_members: number;
	quarantined: number;
	/** relPath directory → record count (e.g. `harness/pi`, `episodic`). */
	by_namespace: Record<string, number>;
};

export type ApplyPlan = {
	records: CanonicalRecord[];
	stats: ApplyStats;
	/** Eligible claims with neither a record nor a merge-collapse — a silent drop.
	 * Must be empty for `complete`. */
	unaccounted: string[];
	/** Eligible claims that resolved to more than one record bearer — an apply
	 * ambiguity. Must be empty for `complete`. */
	over_disposed: string[];
	complete: boolean;
};

/** Plan the canonical writes for a reconciled ledger. `claims` is the full ledger
 * (quarantined claims included — they are filtered out here by id). */
export function planApply(
	claims: Claim[],
	manifest: ReconciliationManifest,
	opts: MapClaimOptions = {},
): ApplyPlan {
	const byId = new Map(claims.map((c) => [c.claim_id, c]));
	const quarantined = new Set(manifest.quarantined.map((q) => q.claim_id));

	const need = (id: string): Claim => {
		const claim = byId.get(id);
		if (!claim) throw new Error(`apply: decision references unknown claim_id ${id}`);
		return claim;
	};

	// records keyed by claim_id; collapsed members carry no record.
	const records = new Map<string, CanonicalRecord>();
	const collapsed = new Set<string>();
	const recordBearerCount = new Map<string, number>(); // over-disposition guard

	const bear = (claim: Claim, build: () => CanonicalRecord): CanonicalRecord => {
		recordBearerCount.set(claim.claim_id, (recordBearerCount.get(claim.claim_id) ?? 0) + 1);
		const record = build();
		records.set(claim.claim_id, record);
		return record;
	};

	// Pass 1 — dispositions (novel + merge) place every record bearer.
	for (const d of manifest.decisions) {
		if (d.verb === "novel") {
			bear(need(d.id), () => claimToCanonical(need(d.id), opts));
		} else if (d.verb === "merge") {
			const others = d.member_ids.filter((id) => id !== d.canonical_id);
			bear(need(d.canonical_id), () => {
				const record = claimToCanonical(need(d.canonical_id), opts);
				record.frontmatter = { ...record.frontmatter, merged_from: others };
				return record;
			});
			for (const id of others) collapsed.add(id);
		}
	}

	// Pass 2 — supersede edges. The superseded claim is a record bearer here
	// (it has no novel/merge disposition); flag it and point at the new record.
	for (const d of manifest.decisions) {
		if (d.verb !== "supersede") continue;
		const newPermalink = records.get(d.new_id)?.permalink ?? claimToCanonical(need(d.new_id), opts).permalink;
		const record = records.get(d.superseded_id) ?? bear(need(d.superseded_id), () => claimToCanonical(need(d.superseded_id), opts));
		record.frontmatter = {
			...record.frontmatter,
			status: "superseded",
			superseded_by: [newPermalink],
		};
	}

	// Accounting — every eligible claim is a record bearer or collapsed; nothing else.
	const eligible = [...byId.keys()].filter((id) => !quarantined.has(id));
	const unaccounted = eligible.filter((id) => !records.has(id) && !collapsed.has(id));
	const over_disposed = [...recordBearerCount.entries()]
		.filter(([id, n]) => n > 1 || (records.has(id) && collapsed.has(id)))
		.map(([id]) => id);

	const list = [...records.values()];
	const by_namespace: Record<string, number> = {};
	let superseded = 0;
	let merged_records = 0;
	for (const r of list) {
		const dir = r.relPath.slice(0, r.relPath.lastIndexOf("/"));
		by_namespace[dir] = (by_namespace[dir] ?? 0) + 1;
		if (r.frontmatter.status === "superseded") superseded += 1;
		if (r.frontmatter.merged_from?.length) merged_records += 1;
	}

	return {
		records: list,
		stats: {
			total_records: list.length,
			active: list.length - superseded,
			superseded,
			merged_records,
			collapsed_members: collapsed.size,
			quarantined: quarantined.size,
			by_namespace,
		},
		unaccounted,
		over_disposed,
		complete: unaccounted.length === 0 && over_disposed.length === 0,
	};
}

