	it("flags a secret in the body as sensitivity:secret", () => {
		const claim = mkClaim({ title: "creds", text: "export REDACTED" });
		expect(claimToCanonical(claim).frontmatter.sensitivity).toBe("secret");
	});

	it("derives a content-addressed permalink (deterministic, claim_id suffix)", () => {
		const claim = mkClaim({ title: "My Cool Note!", text: "body" });
		const rec = claimToCanonical(claim);
		expect(rec.permalink).toBe(`my-cool-note-${claim.claim_id.slice(0, 8)}`);
		expect(claimToCanonical(claim).permalink).toBe(rec.permalink); // stable
	});

	it("derives a title from the first heading when the claim has none", () => {
		const claim = mkClaim({ text: "# Boot Profiling Parked\n\nDetails here." });
		expect(claimToCanonical(claim).frontmatter.title).toBe("Boot Profiling Parked");
	});
});

describe("planApply — decisions → records (disposition + supersede edge)", () => {
	it("novel → one active record", () => {
		const a = mkClaim({ title: "a", text: "alpha" });
		const plan = planApply([a], mkManifest([{ verb: "novel", id: a.claim_id }]));
		expect(plan.complete).toBe(true);
		expect(plan.stats.active).toBe(1);
		expect(plan.stats.superseded).toBe(0);
		expect(plan.records[0]?.frontmatter.status).toBe("active");
	});

	it("merge → one canonical record citing collapsed members; members get no record", () => {
		const a = mkClaim({ title: "a", text: "alpha" });
		const b = mkClaim({ title: "b", text: "beta" });
		const plan = planApply(
			[a, b],
			mkManifest([
				{ verb: "merge", canonical_id: a.claim_id, member_ids: [a.claim_id, b.claim_id], basis: "judge", rationale: "same fact" },
			]),
		);
		expect(plan.complete).toBe(true);
		expect(plan.stats.total_records).toBe(1);
		expect(plan.stats.merged_records).toBe(1);
		expect(plan.stats.collapsed_members).toBe(1);
		expect(plan.records[0]?.frontmatter.merged_from).toEqual([b.claim_id]);
		expect(plan.records.find((r) => r.claim_id === b.claim_id)).toBeUndefined();
	});

	it("supersede → old record flagged + pointing at the new record; new stays active", () => {
		const oldC = mkClaim({ title: "old", text: "old truth" });
		const newC = mkClaim({ title: "new", text: "corrected truth" });
		const plan = planApply(
			[oldC, newC],
			mkManifest([
				{ verb: "novel", id: newC.claim_id },
				{ verb: "supersede", new_id: newC.claim_id, superseded_id: oldC.claim_id, rationale: "correction" },
			]),
		);
		expect(plan.complete).toBe(true);
		const oldRec = plan.records.find((r) => r.claim_id === oldC.claim_id);
		const newRec = plan.records.find((r) => r.claim_id === newC.claim_id);
		expect(oldRec?.frontmatter.status).toBe("superseded");
		expect(oldRec?.frontmatter.superseded_by).toEqual([newRec?.permalink]);
		expect(newRec?.frontmatter.status).toBe("active");
		expect(plan.stats.superseded).toBe(1);
		expect(plan.stats.active).toBe(1);
	});

	it("excludes quarantined claims and flags a silent drop as unaccounted", () => {
		const a = mkClaim({ title: "a", text: "alpha" });
		const b = mkClaim({ title: "b", text: "beta" }); // neither disposed nor quarantined
		const q = mkClaim({ title: "q", text: "quarantined boilerplate" });
		const plan = planApply(
			[a, b, q],
			mkManifest(
				[{ verb: "novel", id: a.claim_id }],
				[{ claim_id: q.claim_id, source_store: "pi", source_path: "x", reason: "boilerplate", bytes: 1 } as ReconciliationManifest["quarantined"][number]],
			),
		);
		expect(plan.unaccounted).toEqual([b.claim_id]);
		expect(plan.complete).toBe(false);
		expect(plan.stats.quarantined).toBe(1);
	});
});

