import { describe, expect, it } from "vitest";

import { type Claim, type ClaimInput, makeClaim } from "../src/migration/ledger.ts";
import { claimToCanonical } from "../src/migration/apply/map-claim.ts";
import { planApply } from "../src/migration/apply/plan.ts";
import type { ReconciliationManifest } from "../src/migration/reconcile-step.ts";

function mkClaim(over: Partial<ClaimInput> & { text: string }): Claim {
	return makeClaim({
		source_store: "pi",
		source_path: "memory/x.md",
		span: { kind: "whole" },
		scope_hint: "profile",
		...over,
	});
}

/** A manifest stub — planApply only reads `decisions` + `quarantined`. */
function mkManifest(
	decisions: ReconciliationManifest["decisions"],
	quarantined: ReconciliationManifest["quarantined"] = [],
): ReconciliationManifest {
	return { decisions, quarantined } as unknown as ReconciliationManifest;
}

describe("claimToCanonical — claim → canonical record", () => {
	it("maps an obsidian project claim to an origin-private pi record", () => {
		const claim = mkClaim({
			source_store: "obsidian",
			source_path: "memory/project/foo.md",
			scope_hint: "project",
			project_slug: "lue-kube",
			title: "NetworkPolicy egress fix",
			text: "---\ntitle: x\n---\nThe egress block was fixed.",
		});
		const rec = claimToCanonical(claim);
		expect(rec.frontmatter.origin).toBe("pi"); // obsidian is Pi's dream wiki
		expect(rec.frontmatter.provenance.source_store).toBe("obsidian");
		expect(rec.frontmatter.provenance.capture_mechanism).toBe("dream");
		expect(rec.frontmatter.confidence).toBe("consolidated");
		expect(rec.frontmatter.visibility).toBe("private");
		expect(rec.frontmatter.scope).toBe("project:lue-kube");
		expect(rec.rootKind).toBe("project");
		expect(rec.projectSlug).toBe("lue-kube");
		expect(rec.relPath).toBe(`harness/pi/${rec.permalink}.md`);
		expect(rec.body).toBe("The egress block was fixed."); // legacy frontmatter stripped
	});

	it("routes episodic codex captures to episodic/", () => {
		const claim = mkClaim({
			source_store: "codex",
			source_path: "sessions/2026.md",
			scope_hint: "episodic",
			title: "session log",
			text: "did some work",
		});
		const rec = claimToCanonical(claim);
		expect(rec.frontmatter.origin).toBe("codex");
		expect(rec.frontmatter.provenance.source_store).toBe("codex-memories");
		expect(rec.relPath).toBe(`episodic/${rec.permalink}.md`);
		expect(rec.rootKind).toBe("global");
	});

	it("flags a secret in the body as sensitivity:secret", () => {
		const claim = mkClaim({ title: "creds", text: "export REDACTED" });
		expect(claimToCanonical(claim).frontmatter.sensitivity).toBe("secret");
	});

	it("derives a content-addressed permalink (deterministic, claim_id suffix)", () => {
		const claim = mkClaim({ title: "My Cool Note!", text: "body" });
		const rec = claimToCanonical(claim);
		expect(rec.permalink).toBe(`my-cool-note-${claim.claim_id.slice(0, 8)}`);
		expect(claimToCanonical(claim).permalink).toBe(rec.permalink); // stable
	});

	it("derives a title from the first heading when the claim has none", () => {
		const claim = mkClaim({ text: "# Boot Profiling Parked\n\nDetails here." });
		expect(claimToCanonical(claim).frontmatter.title).toBe("Boot Profiling Parked");
	});
});

describe("planApply — decisions → records (disposition + supersede edge)", () => {
	it("novel → one active record", () => {
		const a = mkClaim({ title: "a", text: "alpha" });
		const plan = planApply([a], mkManifest([{ verb: "novel", id: a.claim_id }]));
		expect(plan.complete).toBe(true);
		expect(plan.stats.active).toBe(1);
		expect(plan.stats.superseded).toBe(0);
		expect(plan.records[0]?.frontmatter.status).toBe("active");
	});

	it("merge → one canonical record citing collapsed members; members get no record", () => {
		const a = mkClaim({ title: "a", text: "alpha" });
		const b = mkClaim({ title: "b", text: "beta" });
		const plan = planApply(
			[a, b],
			mkManifest([
				{ verb: "merge", canonical_id: a.claim_id, member_ids: [a.claim_id, b.claim_id], basis: "judge", rationale: "same fact" },
			]),
		);
		expect(plan.complete).toBe(true);
		expect(plan.stats.total_records).toBe(1);
		expect(plan.stats.merged_records).toBe(1);
		expect(plan.stats.collapsed_members).toBe(1);
		expect(plan.records[0]?.frontmatter.merged_from).toEqual([b.claim_id]);
		expect(plan.records.find((r) => r.claim_id === b.claim_id)).toBeUndefined();
	});

	it("supersede → old record flagged + pointing at the new record; new stays active", () => {
		const oldC = mkClaim({ title: "old", text: "old truth" });
		const newC = mkClaim({ title: "new", text: "corrected truth" });
		const plan = planApply(
			[oldC, newC],
			mkManifest([
				{ verb: "novel", id: newC.claim_id },
				{ verb: "supersede", new_id: newC.claim_id, superseded_id: oldC.claim_id, rationale: "correction" },
			]),
		);
		expect(plan.complete).toBe(true);
		const oldRec = plan.records.find((r) => r.claim_id === oldC.claim_id);
		const newRec = plan.records.find((r) => r.claim_id === newC.claim_id);
		expect(oldRec?.frontmatter.status).toBe("superseded");
		expect(oldRec?.frontmatter.superseded_by).toEqual([newRec?.permalink]);
		expect(newRec?.frontmatter.status).toBe("active");
		expect(plan.stats.superseded).toBe(1);
		expect(plan.stats.active).toBe(1);
	});

	it("excludes quarantined claims and flags a silent drop as unaccounted", () => {
		const a = mkClaim({ title: "a", text: "alpha" });
		const b = mkClaim({ title: "b", text: "beta" }); // neither disposed nor quarantined
		const q = mkClaim({ title: "q", text: "quarantined boilerplate" });
		const plan = planApply(
			[a, b, q],
			mkManifest(
				[{ verb: "novel", id: a.claim_id }],
				[{ claim_id: q.claim_id, source_store: "pi", source_path: "x", reason: "boilerplate", bytes: 1 } as ReconciliationManifest["quarantined"][number]],
			),
		);
		expect(plan.unaccounted).toEqual([b.claim_id]);
		expect(plan.complete).toBe(false);
		expect(plan.stats.quarantined).toBe(1);
	});
});

/**
 * Apply planner (P2c, ADR 0009 / spec P2) — turn a {@link ReconciliationManifest}
 * into the exact set of canonical records to write, applying the
 * **disposition-vs-edge** model. Pure: no IO.
 *
 * Every eligible claim has exactly one *disposition* — `novel` or `merge` — that
 * decides where its record lands; `supersede` is an *edge* layered on top:
 *  - `novel{id}`            → one active record for that claim.
 *  - `merge{canonical,…}`   → one active record for the canonical claim; the other
 *                              members collapse into it (no own record), recorded
 *                              in `merged_from`.
 *  - `supersede{new,old}`   → the *new* claim is a record bearer via its own
 *                              novel/merge; the *old* claim still gets a record but
 *                              flagged `status: superseded` + `superseded_by:[new]`
 *                              so it drops out of active recall (ADR 0009 §5).
 *
 * A no-drops accounting proves every eligible claim is either a record bearer or
 * collapsed into a merge — never silently lost.
 */

import type { ReconciliationManifest } from "../reconcile-step.ts";
import type { Claim } from "../ledger.ts";
import { type CanonicalRecord, claimToCanonical, type MapClaimOptions } from "./map-claim.ts";

export type ApplyStats = {
	total_records: number;
	active: number;
	superseded: number;
	/** Records that collapsed ≥2 claims (a merge canonical). */
	merged_records: number;
	/** Claims absorbed by a merge — they get no record of their own. */
	collapsed_members: number;
	quarantined: number;
	/** relPath directory → record count (e.g. `harness/pi`, `episodic`). */
	by_namespace: Record<string, number>;
};

export type ApplyPlan = {
	records: CanonicalRecord[];
	stats: ApplyStats;
	/** Eligible claims with neither a record nor a merge-collapse — a silent drop.
	 * Must be empty for `complete`. */
	unaccounted: string[];
	/** Eligible claims that resolved to more than one record bearer — an apply
	 * ambiguity. Must be empty for `complete`. */
	over_disposed: string[];
	complete: boolean;
};

/** Plan the canonical writes for a reconciled ledger. `claims` is the full ledger
 * (quarantined claims included — they are filtered out here by id). */
export function planApply(
	claims: Claim[],
	manifest: ReconciliationManifest,
	opts: MapClaimOptions = {},
): ApplyPlan {
	const byId = new Map(claims.map((c) => [c.claim_id, c]));
	const quarantined = new Set(manifest.quarantined.map((q) => q.claim_id));

	const need = (id: string): Claim => {
		const claim = byId.get(id);
		if (!claim) throw new Error(`apply: decision references unknown claim_id ${id}`);
		return claim;
	};

	// records keyed by claim_id; collapsed members carry no record.
	const records = new Map<string, CanonicalRecord>();
	const collapsed = new Set<string>();
	const recordBearerCount = new Map<string, number>(); // over-disposition guard

	const bear = (claim: Claim, build: () => CanonicalRecord): CanonicalRecord => {
		recordBearerCount.set(claim.claim_id, (recordBearerCount.get(claim.claim_id) ?? 0) + 1);
		const record = build();
		records.set(claim.claim_id, record);
		return record;
	};

	// Pass 1 — dispositions (novel + merge) place every record bearer.
	for (const d of manifest.decisions) {
		if (d.verb === "novel") {
			bear(need(d.id), () => claimToCanonical(need(d.id), opts));
		} else if (d.verb === "merge") {
			const others = d.member_ids.filter((id) => id !== d.canonical_id);
			bear(need(d.canonical_id), () => {
				const record = claimToCanonical(need(d.canonical_id), opts);
				record.frontmatter = { ...record.frontmatter, merged_from: others };
				return record;
			});
			for (const id of others) collapsed.add(id);
		}
	}

	// Pass 2 — supersede edges. The superseded claim is a record bearer here
	// (it has no novel/merge disposition); flag it and point at the new record.
	for (const d of manifest.decisions) {
		if (d.verb !== "supersede") continue;
		const newPermalink = records.get(d.new_id)?.permalink ?? claimToCanonical(need(d.new_id), opts).permalink;
		const record = records.get(d.superseded_id) ?? bear(need(d.superseded_id), () => claimToCanonical(need(d.superseded_id), opts));
		record.frontmatter = {
			...record.frontmatter,
			status: "superseded",
			superseded_by: [newPermalink],
		};
	}

	// Accounting — every eligible claim is a record bearer or collapsed; nothing else.
	const eligible = [...byId.keys()].filter((id) => !quarantined.has(id));
	const unaccounted = eligible.filter((id) => !records.has(id) && !collapsed.has(id));
	const over_disposed = [...recordBearerCount.entries()]
		.filter(([id, n]) => n > 1 || (records.has(id) && collapsed.has(id)))
		.map(([id]) => id);

	const list = [...records.values()];
	const by_namespace: Record<string, number> = {};
	let superseded = 0;
	let merged_records = 0;
	for (const r of list) {
		const dir = r.relPath.slice(0, r.relPath.lastIndexOf("/"));
		by_namespace[dir] = (by_namespace[dir] ?? 0) + 1;
		if (r.frontmatter.status === "superseded") superseded += 1;
		if (r.frontmatter.merged_from?.length) merged_records += 1;
	}

	return {
		records: list,
		stats: {
			total_records: list.length,
			active: list.length - superseded,
			superseded,
			merged_records,
			collapsed_members: collapsed.size,
			quarantined: quarantined.size,
			by_namespace,
		},
		unaccounted,
		over_disposed,
		complete: unaccounted.length === 0 && over_disposed.length === 0,
	};
}

/**
 * Claim → canonical record mapping (P2c apply, ADR 0009 / spec P2).
 *
 * The first writer of real canonical records. Turns a legacy {@link Claim} into a
 * {@link CanonicalRecord}: structured frontmatter + body + a content-addressed
 * permalink + a target path within the two-root canonical store.
 *
 * The mapping is **conservative and reversible**, pinned by spec/ADR — it makes
 * no cross-harness or sharing decisions (P4 owns those):
 *  - `origin` is the capturing harness (`obsidian` is Pi's dream wiki → `pi`).
 *  - `visibility` is always `private`; a later classification pass promotes to
 *    `shared`. So every migrated record lands in `harness/<origin>/` (X-specific),
 *    never `shared/`, except episodic captures which land in `episodic/`.
 *  - `sensitivity` is `secret` iff a secret/PII pattern matches (the body is kept
 *    intact on disk; redaction happens at index/inject time — spec M3), else `private`.
 *  - `permalink` is content-addressed (`slug-<claim_id[:8]>`) — never LLM-invented,
 *    so reruns are idempotent (spec P2).
 *  - `scope` follows the claim's scope hint / project slug; unknowns fall to `profile`.
 * Pure: no IO.
 */

import { type CanonicalFrontmatter, CanonicalFrontmatterSchema } from "../../canonical/frontmatter.ts";
import { redact } from "../../redact.ts";
import { type Claim, type ClaimSourceStore, spanKey } from "../ledger.ts";
import { parseFrontmatter } from "../parse.ts";

type Origin = CanonicalFrontmatter["origin"];
type SourceStore = CanonicalFrontmatter["provenance"]["source_store"];
type CaptureMechanism = CanonicalFrontmatter["provenance"]["capture_mechanism"];

/** Which canonical root a record belongs to. */
export type RootKind = "global" | "project";

/** A canonical record, resolved enough to write: frontmatter + body + the path
 * within its root. `claim_id` is the source disposition this record realises
 * (apply accounting joins on it). */
export type CanonicalRecord = {
	claim_id: string;
	permalink: string;
	rootKind: RootKind;
	/** Set iff `rootKind === "project"`. */
	projectSlug?: string;
	/** Path within the root, e.g. `harness/pi/<permalink>.md` or `episodic/<permalink>.md`. */
	relPath: string;
	frontmatter: CanonicalFrontmatter;
	body: string;
};

/** Legacy physical store → the capturing harness (`origin`). Obsidian is Pi's
 * dream wiki, so it originates as `pi`. */
const ORIGIN_BY_STORE: Record<ClaimSourceStore, Origin> = {
	pi: "pi",
	obsidian: "pi",
	"claude-code": "claude-code",
	codex: "codex",
};

/** Legacy physical store → the finer canonical provenance store. */
const PROVENANCE_STORE_BY_STORE: Record<ClaimSourceStore, SourceStore> = {
	pi: "pi",
	obsidian: "obsidian",
	"claude-code": "claude-code",
	codex: "codex-memories",
};

/** How the source originally captured the fact. */
const CAPTURE_BY_STORE: Record<ClaimSourceStore, CaptureMechanism> = {
	pi: "native",
	obsidian: "dream",
	"claude-code": "native",
	codex: "native",
};

/** Obsidian notes are already dream-consolidated; everything else is raw extract. */
function confidenceFor(store: ClaimSourceStore): CanonicalFrontmatter["confidence"] {
	return store === "obsidian" ? "consolidated" : "extracted";
}

/** Slugify a title for the permalink stem: lowercase, non-alphanumeric → `-`,
 * collapse, trim, cap length. Empty → `untitled`. */
function slugify(title: string): string {
	const slug = title
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, "-")
		.replace(/^-+|-+$/g, "")
		.slice(0, 60)
		.replace(/-+$/g, "");
	return slug.length > 0 ? slug : "untitled";
}

/** Title from the claim, else the first heading / first non-empty body line. */
function deriveTitle(claim: Claim, body: string): string {
	if (claim.title && claim.title.trim().length > 0) return claim.title.trim();
	for (const raw of body.split("\n")) {
		const line = raw.replace(/^#+\s*/, "").trim();
		if (line.length > 0) return line.slice(0, 120);
	}
	return "Untitled";
}

/** `scope` frontmatter from the claim's hint + project slug. Unknowns → profile. */
function scopeFor(claim: Claim): string {
	if (claim.project_slug && claim.project_slug.trim().length > 0) {
		return `project:${claim.project_slug.trim()}`;
	}
	return "profile";
}

export type MapClaimOptions = { migrationBatchId?: string | undefined };

/** Map one claim to its canonical record. */
export function claimToCanonical(claim: Claim, opts: MapClaimOptions = {}): CanonicalRecord {
	const origin = ORIGIN_BY_STORE[claim.source_store];
	const body = parseFrontmatter(claim.text).body.trim() || claim.text.trim();
	const title = deriveTitle(claim, body);
	const permalink = `${slugify(title)}-${claim.claim_id.slice(0, 8)}`;
	const scope = scopeFor(claim);
	const sensitivity = redact(claim.text).hitCount > 0 ? "secret" : "private";

	const provenance: CanonicalFrontmatter["provenance"] = {
		source_store: PROVENANCE_STORE_BY_STORE[claim.source_store],
		source_path: claim.source_path,
		source_content_hash: claim.content_hash,
		source_record_id: claim.claim_id,
		capture_mechanism: CAPTURE_BY_STORE[claim.source_store],
		...(claim.span.kind === "section" ? { source_span: spanKey(claim.span) } : {}),
		...(claim.captured_at ? { first_seen: claim.captured_at } : {}),
		...(opts.migrationBatchId ? { migration_batch_id: opts.migrationBatchId } : {}),
	};

	const frontmatter = CanonicalFrontmatterSchema.parse({
		title,
		permalink,
		origin,
		visibility: "private",
		sensitivity,
		scope,
		confidence: confidenceFor(claim.source_store),
		status: "active",
		provenance,
	});

	// Placement: episodic captures → episodic/; everything else is origin-private
	// → harness/<origin>/. shared/ is reserved for P4 promotion.
	const dir = claim.scope_hint === "episodic" ? "episodic" : `harness/${origin}`;
	const rootKind: RootKind = scope.startsWith("project:") ? "project" : "global";

	return {
		claim_id: claim.claim_id,
		permalink,
		rootKind,
		...(rootKind === "project" && claim.project_slug ? { projectSlug: claim.project_slug.trim() } : {}),
		relPath: `${dir}/${permalink}.md`,
		frontmatter,
		body,
	};
}

import { describe, expect, it } from "vitest";

import { CanonicalFrontmatterSchema } from "../src/canonical/frontmatter.ts";
import { serializeCanonical } from "../src/canonical/serialize.ts";
import { parseFrontmatter } from "../src/migration/parse.ts";

/** Parse a serialized record back into a validated frontmatter object. */
function roundTrip(fm: ReturnType<typeof CanonicalFrontmatterSchema.parse>, body: string) {
	const text = serializeCanonical(fm, body);
	const parsed = parseFrontmatter(text);
	return { text, body: parsed.body, fm: CanonicalFrontmatterSchema.parse(parsed.data) };
}

const base = {
	title: "lue-kube NetworkPolicy blocked Cloudflare Tunnel egress",
	permalink: "lue-kube-networkpolicy-tunnel-abc12345",
	origin: "pi" as const,
	visibility: "private",
	sensitivity: "private" as const,
	scope: "project:lue-kube",
	confidence: "extracted" as const,
	provenance: {
		source_store: "obsidian" as const,
		source_path: "memory/project/lue-kube-networkpolicy.md",
		source_content_hash: "deadbeef",
		capture_mechanism: "dream" as const,
	},
};

describe("serializeCanonical — round-trips through parseFrontmatter", () => {
	it("a plain active record survives serialize → parse → schema", () => {
		const fm = CanonicalFrontmatterSchema.parse(base);
		const { fm: out, body } = roundTrip(fm, "The egress block on port 7844 was fixed by adding an allow rule.");
		expect(out).toEqual(fm);
		expect(out.status).toBe("active");
		// Body round-trips modulo trailing-newline normalization (single \n appended).
		expect(body.trimEnd()).toBe("The egress block on port 7844 was fixed by adding an allow rule.");
	});

	it("preserves the nested provenance map exactly", () => {
		const fm = CanonicalFrontmatterSchema.parse(base);
		const { fm: out } = roundTrip(fm, "body");
		expect(out.provenance).toEqual(base.provenance);
	});

	it("carries merge provenance (merged_from)", () => {
		const fm = CanonicalFrontmatterSchema.parse({
			...base,
			merged_from: ["hash-of-member-a", "hash-of-member-b"],
		});
		const { fm: out } = roundTrip(fm, "merged canonical record");
		expect(out.merged_from).toEqual(["hash-of-member-a", "hash-of-member-b"]);
	});

	it("carries a superseded record's status + reverse edge", () => {
		const fm = CanonicalFrontmatterSchema.parse({
			...base,
			status: "superseded",
			superseded_by: ["newer-record-permalink"],
		});
		const { fm: out } = roundTrip(fm, "old, corrected truth");
		expect(out.status).toBe("superseded");
		expect(out.superseded_by).toEqual(["newer-record-permalink"]);
	});

	it("omits absent optional edges (no empty anchors)", () => {
		const fm = CanonicalFrontmatterSchema.parse(base);
		const text = serializeCanonical(fm, "body");
		expect(text).not.toContain("merged_from:");
		expect(text).not.toContain("superseded_by:");
		expect(text).not.toContain("links:");
	});
});

/**
 * Canonical record serializer — {@link CanonicalFrontmatter} + body → a Markdown
 * file string. The inverse of `migration/parse.ts`'s `parseFrontmatter`.
 *
 * Hand-rolled to match the repo's no-YAML-dependency convention. It emits
 * exactly the narrow YAML subset `parseYamlSubset` understands, so every record
 * this writes round-trips back through `parseFrontmatter` → `CanonicalFrontmatterSchema`:
 * JSON-quoted scalars (mirroring `dream/patch-applier.ts`'s `serialise`), block
 * `- ` string lists, and `provenance` as the one nested map (the single level of
 * nesting the parser supports, mirroring CC's `metadata:`). Pure: string ops only.
 */

import type { CanonicalFrontmatter } from "./frontmatter.ts";

/** Scalar fields, in a stable, diff-friendly order. All are required-after-parse
 * strings on the schema (`status` via its default). */
const SCALAR_ORDER = [
	"title",
	"permalink",
	"origin",
	"visibility",
	"sensitivity",
	"scope",
	"confidence",
	"status",
] as const;

/** Provenance sub-keys, stable order; absent optionals are omitted. */
const PROVENANCE_ORDER = [
	"source_store",
	"source_path",
	"source_span",
	"source_content_hash",
	"source_record_id",
	"migration_batch_id",
	"first_seen",
	"last_seen",
	"capture_mechanism",
] as const;

function stringArrayLines(key: string, items: readonly string[]): string[] {
	return [`${key}:`, ...items.map((item) => `  - ${JSON.stringify(item)}`)];
}

function provenanceLines(provenance: CanonicalFrontmatter["provenance"]): string[] {
	const lines = ["provenance:"];
	const record = provenance as Record<string, unknown>;
	for (const key of PROVENANCE_ORDER) {
		const value = record[key];
		if (typeof value === "string" && value.length > 0) {
			lines.push(`  ${key}: ${JSON.stringify(value)}`);
		}
	}
	return lines;
}

/** Serialize a canonical record to its on-disk Markdown form. */
export function serializeCanonical(frontmatter: CanonicalFrontmatter, body: string): string {
	const lines: string[] = ["---"];

	for (const key of SCALAR_ORDER) {
		const value = frontmatter[key];
		if (typeof value === "string" && value.length > 0) {
			lines.push(`${key}: ${JSON.stringify(value)}`);
		}
	}

	lines.push(...provenanceLines(frontmatter.provenance));

	// Optional string-array edges — emitted only when non-empty so absent edges
	// don't litter the file (and so the parser never sees an empty `key:` anchor).
	if (frontmatter.merged_from?.length) lines.push(...stringArrayLines("merged_from", frontmatter.merged_from));
	if (frontmatter.supersedes?.length) lines.push(...stringArrayLines("supersedes", frontmatter.supersedes));
	if (frontmatter.superseded_by?.length) lines.push(...stringArrayLines("superseded_by", frontmatter.superseded_by));
	if (frontmatter.links?.length) lines.push(...stringArrayLines("links", frontmatter.links));
	if (frontmatter.relates?.length) lines.push(...stringArrayLines("relates", frontmatter.relates));

	lines.push("---", "");
	return `${lines.join("\n")}${body.replace(/\s*$/, "")}\n`;
}

