1	/**
2	 * Canonical cross-harness memory store — path + namespace resolution.
3	 *
4	 * Layout locked 2026-06-22 (ADR 0007 D1, spec P1): a per-project + global split.
5	 *   global   ~/.agents/memory/{shared,harness/<id>,episodic,inbox}
6	 *   project  ~/.agents/projects/<sanitize(gitRoot)>/memory/{shared,harness/<id>,episodic,inbox}
7	 *
8	 * The per-project root is exactly Claude Code's convention and the existing
9	 * agentic-dream write target (`agentsMemoryRoot`); the global root holds
10	 * profile/cross-project facts. `scope` frontmatter records global-vs-project so
11	 * a misfiled note stays classifiable. Pure: no IO, env-overridable root only.
12	 */
13	
14	import { homedir } from "node:os";
15	import { join } from "node:path";
16	
17	import { agentsMemoryRoot } from "../lib/agents-path.ts";
18	
19	/** The one canonical harness-ID enum — used in paths, provenance, qmd collection
20	 * names, tests, and docs. No informal aliases (`cc`, `claude`, …). */
21	export const HARNESS_IDS = ["pi", "claude-code", "codex"] as const;
22	export type HarnessId = (typeof HARNESS_IDS)[number];
23	
24	export function isHarnessId(value: string): value is HarnessId {
25		return (HARNESS_IDS as readonly string[]).includes(value);
26	}
27	
28	/** Namespaced subdirectories present under every canonical root. */
29	export const CANONICAL_SUBDIRS = ["shared", "harness", "episodic", "inbox"] as const;
30	
31	/**
32	 * Global / cross-project canonical root: `~/.agents/memory`.
33	 * Overridable via `AGENTS_MEMORY_HOME` (testing + relocation).
34	 */
35	export function canonicalGlobalRoot(): string {
36		const override = process.env.AGENTS_MEMORY_HOME;
37		return override && override.length > 0 ? override : join(homedir(), ".agents", "memory");
38	}
39	
40	/**
41	 * Per-project canonical root: `~/.agents/projects/<sanitize(gitRoot)>/memory`.
42	 * Delegates to {@link agentsMemoryRoot} so the project sanitisation stays in
