/**
 * P2c apply — DRY RUN (ADR 0009 / spec P2). The binding sign-off artifact.
 *
 * Reads the reconcile manifest + persisted ledger (read-only), runs {@link planApply},
 * writes every canonical record to a SCRATCH preview root, and emits APPLY-DIFF.md:
 * the exact files apply would create, what collapses (merge), and what drops from
 * active recall (supersede). It mutates NO real store and changes NO recall — the
 * real transactional swap into `~/.agents/memory` is a separate, gated step that
 * runs only after Luke approves this diff.
 *
 * Hard gate: aborts without writing if the plan is not complete (any unaccounted /
 * over-disposed claim) or if the plan's verb counts disagree with the manifest.
 *
 * Env:
 *   DREAM_RECONCILE_OUT   reconcile artifact dir (default ~/.dream-memory/migration-reconcile)
 *   DREAM_APPLY_PREVIEW   preview output dir     (default <OUT>/canonical-preview)
 *
 * Usage: pnpm tsx scripts/migrate-apply-dryrun.ts
 */

import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { homedir } from "node:os";
import { basename, dirname, join } from "node:path";

import { serializeCanonical } from "../src/canonical/serialize.ts";
import { type CanonicalRecord, claimToCanonical } from "../src/migration/apply/map-claim.ts";
import { type ApplyPlan, planApply } from "../src/migration/apply/plan.ts";
import { type Claim, ClaimSchema } from "../src/migration/ledger.ts";
import { type ReconciliationManifest, ReconciliationManifestSchema } from "../src/migration/reconcile-step.ts";

const HOME = homedir();

function envRoot(key: string, fallback: string): string {
	const v = process.env[key];
	return v && v.trim() ? v : fallback;
}

/** Preview path for a record — mirrors the real two-root layout (global vs
 * per-project) under a single scratch tree so Luke can browse it as one dir. */
function previewPathFor(record: CanonicalRecord, previewRoot: string): string {
	if (record.rootKind === "project" && record.projectSlug) {
		return join(previewRoot, "projects", record.projectSlug, record.relPath);
	}
	return join(previewRoot, "global", record.relPath);
}

function md(strings: TemplateStringsArray, ...values: unknown[]): string {
	return strings.reduce((acc, s, i) => acc + s + (i < values.length ? String(values[i]) : ""), "");
}

/** A TOC-index supersede artifact: a `MEMORY.md` index bullet promoted to a
 * standalone doc (low-harm; flagged so Luke can confirm it's not a real correction). */
function isTocArtifact(claim: Claim | undefined): boolean {
	return claim ? basename(claim.source_path) === "MEMORY.md" : false;
}

function buildReport(
	plan: ApplyPlan,
	byId: Map<string, Claim>,
	manifest: ReconciliationManifest,
	previewRoot: string,
	generatedAt: string,
): string {
	const byPermalink = new Map(plan.records.map((r) => [r.permalink, r]));
	const title = (id: string): string => {
		const claim = byId.get(id);
		return claim ? claimToCanonical(claim).frontmatter.title : `(unknown ${id.slice(0, 8)})`;
	};

	const merges = plan.records.filter((r) => r.frontmatter.merged_from?.length).sort((a, b) => a.permalink.localeCompare(b.permalink));
	const supersedes = plan.records.filter((r) => r.frontmatter.status === "superseded").sort((a, b) => a.permalink.localeCompare(b.permalink));
	const novel = plan.records.filter((r) => r.frontmatter.status === "active" && !r.frontmatter.merged_from?.length);

	const quarantineByReason: Record<string, number> = {};
	for (const q of manifest.quarantined) quarantineByReason[q.reason] = (quarantineByReason[q.reason] ?? 0) + 1;

	const ns = Object.entries(plan.stats.by_namespace).sort(([a], [b]) => a.localeCompare(b));

	const lines: string[] = [];
	const p = (s = ""): void => void lines.push(s);

	p(md`# P2c apply — dry-run diff (NOT applied)`);
	p();
	p(md`Generated: ${generatedAt}`);
	p(md`Source manifest: \`${manifest.generated_at}\` (threshold ${manifest.threshold}, version ${manifest.version})`);
	p(md`Preview tree: \`${previewRoot}\` — ${plan.records.length} files written, no real store touched.`);
	p();
	p(md`**This changes nothing live.** It shows exactly what the transactional apply *would* write into the canonical store. Recall is untouched until you approve this diff.`);
	p();

	p(md`## No-drops accounting (the gate)`);
	p();
	p(md`| check | value |`);
	p(md`| --- | --- |`);
	p(md`| eligible claims | ${manifest.eligible_claims} |`);
	p(md`| quarantined (excluded, kept on disk) | ${plan.stats.quarantined} |`);
	p(md`| record bearers written | ${plan.stats.total_records} |`);
	p(md`| └ active (surface in recall) | ${plan.stats.active} |`);
	p(md`| └ superseded (kept, drop from recall) | ${plan.stats.superseded} |`);
	p(md`| merge canonicals (collapse ≥2 claims) | ${plan.stats.merged_records} |`);
	p(md`| merge members collapsed (no own record) | ${plan.stats.collapsed_members} |`);
	p(md`| **unaccounted (silent drops)** | **${plan.unaccounted.length}** |`);
	p(md`| **over-disposed (double-written)** | **${plan.over_disposed.length}** |`);
	p(md`| complete | ${plan.complete ? "✅ yes" : "❌ NO"} |`);
	p();
	p(md`Identity: \`${plan.stats.total_records} bearers + ${plan.stats.collapsed_members} collapsed = ${plan.stats.total_records + plan.stats.collapsed_members} = ${manifest.eligible_claims} eligible\`. Every eligible claim is either written or folded into a merge — nothing is lost.`);
	p();

	p(md`## By namespace`);
	p();
	p(md`| namespace | records |`);
	p(md`| --- | --- |`);
	for (const [dir, n] of ns) p(md`| \`${dir}\` | ${n} |`);
	p();
	p(`> Global records resolve to \`~/.agents/memory/<namespace>\`; \`projects/<slug>\` records resolve to \`~/.agents/projects/<sanitize(gitRoot)>/memory/<namespace>\` (slug→gitRoot resolution happens in the gated apply). All migrated records land in \`harness/<origin>\` or \`episodic\` — never \`shared\` (P4 promotes to shared).`);
	p();

	p(md`## Merges (${merges.length}) — parallel captures collapsed to one canonical`);
	p();
	p(`Non-destructive: every collapsed member is recorded in the canonical's \`merged_from\`. A wrong merge is reversible — the member claim_id is right there.`);
	p();
	for (const r of merges) {
		p(md`- **${r.permalink}** — "${r.frontmatter.title}" (\`${r.relPath.slice(0, r.relPath.lastIndexOf("/"))}\`)`);
		for (const memberId of r.frontmatter.merged_from ?? []) {
			const m = byId.get(memberId);
			p(md`    - collapses \`${memberId.slice(0, 8)}\` "${title(memberId)}" — ${m ? `${m.source_store}:${m.source_path}` : "(claim not in ledger)"}`);
		}
	}
	p();

	p(md`## Supersedes (${supersedes.length}) — temporal corrections; old kept, drops from recall`);
	p();
	p(`Each superseded record stays on disk with \`status: superseded\` + \`superseded_by\`, so it is excluded from active recall but fully recoverable (flip the status back). TOC-index artifacts (\`MEMORY.md\` index bullets) are flagged — low-harm, confirm they aren't real corrections.`);
	p();
	let tocCount = 0;
	for (const r of supersedes) {
		const newPermalink = r.frontmatter.superseded_by?.[0] ?? "(none)";
		const newRec = byPermalink.get(newPermalink);
		const claim = byId.get(r.claim_id);
		const toc = isTocArtifact(claim);
		if (toc) tocCount += 1;
		p(md`- ${toc ? "🗂️ " : ""}**${r.permalink}** "${r.frontmatter.title}" ${claim ? `(${claim.source_store}:${claim.source_path})` : ""}`);
		p(md`    - → superseded by **${newPermalink}** "${newRec?.frontmatter.title ?? "(new record)"}"`);
	}
	p();
	p(md`${tocCount} of ${supersedes.length} supersedes are \`MEMORY.md\` TOC-index artifacts (🗂️). ${tocCount > 0 ? "Follow-up: quarantine MEMORY.md index bullets in the extractors (spec P2 cleanup)." : ""}`);
	p();

	p(md`## Novel records (${novel.length}) — sample`);
	p();
	p(md`| permalink | namespace | origin | scope | sensitivity |`);
	p(md`| --- | --- | --- | --- | --- |`);
	for (const r of novel.slice(0, 25)) {
		p(md`| ${r.permalink} | \`${r.relPath.slice(0, r.relPath.lastIndexOf("/"))}\` | ${r.frontmatter.origin} | ${r.frontmatter.scope} | ${r.frontmatter.sensitivity} |`);
	}
	p(md`_…and ${Math.max(0, novel.length - 25)} more. Full set is on disk under the preview tree._`);
	p();

	p(md`## Quarantined (${manifest.quarantined.length}) — excluded, untouched on disk`);
	p();
	p(md`| reason | count |`);
	p(md`| --- | --- |`);
	for (const [reason, n] of Object.entries(quarantineByReason).sort(([, a], [, b]) => b - a)) {
		p(md`| ${reason} | ${n} |`);
	}
	p();

	p(md`## What apply would do next (gated — NOT done here)`);
	p();
	p(`1. Write these ${plan.records.length} records into a temp tree, validate, atomic-swap into \`~/.agents/memory\` (+ per-project roots), retain a rollback snapshot.`);
	p(`2. Rebuild the qmd index.`);
	p(`3. Add the \`status: active\` recall filter so superseded records stop surfacing.`);
	p();
	p(`Legacy stores (pi / obsidian / codex / claude-code) are read-only inputs — apply never deletes them.`);
	p();

	return `${lines.join("\n")}\n`;
}

async function main(): Promise<void> {
	const outDir = envRoot("DREAM_RECONCILE_OUT", join(HOME, ".dream-memory", "migration-reconcile"));
	const previewRoot = envRoot("DREAM_APPLY_PREVIEW", join(outDir, "canonical-preview"));
	const manifestPath = join(outDir, "manifest.json");
	const ledgerPath = join(outDir, "ledger-claims.jsonl");
	const generatedAt = new Date().toISOString();

	console.log(`\n=== P2c apply DRY RUN (no real store touched) ===`);
	console.log(`manifest: ${manifestPath}`);
	console.log(`ledger:   ${ledgerPath}`);
	console.log(`preview:  ${previewRoot}`);

	// 1. Load artifacts (read-only), validate through the schemas.
	const manifest = ReconciliationManifestSchema.parse(JSON.parse(await readFile(manifestPath, "utf8")));
	const ledgerText = await readFile(ledgerPath, "utf8");
	const claims: Claim[] = ledgerText
		.split("\n")
		.filter((line) => line.trim().length > 0)
		.map((line) => ClaimSchema.parse(JSON.parse(line)));
	const byId = new Map(claims.map((c) => [c.claim_id, c]));
	console.log(`\nloaded ${claims.length} claims, ${manifest.decisions.length} decisions, ${manifest.quarantined.length} quarantined`);

	// 2. Plan the canonical writes (pure).
	const plan = planApply(claims, manifest, { migrationBatchId: manifest.generated_at });

	// 3. Hard gate — refuse to write a preview that misrepresents apply.
	const expectedActive = manifest.stats.novel + manifest.stats.merges;
	const mismatches: string[] = [];
	if (!plan.complete) mismatches.push(`plan not complete: ${plan.unaccounted.length} unaccounted, ${plan.over_disposed.length} over-disposed`);
	if (plan.stats.active !== expectedActive) mismatches.push(`active ${plan.stats.active} ≠ novel+merges ${expectedActive}`);
	if (plan.stats.superseded !== manifest.stats.supersedes) mismatches.push(`superseded ${plan.stats.superseded} ≠ manifest ${manifest.stats.supersedes}`);
	if (plan.stats.merged_records !== manifest.stats.merges) mismatches.push(`merged_records ${plan.stats.merged_records} ≠ manifest ${manifest.stats.merges}`);
	if (mismatches.length > 0) {
		console.error(`\n❌ ABORT — plan disagrees with manifest, nothing written:`);
		for (const m of mismatches) console.error(`   - ${m}`);
		if (plan.unaccounted.length) console.error(`   unaccounted sample: ${plan.unaccounted.slice(0, 10).join(", ")}`);
		if (plan.over_disposed.length) console.error(`   over_disposed sample: ${plan.over_disposed.slice(0, 10).join(", ")}`);
		process.exitCode = 1;
		return;
	}
	console.log(`\n✅ accounting clean: ${plan.stats.total_records} records (${plan.stats.active} active, ${plan.stats.superseded} superseded), 0 dropped`);

	// 4. Write the preview tree (scratch only — regenerated each run).
	if (!previewRoot.includes("canonical-preview") && !previewRoot.startsWith(outDir)) {
		throw new Error(`refusing to clear preview dir outside the reconcile out dir: ${previewRoot}`);
	}
	await rm(previewRoot, { recursive: true, force: true });
	let written = 0;
	for (const record of plan.records) {
		const filePath = previewPathFor(record, previewRoot);
		await mkdir(dirname(filePath), { recursive: true });
		await writeFile(filePath, serializeCanonical(record.frontmatter, record.body), "utf8");
		written += 1;
	}
	console.log(`wrote ${written} records under ${previewRoot}`);

	// 5. Emit the diff report — Luke's binding sign-off artifact.
	const report = buildReport(plan, byId, manifest, previewRoot, generatedAt);
	const reportPath = join(outDir, "APPLY-DIFF.md");
	await writeFile(reportPath, report, "utf8");
	console.log(`\n📄 diff report: ${reportPath}`);
	console.log(`   review it + the preview tree, then approve the gated apply.`);
}

main().catch((err) => {
	console.error(err);
	process.exitCode = 1;
});

