			p(md`    - collapses \`${memberId.slice(0, 8)}\` "${title(memberId)}" — ${m ? `${m.source_store}:${m.source_path}` : "(claim not in ledger)"}`);
		}
	}
	p();

	p(md`## Supersedes (${supersedes.length}) — temporal corrections; old kept, drops from recall`);
	p();
	p(`Each superseded record stays on disk with \`status: superseded\` + \`superseded_by\`, so it is excluded from active recall but fully recoverable (flip the status back). TOC-index artifacts (\`MEMORY.md\` index bullets) are flagged — low-harm, confirm they aren't real corrections.`);
	p();
	let tocCount = 0;
	for (const r of supersedes) {
		const newPermalink = r.frontmatter.superseded_by?.[0] ?? "(none)";
		const newRec = byPermalink.get(newPermalink);
		const claim = byId.get(r.claim_id);
		const toc = isTocArtifact(claim);
		if (toc) tocCount += 1;
		p(md`- ${toc ? "🗂️ " : ""}**${r.permalink}** "${r.frontmatter.title}" ${claim ? `(${claim.source_store}:${claim.source_path})` : ""}`);
		p(md`    - → superseded by **${newPermalink}** "${newRec?.frontmatter.title ?? "(new record)"}"`);
	}
	p();
	p(md`${tocCount} of ${supersedes.length} supersedes are \`MEMORY.md\` TOC-index artifacts (🗂️). ${tocCount > 0 ? "Follow-up: quarantine MEMORY.md index bullets in the extractors (spec P2 cleanup)." : ""}`);
	p();

	p(md`## Novel records (${novel.length}) — sample`);
	p();
	p(md`| permalink | namespace | origin | scope | sensitivity |`);
	p(md`| --- | --- | --- | --- | --- |`);
	for (const r of novel.slice(0, 25)) {
		p(md`| ${r.permalink} | \`${r.relPath.slice(0, r.relPath.lastIndexOf("/"))}\` | ${r.frontmatter.origin} | ${r.frontmatter.scope} | ${r.frontmatter.sensitivity} |`);
	}
	p(md`_…and ${Math.max(0, novel.length - 25)} more. Full set is on disk under the preview tree._`);
	p();

	p(md`## Quarantined (${manifest.quarantined.length}) — excluded, untouched on disk`);
	p();
	p(md`| reason | count |`);
	p(md`| --- | --- |`);
	for (const [reason, n] of Object.entries(quarantineByReason).sort(([, a], [, b]) => b - a)) {
		p(md`| ${reason} | ${n} |`);
	}
	p();

	p(md`## What apply would do next (gated — NOT done here)`);
	p();
	p(`1. Write these ${plan.records.length} records into a temp tree, validate, atomic-swap into \`~/.agents/memory\` (+ per-project roots), retain a rollback snapshot.`);
	p(`2. Rebuild the qmd index.`);
	p(`3. Add the \`status: active\` recall filter so superseded records stop surfacing.`);
	p();
	p(`Legacy stores (pi / obsidian / codex / claude-code) are read-only inputs — apply never deletes them.`);
	p();

	return `${lines.join("\n")}\n`;
}

async function main(): Promise<void> {
	const outDir = envRoot("DREAM_RECONCILE_OUT", join(HOME, ".dream-memory", "migration-reconcile"));
	const previewRoot = envRoot("DREAM_APPLY_PREVIEW", join(outDir, "canonical-preview"));
	const manifestPath = join(outDir, "manifest.json");
	const ledgerPath = join(outDir, "ledger-claims.jsonl");
	const generatedAt = new Date().toISOString();

	console.log(`\n=== P2c apply DRY RUN (no real store touched) ===`);
	console.log(`manifest: ${manifestPath}`);
	console.log(`ledger:   ${ledgerPath}`);
	console.log(`preview:  ${previewRoot}`);

	// 1. Load artifacts (read-only), validate through the schemas.
	const manifest = ReconciliationManifestSchema.parse(JSON.parse(await readFile(manifestPath, "utf8")));
	const ledgerText = await readFile(ledgerPath, "utf8");
	const claims: Claim[] = ledgerText
		.split("\n")
		.filter((line) => line.trim().length > 0)
		.map((line) => ClaimSchema.parse(JSON.parse(line)));
	const byId = new Map(claims.map((c) => [c.claim_id, c]));
	console.log(`\nloaded ${claims.length} claims, ${manifest.decisions.length} decisions, ${manifest.quarantined.length} quarantined`);

	// 2. Plan the canonical writes (pure).
	const plan = planApply(claims, manifest, { migrationBatchId: manifest.generated_at });

	// 3. Hard gate — refuse to write a preview that misrepresents apply.
	const expectedActive = manifest.stats.novel + manifest.stats.merges;
	const mismatches: string[] = [];
	if (!plan.complete) mismatches.push(`plan not complete: ${plan.unaccounted.length} unaccounted, ${plan.over_disposed.length} over-disposed`);
	if (plan.stats.active !== expectedActive) mismatches.push(`active ${plan.stats.active} ≠ novel+merges ${expectedActive}`);
	if (plan.stats.superseded !== manifest.stats.supersedes) mismatches.push(`superseded ${plan.stats.superseded} ≠ manifest ${manifest.stats.supersedes}`);
	if (plan.stats.merged_records !== manifest.stats.merges) mismatches.push(`merged_records ${plan.stats.merged_records} ≠ manifest ${manifest.stats.merges}`);
	if (mismatches.length > 0) {
		console.error(`\n❌ ABORT — plan disagrees with manifest, nothing written:`);
		for (const m of mismatches) console.error(`   - ${m}`);
		if (plan.unaccounted.length) console.error(`   unaccounted sample: ${plan.unaccounted.slice(0, 10).join(", ")}`);
		if (plan.over_disposed.length) console.error(`   over_disposed sample: ${plan.over_disposed.slice(0, 10).join(", ")}`);
		process.exitCode = 1;
		return;
	}
	console.log(`\n✅ accounting clean: ${plan.stats.total_records} records (${plan.stats.active} active, ${plan.stats.superseded} superseded), 0 dropped`);

	// 4. Write the preview tree (scratch only — regenerated each run).
	if (!previewRoot.includes("canonical-preview") && !previewRoot.startsWith(outDir)) {
		throw new Error(`refusing to clear preview dir outside the reconcile out dir: ${previewRoot}`);
	}
	await rm(previewRoot, { recursive: true, force: true });
	let written = 0;
	for (const record of plan.records) {
		const filePath = previewPathFor(record, previewRoot);
		await mkdir(dirname(filePath), { recursive: true });
		await writeFile(filePath, serializeCanonical(record.frontmatter, record.body), "utf8");
		written += 1;
	}
	console.log(`wrote ${written} records under ${previewRoot}`);

	// 5. Emit the diff report — Luke's binding sign-off artifact.
	const report = buildReport(plan, byId, manifest, previewRoot, generatedAt);
	const reportPath = join(outDir, "APPLY-DIFF.md");
	await writeFile(reportPath, report, "utf8");
	console.log(`\n📄 diff report: ${reportPath}`);
	console.log(`   review it + the preview tree, then approve the gated apply.`);
}

main().catch((err) => {
	console.error(err);
	process.exitCode = 1;
});

