const fs=require("fs");
const claims=fs.readFileSync("ledger-claims.jsonl","utf8").trim().split("\n").map(l=>JSON.parse(l));
const manifest=JSON.parse(fs.readFileSync("manifest.json","utf8"));

// classify each MEMORY.md-sourced claim by disposition
const isMemoryMd = (p)=> p.split("/").pop()==="MEMORY.md";
const mem = claims.filter(c=>isMemoryMd(c.source_path));
console.log("MEMORY.md-sourced claims:", mem.length);
const byStore={}; for(const c of mem){byStore[c.source_store]=(byStore[c.source_store]||0)+1;}
console.log("  by store:", JSON.stringify(byStore));

// disposition lookup
const novel=new Set(), mergeCanon=new Set(), mergeMember=new Set(), supOld=new Set(), supNew=new Set();
for(const d of manifest.decisions){
  if(d.verb==="novel") novel.add(d.id);
  else if(d.verb==="merge"){ mergeCanon.add(d.canonical_id); for(const m of d.member_ids) if(m!==d.canonical_id) mergeMember.add(m);}
  else if(d.verb==="supersede"){ supOld.add(d.superseded_id); supNew.add(d.new_id);}
}
const quar=new Set(manifest.quarantined.map(q=>q.claim_id));
const memIds=new Set(mem.map(c=>c.claim_id));
let dn=0,dmc=0,dmm=0,dso=0,dsn=0,dq=0,dnone=0;
for(const c of mem){
  if(quar.has(c.claim_id)) dq++;
  else if(novel.has(c.claim_id)) dn++;
  else if(mergeCanon.has(c.claim_id)) dmc++;
  else if(mergeMember.has(c.claim_id)) dmm++;
  else if(supOld.has(c.claim_id)) dso++;
  else if(supNew.has(c.claim_id)) dsn++;
  else dnone++;
}
console.log("  disposition: novel="+dn+" mergeCanonical="+dmc+" mergeMember="+dmm+" supersededOld="+dso+" supersedingNew="+dsn+" quarantined="+dq+" none="+dnone);
console.log("");
console.log("=> novel MEMORY.md claims become STANDALONE records (potential unique content):", dn);
// show the novel ones (these are the data-loss risk if we blanket-quarantine)
let shown=0;
for(const c of mem){ if(novel.has(c.claim_id) && shown<25){ const firstLine=(c.title||c.text.split("\n").find(l=>l.trim())||"").slice(0,90); console.log("   - "+c.source_store+":"+c.source_path+"  ::  "+firstLine); shown++; } }
'

