cd /Users/luke/.dream-memory/migration-reconcile && npx --no-install -- node -e '
const fs=require("fs");
const claims=fs.readFileSync("ledger-claims.jsonl","utf8").trim().split("\n").map(l=>JSON.parse(l));
const manifest=JSON.parse(fs.readFileSync("manifest.json","utf8"));
const path=require("path");

const novel=new Set(); for(const d of manifest.decisions) if(d.verb==="novel") novel.add(d.id);
const isMem=(p)=>p.split("/").pop()==="MEMORY.md";

// corpus path index per store: set of source_paths
const pathsByStore={};
for(const c of claims){ (pathsByStore[c.source_store]=pathsByStore[c.source_store]||new Set()).add(c.source_path); }

const mem = claims.filter(c=>isMem(c.source_path) && novel.has(c.claim_id));
console.log("novel MEMORY.md index claims:", mem.length, "\n");

const stripFm=(t)=>{ const m=t.match(/^---\n[\s\S]*?\n---\n?/); return m? t.slice(m[0].length):t; };
const bulletRe=/^\s*[-*]\s+\[[^\]]*\]\(([^)]+)\)/;   // - [Title](link)
const headerRe=/^#{1,6}\s/;

let totUnresolvedBullets=0, totResolvedBullets=0, filesWithProse=0, totProseLines=0;
const proseSamples=[], unresolvedSamples=[];
for(const c of mem){
  const dir=path.posix.dirname(c.source_path);
  const body=stripFm(c.text);
  const lines=body.split("\n");
  let bullets=0, resolved=0, prose=0;
  const proseHere=[];
  for(const raw of lines){
    const line=raw.trim();
    if(!line) continue;
    if(headerRe.test(line)) continue;            // index header
    const bm=raw.match(bulletRe);
    if(bm){
      bullets++;
      let link=bm[1].split("#")[0].trim();
      // resolve relative to MEMORY.md dir
      let target = link.startsWith("/")? link.slice(1) : path.posix.normalize(path.posix.join(dir, link));
      const set=pathsByStore[c.source_store];
      if(set && (set.has(target)||set.has(link))) resolved++;
      else { if(unresolvedSamples.length<20) unresolvedSamples.push(c.source_store+":"+c.source_path+"  -> "+link+"  ["+raw.trim().slice(0,70)+"]"); }
      continue;
    }
    // a non-blank, non-header, non-bullet line = candidate unique prose
    // ignore pure list-continuation / TOC scaffolding markers
    if(line==="---"||/^<!--/.test(line)) continue;
    prose++; proseHere.push(line.slice(0,100));
  }
  totResolvedBullets+=resolved; totUnresolvedBullets+=(bullets-resolved); totProseLines+=prose;
  if(prose>0){ filesWithProse++; if(proseSamples.length<15) proseSamples.push({f:c.source_store+":"+c.source_path, n:prose, ex:proseHere.slice(0,4)}); }
}
console.log("BULLET RESOLUTION (does the linked doc exist as its own claim?):");
console.log("  resolved (redundant nav):", totResolvedBullets);
console.log("  UNRESOLVED (hook may be only trace):", totUnresolvedBullets);
console.log("");
console.log("NON-BULLET PROSE LINES (candidate unique facts):", totProseLines, "across", filesWithProse, "files");
console.log("");
console.log("=== unresolved-bullet samples ===");
for(const s of unresolvedSamples) console.log("  "+s);
console.log("");
console.log("=== prose samples (files with non-TOC content) ===");
for(const s of proseSamples){ console.log("  "+s.f+"  ("+s.n+" prose lines)"); for(const e of s.ex) console.log("       | "+e); }
'

