1	/**
2	 * P2c apply — DRY RUN (ADR 0009 / spec P2). The binding sign-off artifact.
3	 *
4	 * Reads the reconcile manifest + persisted ledger (read-only), runs {@link planApply},
5	 * writes every canonical record to a SCRATCH preview root, and emits APPLY-DIFF.md:
6	 * the exact files apply would create, what collapses (merge), and what drops from
7	 * active recall (supersede). It mutates NO real store and changes NO recall — the
8	 * real transactional swap into `~/.agents/memory` is a separate, gated step that
9	 * runs only after Luke approves this diff.
10	 *
11	 * Hard gate: aborts without writing if the plan is not complete (any unaccounted /
12	 * over-disposed claim) or if the plan's verb counts disagree with the manifest.
13	 *
14	 * Env:
15	 *   DREAM_RECONCILE_OUT   reconcile artifact dir (default ~/.dream-memory/migration-reconcile)
16	 *   DREAM_APPLY_PREVIEW   preview output dir     (default <OUT>/canonical-preview)
17	 *
18	 * Usage: pnpm tsx scripts/migrate-apply-dryrun.ts
19	 */
20	
21	import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
22	import { homedir } from "node:os";
23	import { basename, dirname, join } from "node:path";
24	
25	import { serializeCanonical } from "../src/canonical/serialize.ts";
26	import { type CanonicalRecord, claimToCanonical } from "../src/migration/apply/map-claim.ts";
27	import { type ApplyPlan, planApply } from "../src/migration/apply/plan.ts";
28	import { type Claim, ClaimSchema } from "../src/migration/ledger.ts";
29	import { type ReconciliationManifest, ReconciliationManifestSchema } from "../src/migration/reconcile-step.ts";
30	
31	const HOME = homedir();
32	
33	function envRoot(key: string, fallback: string): string {
34		const v = process.env[key];
35		return v && v.trim() ? v : fallback;
36	}
37	
38	/** Preview path for a record — mirrors the real two-root layout (global vs
39	 * per-project) under a single scratch tree so Luke can browse it as one dir. */
40	function previewPathFor(record: CanonicalRecord, previewRoot: string): string {
41		if (record.rootKind === "project" && record.projectSlug) {
42			return join(previewRoot, "projects", record.projectSlug, record.relPath);
43		}
44		return join(previewRoot, "global", record.relPath);
45	}
46	
47	function md(strings: TemplateStringsArray, ...values: unknown[]): string {
48		return strings.reduce((acc, s, i) => acc + s + (i < values.length ? String(values[i]) : ""), "");
49	}
50	
51	/** A TOC-index supersede artifact: a `MEMORY.md` index bullet promoted to a
52	 * standalone doc (low-harm; flagged so Luke can confirm it's not a real correction). */
53	function isTocArtifact(claim: Claim | undefined): boolean {
54		return claim ? basename(claim.source_path) === "MEMORY.md" : false;
55	}
56	
57	function buildReport(
58		plan: ApplyPlan,
59		byId: Map<string, Claim>,
60		manifest: ReconciliationManifest,
61		previewRoot: string,
62		generatedAt: string,
63	): string {
64		const byPermalink = new Map(plan.records.map((r) => [r.permalink, r]));
65		const title = (id: string): string => {
66			const claim = byId.get(id);
67			return claim ? claimToCanonical(claim).frontmatter.title : `(unknown ${id.slice(0, 8)})`;
68		};
69	
70		const merges = plan.records.filter((r) => r.frontmatter.merged_from?.length).sort((a, b) => a.permalink.localeCompare(b.permalink));
71		const supersedes = plan.records.filter((r) => r.frontmatter.status === "superseded").sort((a, b) => a.permalink.localeCompare(b.permalink));
72		const novel = plan.records.filter((r) => r.frontmatter.status === "active" && !r.frontmatter.merged_from?.length);
73	
74		const quarantineByReason: Record<string, number> = {};
75		for (const q of manifest.quarantined) quarantineByReason[q.reason] = (quarantineByReason[q.reason] ?? 0) + 1;
76	
77		const ns = Object.entries(plan.stats.by_namespace).sort(([a], [b]) => a.localeCompare(b));
78		const globalRecords = plan.records.filter((r) => r.rootKind === "global");
79		const projectRecords = plan.records.filter((r) => r.rootKind === "project");
80		const projectCounts: Record<string, number> = {};
81		for (const r of projectRecords) {
82			const slug = r.projectSlug ?? "(none)";
83			projectCounts[slug] = (projectCounts[slug] ?? 0) + 1;
84		}
85		const projectSlugs = Object.entries(projectCounts).sort(([, a], [, b]) => b - a);
86	
87		const lines: string[] = [];
88		const p = (s = ""): void => void lines.push(s);
89	
90		p(md`# P2c apply — dry-run diff (NOT applied)`);
91		p();
92		p(md`Generated: ${generatedAt}`);
93		p(md`Source manifest: \`${manifest.generated_at}\` (threshold ${manifest.threshold}, version ${manifest.version})`);
94		p(md`Preview tree: \`${previewRoot}\` — ${plan.records.length} files written, no real store touched.`);
95		p();
96		p(md`**This changes nothing live.** It shows exactly what the transactional apply *would* write into the canonical store. Recall is untouched until you approve this diff.`);
97		p();
98	
99		p(md`## No-drops accounting (the gate)`);
100		p();
101		p(md`| check | value |`);
102		p(md`| --- | --- |`);
103		p(md`| eligible claims | ${manifest.eligible_claims} |`);
104		p(md`| quarantined (excluded, kept on disk) | ${plan.stats.quarantined} |`);
105		p(md`| record bearers written | ${plan.stats.total_records} |`);
106		p(md`| └ active (surface in recall) | ${plan.stats.active} |`);
107		p(md`| └ superseded (kept, drop from recall) | ${plan.stats.superseded} |`);
108		p(md`| merge canonicals (collapse ≥2 claims) | ${plan.stats.merged_records} |`);
109		p(md`| merge members collapsed (no own record) | ${plan.stats.collapsed_members} |`);
110		p(md`| **unaccounted (silent drops)** | **${plan.unaccounted.length}** |`);
111		p(md`| **over-disposed (double-written)** | **${plan.over_disposed.length}** |`);
112		p(md`| complete | ${plan.complete ? "✅ yes" : "❌ NO"} |`);
113		p();
114		p(md`Identity: \`${plan.stats.total_records} bearers + ${plan.stats.collapsed_members} collapsed = ${plan.stats.total_records + plan.stats.collapsed_members} = ${manifest.eligible_claims} eligible\`. Every eligible claim is either written or folded into a merge — nothing is lost.`);
115		p();
116	
117		p(md`## Routing — global vs per-project root`);
118		p();
119		p(md`| root | records |`);
120		p(md`| --- | --- |`);
121		p(md`| global (\`~/.agents/memory\`) | ${globalRecords.length} |`);
122		p(md`| per-project (\`~/.agents/projects/<sanitize(gitRoot)>/memory\`) | ${projectRecords.length} across ${projectSlugs.length} projects |`);
123		p();
124		p(md`### By namespace (summed across both roots)`);
125		p();
126		p(md`| namespace | records |`);
127		p(md`| --- | --- |`);
128		for (const [dir, n] of ns) p(md`| \`${dir}\` | ${n} |`);
129		p();
130		p(md`### Top projects`);
131		p();
132		p(md`| project slug | records |`);
133		p(md`| --- | --- |`);
134		for (const [slug, n] of projectSlugs.slice(0, 15)) p(md`| ${slug} | ${n} |`);
135		p(md`_…and ${Math.max(0, projectSlugs.length - 15)} more projects._`);
136		p();
137		p(`> Migrated records land in \`harness/<origin>\` or \`episodic\` — never \`shared\` (P4 promotes to shared). The project slug→gitRoot resolution happens in the gated apply.`);
138		p();
139	
140		p(md`## Merges (${merges.length}) — parallel captures collapsed to one canonical`);
141		p();
142		p(`Non-destructive: every collapsed member is recorded in the canonical's \`merged_from\`. A wrong merge is reversible — the member claim_id is right there.`);
143		p();
144		for (const r of merges) {
145			p(md`- **${r.permalink}** — "${r.frontmatter.title}" (\`${r.relPath.slice(0, r.relPath.lastIndexOf("/"))}\`)`);
146			for (const memberId of r.frontmatter.merged_from ?? []) {
147				const m = byId.get(memberId);
148				p(md`    - collapses \`${memberId.slice(0, 8)}\` "${title(memberId)}" — ${m ? `${m.source_store}:${m.source_path}` : "(claim not in ledger)"}`);
149			}
150		}
151		p();
152	
153		p(md`## Supersedes (${supersedes.length}) — temporal corrections; old kept, drops from recall`);
154		p();
155		p(`Each superseded record stays on disk with \`status: superseded\` + \`superseded_by\`, so it is excluded from active recall but fully recoverable (flip the status back). TOC-index artifacts (\`MEMORY.md\` index bullets) are flagged — low-harm, confirm they aren't real corrections.`);
156		p();
157		let tocCount = 0;
158		for (const r of supersedes) {
159			const newPermalink = r.frontmatter.superseded_by?.[0] ?? "(none)";
160			const newRec = byPermalink.get(newPermalink);
161			const claim = byId.get(r.claim_id);
162			const toc = isTocArtifact(claim);
163			if (toc) tocCount += 1;
164			p(md`- ${toc ? "🗂️ " : ""}**${r.permalink}** "${r.frontmatter.title}" ${claim ? `(${claim.source_store}:${claim.source_path})` : ""}`);
165			p(md`    - → superseded by **${newPermalink}** "${newRec?.frontmatter.title ?? "(new record)"}"`);
166		}
167		p();
168		p(md`${tocCount} of ${supersedes.length} supersedes are \`MEMORY.md\` TOC-index artifacts (🗂️). ${tocCount > 0 ? "Follow-up: quarantine MEMORY.md index bullets in the extractors (spec P2 cleanup)." : ""}`);
169		p();
