// 4a. Write guard — this is the only destructive op (rm -rf). previewRoot/outDir are
// already resolve()'d, so a `$outDir/../../x` traversal can't textually masquerade as
// "under outDir". Allow only a path strictly under the reconcile out dir or one whose
// own basename is `canonical-preview`; never the out dir itself, home, or a filesystem root.
const underOut = previewRoot.startsWith(outDir + sep);
const isNamedPreview = basename(previewRoot) === "canonical-preview";
if (!underOut && !isNamedPreview) {
	throw new Error(`refusing to rm -rf a path that is neither under ${outDir} nor an explicit canonical-preview dir: ${previewRoot}`);
}
if (previewRoot === outDir || previewRoot === resolve(HOME) || dirname(previewRoot) === previewRoot) {
	throw new Error(`refusing to rm -rf a protected dir (out dir / home / root): ${previewRoot}`);
}

// 4b. Collision guard — detect (before any write) the rare case where two records
// resolve to the same path (slug + claim_id[:8] birthday collision). A silent
// overwrite would make "N records written" a lie while the gate still reads complete.
const pathFor = (record: CanonicalRecord): string => previewPathFor(record, previewRoot);
const distinctPaths = new Set(plan.records.map(pathFor));
if (distinctPaths.size !== plan.records.length) {
	console.error(`\n❌ ABORT — ${plan.records.length} records map to only ${distinctPaths.size} distinct paths; a write would silently overwrite. Nothing written.`);
	process.exitCode = 1;
	return;
}

// 4c. Write the preview tree (scratch only — regenerated each run).
await rm(previewRoot, { recursive: true, force: true });
let written = 0;
for (const record of plan.records) {
	const filePath = pathFor(record);
	await mkdir(dirname(filePath), { recursive: true });
	await writeFile(filePath, serializeCanonical(record.frontmatter, record.body), "utf8");
	written += 1;
}
console.log(`wrote ${written} records under ${previewRoot}`);

