1	/**
2	 * Temporal decay scorer — dynamic-tail ranking multiplier only.
3	 *
4	 * MIRROR of `extensions/pi-memory/src/decay.ts` (canonical home). dream-memory is
5	 * a separate npm package and cannot import pi-memory's source at runtime, so this
6	 * pure, dependency-free function is duplicated verbatim. Keep the two in sync; a
7	 * parity test (`tests/decay.spec.ts`) pins the shared properties.
8	 *
9	 * CACHE SAFETY: pure math, produces a 0..1 multiplier applied to recall
10	 * candidates in the dynamic tail (after the cache breakpoint) — never the prefix.
11	 *
12	 * Formula
13	 * -------
14	 *   recency    = 2 ^ (-ageDays / halfLifeDays)   // 1.0 at age 0, 0.5 at one half-life, → 0 as age → ∞
15	 *   usageBoost = 1 - 1 / (1 + usageCount)         // 0 at usage 0, 0.5 at 1, 0.67 at 2, … → 1 (bounded)
16	 *   weight     = recency + (1 - recency) * usageBoost * BLEND
17	 *
18	 * `ageDays` is measured from the most recent of createdAt / lastUsedAt; BLEND
19	 * caps how far usage lifts a stale memory back toward 1.0.
20	 */
21	
22	export const DECAY_USAGE_BLEND = 0.5;
23	const MS_PER_DAY = 86_400_000;
24	
25	export interface DecayInput {
26		createdAt?: string | number | null;
27		lastUsedAt?: string | number | null;
28		usageCount?: number | null;
29		now: number;
30		halfLifeDays: number;
31	}
32	
33	/** Returns a 0..1 decay multiplier for a memory's base recall score. */
34	export function decayWeight(input: DecayInput): number {
35		const halfLifeDays = input.halfLifeDays > 0 ? input.halfLifeDays : 30;
36		const anchorMs = Math.max(toEpochMs(input.createdAt), toEpochMs(input.lastUsedAt));
37		if (!Number.isFinite(anchorMs) || anchorMs <= 0) return 1;
38	
39		const ageDays = Math.max(0, (input.now - anchorMs) / MS_PER_DAY);
40		const recency = Math.pow(2, -ageDays / halfLifeDays);
41	
42		const usageCount = Math.max(0, input.usageCount ?? 0);
43		const usageBoost = 1 - 1 / (1 + usageCount);
44	
45		const weight = recency + (1 - recency) * usageBoost * DECAY_USAGE_BLEND;
46		return clamp01(weight);
47	}
48	
49	function toEpochMs(value: string | number | null | undefined): number {
50		if (value === null || value === undefined) return 0;
51		if (typeof value === "number") return Number.isFinite(value) ? value : 0;
52		const parsed = Date.parse(value);
53		return Number.isFinite(parsed) ? parsed : 0;
54	}
55	
56	function clamp01(value: number): number {
57		if (!Number.isFinite(value)) return 1;
58		if (value < 0) return 0;
59		if (value > 1) return 1;
60		return value;
61	}
