/**
 * Temporal decay scorer — dynamic-tail ranking multiplier only.
 *
 * MIRROR of `extensions/pi-memory/src/decay.ts` (canonical home). dream-memory is
 * a separate npm package and cannot import pi-memory's source at runtime, so this
 * pure, dependency-free function is duplicated verbatim. Keep the two in sync; a
 * parity test (`tests/decay.spec.ts`) pins the shared properties.
 *
 * CACHE SAFETY: pure math, produces a 0..1 multiplier applied to recall
 * candidates in the dynamic tail (after the cache breakpoint) — never the prefix.
 *
 * Formula
 * -------
 *   recency    = 2 ^ (-ageDays / halfLifeDays)   // 1.0 at age 0, 0.5 at one half-life, → 0 as age → ∞
 *   usageBoost = 1 - 1 / (1 + usageCount)         // 0 at usage 0, 0.5 at 1, 0.67 at 2, … → 1 (bounded)
 *   weight     = recency + (1 - recency) * usageBoost * BLEND
 *
 * `ageDays` is measured from the most recent of createdAt / lastUsedAt; BLEND
 * caps how far usage lifts a stale memory back toward 1.0.
 */

export const DECAY_USAGE_BLEND = 0.5;
const MS_PER_DAY = 86_400_000;

export interface DecayInput {
	createdAt?: string | number | null;
	lastUsedAt?: string | number | null;
	usageCount?: number | null;
	now: number;
	halfLifeDays: number;
}

/** Returns a 0..1 decay multiplier for a memory's base recall score. */
export function decayWeight(input: DecayInput): number {
	const halfLifeDays = input.halfLifeDays > 0 ? input.halfLifeDays : 30;
	const anchorMs = Math.max(toEpochMs(input.createdAt), toEpochMs(input.lastUsedAt));
	if (!Number.isFinite(anchorMs) || anchorMs <= 0) return 1;

	const ageDays = Math.max(0, (input.now - anchorMs) / MS_PER_DAY);
	const recency = Math.pow(2, -ageDays / halfLifeDays);

	const usageCount = Math.max(0, input.usageCount ?? 0);
	const usageBoost = 1 - 1 / (1 + usageCount);

	const weight = recency + (1 - recency) * usageBoost * DECAY_USAGE_BLEND;
	return clamp01(weight);
}

function toEpochMs(value: string | number | null | undefined): number {
	if (value === null || value === undefined) return 0;
	if (typeof value === "number") return Number.isFinite(value) ? value : 0;
	const parsed = Date.parse(value);
	return Number.isFinite(parsed) ? parsed : 0;
}

function clamp01(value: number): number {
	if (!Number.isFinite(value)) return 1;
	if (value < 0) return 0;
	if (value > 1) return 1;
	return value;
}

