1	/**
2	 * dream-memory active-recall — hit selection, freshness, decay.
3	 *
4	 * Builds the selector prompt, parses selected permalinks, applies freshness
5	 * caveats + temporal decay ranking, assembles injected recall content.
6	 * Extracted from active-memory.ts (009).
7	 */
8	
9	import { stat } from "node:fs/promises";
10	import { randomUUID } from "node:crypto";
11	import type { SearchHit } from "../store.ts";
12	import type { RecallConfig } from "./recall-state.ts";
13	import { decayWeightForPath, loadDecayConfig, openPiMemorySidecar } from "../memory-decay.ts";
14	
15	const LEAN_RECALL_SYSTEM_PROMPT = `You select memory hits for the current user prompt.
16	Return JSON only: {"selected":["permalink"]}.
17	Select up to 5 permalinks that clearly help answer or execute the prompt.
18	If none clearly help, return {"selected":[]}.
19	No prose, markdown, reasoning, or invented facts.`;
20	
21	export const RECALL_PROMPT_VARIANTS: Record<RecallConfig["prompt_variant"], string> = {
22		compact: LEAN_RECALL_SYSTEM_PROMPT,
23		terse: LEAN_RECALL_SYSTEM_PROMPT,
24		expanded: LEAN_RECALL_SYSTEM_PROMPT,
25		cot: LEAN_RECALL_SYSTEM_PROMPT,
26	};
27	
28	export const RECALL_SYSTEM_PROMPT = LEAN_RECALL_SYSTEM_PROMPT;
29	
30	/**
31	 * Strip a leading YAML frontmatter block (`---\n...\n---`) from a snippet.
32	 *
33	 * QMD's BM25 chunker treats the frontmatter block as the first searchable
34	 * chunk, so for queries that match a title keyword (e.g. "QMD chosen over
35	 * basic-memory") the highest-scoring snippet is YAML metadata, not prose.
36	 * The active-recall haiku then sees a wall of keys and colons and either
37	 * outputs NONE or hallucinates prose. This strip is a per-snippet defense:
38	 * if the matched chunk leads with frontmatter, drop it and use whatever
39	 * prose follows.
40	 *
41	 * Conservative: only strips when the snippet *starts* with `---` and the
42	 * closing fence is found. Pass-through otherwise. Internal `---` separators
43	 * mid-prose are untouched.
44	 */
45	export function stripFrontmatter(text: string): string {
46		if (!text.startsWith("---")) return text;
47		// Match leading frontmatter: --- (newline) ... (newline) ---
48		const m = /^---\r?\n[\s\S]*?\r?\n---\r?\n?/.exec(text);
49		if (!m) return text;
50		return text.slice(m[0].length).trim();
51	}
52	
53	export function buildRecallPrompt(prompt: string, hits: SearchHit[], priorContext?: string): string {
54		const hitsBlock = hits
55			.slice(0, 10)
56			.map((h, i) => {
57				const raw = h.matched_chunk ?? h.content ?? "";
58				const body = stripFrontmatter(raw).slice(0, 500);
59				return `### hit_${i + 1}\npermalink: ${h.permalink}\ntitle: ${h.title}\nscore: ${h.score?.toFixed?.(3) ?? h.score}\nsnippet:\n${body}`;
60			})
61			.join("\n\n");
62		const contextBlock =
63			priorContext && priorContext.trim().length > 0
64				? `\nPrior conversation context (disambiguation only; latest user prompt wins):\n${priorContext.trim()}\n`
65				: "";
66		return `Latest user prompt:
67	${prompt}${contextBlock}
68	
69	Candidate memories:
70	${hitsBlock}
71	
72	Selection rules:
73	- Another model will answer the user; do not answer the user.
74	- Select a memory only if it clearly helps with the latest user prompt.
75	- Prefer NONE/empty selection for weak, broad, speculative, or merely topical matches.
76	- If the user asks to ignore memory, select nothing.
77	- Treat old code/path claims as context only; the answering model must verify current files.
78	
79	Return JSON only: {"selected":["permalink"]}. Use an empty array when nothing is clearly useful.`;
80	}
81	
82	function stripJsonFence(text: string): string {
83		return text
84			.trim()
85			.replace(/^```(?:json)?\s*/i, "")
86			.replace(/\s*```$/, "")
87			.trim();
88	}
89	
90	function normaliseSelectedPermalink(value: string): string {
91		return value
92			.trim()
93			.replace(/^qmd:\/\/[^/]+\//, "")
94			.replace(/\.md$/, "");
95	}
96	
97	export function parseSelectedPermalinks(text: string, validPermalinks: readonly string[]): string[] {
98		const valid = new Set(validPermalinks);
99		let parsed: unknown;
100		try {
101			parsed = JSON.parse(stripJsonFence(text));
102		} catch {
103			return [];
104		}
105		const raw = Array.isArray(parsed)
106			? parsed
107			: parsed && typeof parsed === "object"
108				? (parsed as { selected?: unknown; selected_memories?: unknown; permalinks?: unknown }).selected
109					?? (parsed as { selected_memories?: unknown }).selected_memories
110					?? (parsed as { permalinks?: unknown }).permalinks
111				: undefined;
112		if (!Array.isArray(raw)) return [];
113		const selected: string[] = [];
114		for (const item of raw) {
115			if (typeof item !== "string") continue;
116			const permalink = normaliseSelectedPermalink(item);
117			if (!valid.has(permalink) || selected.includes(permalink)) continue;
118			selected.push(permalink);
119			if (selected.length >= 5) break;
120		}
121		return selected;
122	}
123	
124	export function selectedHitsFromText(text: string, hits: SearchHit[]): SearchHit[] {
125		const byPermalink = new Map(hits.map((h) => [h.permalink, h]));
126		return parseSelectedPermalinks(text, hits.map((h) => h.permalink))
127			.map((permalink) => byPermalink.get(permalink))
128			.filter((h): h is SearchHit => h !== undefined);
129	}
130	
131	export function isPrimaryLookupHit(hit: SearchHit): boolean {
132		const key = `${hit.permalink}\n${hit.file_path ?? ""}`;
133		if (/\b(memory|profile|project|inbox|dream-memory-profile|dream-memory-project|scars|changes)\//.test(key)) return false;
134		return /(^|\n)(projects|workspace-info\/|docs\/|[a-z0-9._-]+)(\.md)?(\n|$)/i.test(key);
135	}
136	
137	/**
138	 * v3 freshness warnings — mirrors Claude Code's `memdir/memoryAge.ts`.
139	 *
140	 * Tag each memory with an age-aware caveat before injection. Stale ≠ wrong,
141	 * but stale file:line citations get asserted as fact too often without one.
142	 *
143	 * Days are floor-rounded; <=1 day = no caveat (fresh enough); >=30 days =
144	 * stronger "historical only" tone. Wording copied verbatim from CC's MIT-
145	 * licensed memoryFreshnessText() for the canonical case.
146	 */
147	export function memoryAgeDays(mtimeMs: number, nowMs: number = Date.now()): number {
148		return Math.max(0, Math.floor((nowMs - mtimeMs) / 86_400_000));
149	}
150	
151	export function freshnessCaveat(days: number): string {
152		if (days <= 1) return "";
153		if (days >= 30) {
154			return (
155				`<system-reminder>This memory is ${days} days old and has not been refreshed since. ` +
156				`Treat as historical only; verify against current code before asserting as fact.</system-reminder>`
157			);
158		}
159		return (
160			`<system-reminder>This memory is ${days} days old. ` +
161			`Memories are point-in-time observations, not live state — ` +
162			`claims about code behavior or file:line citations may be outdated. ` +
163			`Verify against current code before asserting as fact.</system-reminder>`
164		);
165	}
166	
167	/** Best-effort mtime lookup. Returns undefined if path unknown or stat fails. */
168	async function hitMtimeMs(hit: SearchHit): Promise<number | undefined> {
169		if (!hit.file_path) return undefined;
170		try {
171			const s = await stat(hit.file_path);
172			return s.mtimeMs;
173		} catch {
174			return undefined;
175		}
176	}
177	
178	function selectedMemoryBlock(hit: SearchHit, caveat: string): string {
179		const raw = hit.matched_chunk ?? hit.content ?? "";
180		const body = stripFrontmatter(raw).trim().slice(0, 1200);
181		const title = hit.title && hit.title !== hit.permalink ? `Title: ${hit.title}\n` : "";
182		return [caveat, `Memory: ${hit.permalink}`, title ? title.trimEnd() : "", body].filter(Boolean).join("\n");
183	}
184	
185	export interface FreshnessSummary {
186		permalinks: string[];
187		maxAgeDays: number;
188	}
189	
190	export async function buildSelectedRecallContent(
191		hits: SearchHit[],
192		opts: { nowMs?: number; logger?: (m: string) => void } = {},
193	): Promise<{ content: string; freshness: FreshnessSummary }> {
194		const now = opts.nowMs ?? Date.now();
195		const withAges = await Promise.all(
196			hits.map(async (h) => {
197				const m = await hitMtimeMs(h);
198				const days = m === undefined ? 0 : memoryAgeDays(m, now);
199				return { hit: h, days, caveat: freshnessCaveat(days) };
200			}),
201		);
202		const blocks = withAges.map(({ hit, caveat }) => selectedMemoryBlock(hit, caveat));
203		const flagged = withAges.filter((w) => w.caveat.length > 0);
204		const maxAgeDays = withAges.reduce((m, w) => Math.max(m, w.days), 0);
205		if (flagged.length > 0 && opts.logger) {
206			opts.logger(
207				`[active-memory.freshness] permalinks=${flagged.map((w) => w.hit.permalink).join(",")} maxAgeDays=${maxAgeDays}`,
208			);
209		}
210		return {
211			content: `<active-recall>\n${blocks.join("\n\n")}\n</active-recall>`,
212			freshness: { permalinks: flagged.map((w) => w.hit.permalink), maxAgeDays },
213		};
214	}
215	
216	/**
217	 * Back-compat guard for older selector prompts that returned a NONE sentinel.
218	 * Current selector output is JSON; if a model still emits NONE, treat it as
219	 * no selected memories rather than injecting prose.
220	 */
221	export function isNoRelevantRecall(text: string): boolean {
222		const firstLine = text
223			.trim()
224			.split(/\r?\n/, 1)[0]
225			?.trim()
226			.replace(/[.!]+$/, "");
227		return firstLine === "NONE";
228	}
229	
230	const TRIVIAL_RECALL_PROMPTS = new Set([
231		"?",
232		"again",
233		"continue",
234		"push",
235		"pull",
236		"thanks",
237		"thankyou",
238		"please",
239		"status",
240		"debug",
241		"deploy",
242		"review",
243		"merge",
244		"done",
245		"okay",
246		"cool",
247	]);
248	
249	export function isTrivialRecallPrompt(input: string): boolean {
250		const normalised = input.trim().toLowerCase().replace(/[.!]+$/, "");
251		return TRIVIAL_RECALL_PROMPTS.has(normalised);
252	}
253	
254	export function isLikelyRecallEntityPrompt(input: string): boolean {
255		const prompt = input.trim();
256		if (prompt.length < 6 || prompt.length > 80) return false;
257		const tokens = prompt.split(/\s+/);
258		if (tokens.length > 3) return false;
259		return tokens.every((token) => {
260			if (isTrivialRecallPrompt(token)) return false;
261			return /^[a-z0-9][a-z0-9._-]{5,}$/i.test(token);
262		});
263	}
264	
265	/**
266	 * Apply temporal decay (mem0-inspired) to recall candidate scores BEFORE the
267	 * curator selects. Stale / never-recalled memories sink in ranking; recently
268	 * recalled ones keep their weight. Usage STATE comes from pi-memory's
269	 * `memory_usage` sidecar — never the cached prefix. Mutates `hits[].score` in
270	 * place. Untracked hits (e.g. dream-memory's own wiki files) get a neutral 1.0
271	 * multiplier. Never throws — decay is best-effort ranking sugar.
272	 */
273	export function applyDecayRanking(hits: SearchHit[], log: (m: string) => void, nowMs: number = Date.now()): void {
274		const cfg = loadDecayConfig();
275		if (!cfg.enabled) return;
276		const paths = hits.map((h) => h.file_path).filter((p): p is string => typeof p === "string" && p.length > 0);
277		if (paths.length === 0) return;
278		const sidecar = openPiMemorySidecar();
279		if (!sidecar) return;
280		try {
281			const usage = sidecar.usageByPath(paths);
282			if (usage.size === 0) return;
283			let decayed = 0;
284			for (const hit of hits) {
285				if (!hit.file_path || typeof hit.score !== "number") continue;
286				const w = decayWeightForPath(hit.file_path, usage, { now: nowMs, halfLifeDays: cfg.halfLifeDays });
287				if (w < 1) {
288					hit.score = hit.score * w;
289					decayed++;
290				}
291			}
292			if (decayed > 0) log(`[active-recall] decay applied to ${decayed}/${hits.length} candidates`);
293		} catch (err) {
294			log(`[active-recall] decay ranking skipped: ${(err as Error).message}`);
295		} finally {
296			sidecar.close();
297		}
298	}
299	
300	/**
301	 * Record recall usage for the selected memory paths in pi-memory's `memory_usage`
302	 * sidecar. This increments usage_count + refreshes last_used_at, which is what
303	 * protects a recalled memory from decay-driven auto-delete. Sidecar-only write —
304	 * cache-safe. Never throws.
305	 */
306	export function recordRecallUsage(hits: SearchHit[], log: (m: string) => void): void {
307		if (loadDecayConfig().enabled === false) return;
308		const paths = hits.map((h) => h.file_path).filter((p): p is string => typeof p === "string" && p.length > 0);
309		if (paths.length === 0) return;
310		const sidecar = openPiMemorySidecar();
311		if (!sidecar) return;
312		try {
313			sidecar.recordMemoryUsage(paths, randomUUID());
314		} catch (err) {
315			log(`[active-recall] usage record skipped: ${(err as Error).message}`);
316		} finally {
317			sidecar.close();
318		}
319	}
320

