1	/**
2	 * Read/write access to the pi-memory temporal-decay sidecar from the dream-memory
3	 * (read) side.
4	 *
5	 * pi-memory owns the SQLite store and the canonical decay methods (see
6	 * `extensions/pi-memory/src/db.ts` MemoryDb.recordMemoryUsage / decayCandidates /
7	 * deleteMemoryFile and `extensions/pi-memory/src/decay.ts`). dream-memory is a
8	 * *separate npm package* installed in its own node_modules, so it cannot import
9	 * pi-memory's MemoryDb (which pulls in better-sqlite3 + effect). Per the task's
10	 * blessed fallback we open the same sqlite file directly with Node's built-in
11	 * `node:sqlite` (Node ≥22) and mirror the identical SQL. Keep these queries in
12	 * sync with pi-memory's MemoryDb.
13	 *
14	 * CACHE SAFETY: every write here targets the `memory_usage` sidecar or deletes a
15	 * row/file on disk. None of it touches the cached system-prompt prefix. The decay
16	 * weight is only ever applied to dynamic-tail recall candidates.
17	 */
18	
19	import { existsSync, readFileSync } from "node:fs";
20	import { createRequire } from "node:module";
21	import { homedir } from "node:os";
22	import { join } from "node:path";
23	
24	import { decayWeight } from "./decay.ts";
25	
26	const nodeRequire = createRequire(import.meta.url);
27	
28	export interface DecayConfig {
29		enabled: boolean;
30		halfLifeDays: number;
31		autoDelete: {
32			enabled: boolean;
33			staleAfterDays: number;
34			maxUsage: number;
35			maxPerRun: number;
36		};
37	}
38	
39	export const DEFAULT_DECAY_CONFIG: DecayConfig = {
40		enabled: true,
41		halfLifeDays: 30,
42		autoDelete: { enabled: true, staleAfterDays: 90, maxUsage: 0, maxPerRun: 20 },
43	};
44	
45	/** Minimal structural view of node:sqlite's DatabaseSync we rely on. */
46	interface SqliteSync {
47		prepare(sql: string): {
48			run(...params: unknown[]): unknown;
49			get(...params: unknown[]): unknown;
50			all(...params: unknown[]): unknown[];
51		};
52		close(): void;
53	}
54	
55	export interface UsageRow {
56		usageCount: number;
57		lastUsedAt?: string;
58		createdAt?: string;
59	}
60	
61	export interface DecayCandidate {
62		path: string;
63		scope: string;
64		type: string;
65		createdAt?: string;
66		usageCount: number;
67		lastUsedAt?: string;
68	}
69	
70	/** Resolve pi-memory's sqlite path (mirrors pi-memory `memoryDbPath`). */
71	export function piMemoryDbPath(env: NodeJS.ProcessEnv = process.env): string {
72		if (env.PI_MEMORY_DB) return env.PI_MEMORY_DB;
73		const root = env.PI_MEMORY_DIR?.length ? env.PI_MEMORY_DIR : join(homedir(), ".pi", "agent", "memory");
74		return join(root, "db", "memory.sqlite");
75	}
76	
77	/**
78	 * Open the pi-memory sqlite read/write. Returns undefined if the file does not
79	 * exist yet (fresh machine) or node:sqlite is unavailable — callers must treat a
80	 * missing handle as "decay disabled, neutral ranking".
81	 */
82	export function openPiMemorySidecar(path = piMemoryDbPath()): MemoryDecayDb | undefined {
83		if (!existsSync(path)) return undefined;
84		try {
85			// Lazy require so environments without node:sqlite (or with it stubbed)
86			// degrade gracefully instead of throwing at import time.
87			const { DatabaseSync } = nodeRequire("node:sqlite") as { DatabaseSync: new (p: string) => SqliteSync };
88			return new MemoryDecayDb(new DatabaseSync(path));
89		} catch {
90			return undefined;
91		}
92	}
93	
94	/**
95	 * Thin mirror of the pi-memory decay methods, backed by node:sqlite. SQL is kept
96	 * byte-equivalent to `extensions/pi-memory/src/db.ts`.
97	 */
98	export class MemoryDecayDb {
99		constructor(private readonly db: SqliteSync) {}
100	
101		close(): void {
102			try {
103				this.db.close();
104			} catch {
105				/* best effort */
106			}
107		}
108	
109		/** Usage + createdAt for the given paths, keyed by path. Missing paths omitted. */
110		usageByPath(paths: string[]): Map<string, UsageRow> {
111			const out = new Map<string, UsageRow>();
112			if (paths.length === 0) return out;
113			const placeholders = paths.map(() => "?").join(", ");
114			const rows = this.db
115				.prepare(`
116					SELECT mf.path AS path, mf.created_at AS createdAt,
117					       COALESCE(mu.usage_count, 0) AS usageCount, mu.last_used_at AS lastUsedAt
118					FROM memory_files mf
119					LEFT JOIN memory_usage mu ON mu.path = mf.path
120					WHERE mf.path IN (${placeholders})
121				`)
122				.all(...paths) as Array<{ path: string; createdAt?: string; usageCount: number; lastUsedAt?: string }>;
123			for (const row of rows) {
124				out.set(row.path, {
125					usageCount: row.usageCount ?? 0,
126					...(row.lastUsedAt ? { lastUsedAt: row.lastUsedAt } : {}),
127					...(row.createdAt ? { createdAt: row.createdAt } : {}),
128				});
129			}
130			return out;
131		}
132	
133		/** Mirror of MemoryDb.recordMemoryUsage. */
134		recordMemoryUsage(paths: string[], recallEventId: string, scores: Record<string, number> = {}): void {
135			if (paths.length === 0) return;
136			const now = new Date().toISOString();
137			const stmt = this.db.prepare(`
138				INSERT INTO memory_usage (path, usage_count, last_used_at, last_recall_event_id, last_score)
139				VALUES (?, 1, ?, ?, ?)
140				ON CONFLICT(path) DO UPDATE SET
141					usage_count = memory_usage.usage_count + 1,
142					last_used_at = excluded.last_used_at,
143					last_recall_event_id = excluded.last_recall_event_id,
144					last_score = COALESCE(excluded.last_score, memory_usage.last_score)
145			`);
146			for (const path of paths) {
147				const score = scores[path];
148				stmt.run(path, now, recallEventId, typeof score === "number" ? score : null);
149			}
150		}
151	
152		/** Mirror of MemoryDb.decayCandidates. */
153		decayCandidates(opts: { staleAfterDays: number; maxUsage: number; limit?: number }): DecayCandidate[] {
154			const cutoff = new Date(Date.now() - opts.staleAfterDays * 86_400_000).toISOString();
155			const limit = opts.limit ?? 100;
156			return this.db
157				.prepare(`
158					SELECT mf.path AS path, mf.scope AS scope, mf.type AS type, mf.created_at AS createdAt,
159					       COALESCE(mu.usage_count, 0) AS usageCount, mu.last_used_at AS lastUsedAt
160					FROM memory_files mf
161					LEFT JOIN memory_usage mu ON mu.path = mf.path
162					WHERE mf.active = 1
163					  AND mf.created_at IS NOT NULL AND mf.created_at < ?
164					  AND COALESCE(mu.usage_count, 0) <= ?
165					  AND (mu.last_used_at IS NULL OR mu.last_used_at < ?)
166					ORDER BY mf.created_at ASC
167					LIMIT ?
168				`)
169				.all(cutoff, opts.maxUsage, cutoff, limit) as DecayCandidate[];
170		}
171	
172		/** Mirror of MemoryDb.deleteMemoryFile. */
173		deleteMemoryFile(path: string): { path: string; scope: string; type: string } | undefined {
174			const row = this.db.prepare("SELECT path, scope, type FROM memory_files WHERE path = ?").get(path) as
175				| { path: string; scope: string; type: string }
176				| undefined;
177			if (!row) return undefined;
178			this.db.prepare("DELETE FROM memory_usage WHERE path = ?").run(path);
179			this.db.prepare("DELETE FROM memory_files WHERE path = ?").run(path);
180			return row;
181		}
182	}
183	
184	/**
185	 * Compute a decay multiplier for a memory at `path` given a usage map. Returns 1
186	 * (neutral) when the path is untracked (e.g. dream-memory's own wiki files that
187	 * are not in pi-memory's memory_files table) so we never penalise memories we
188	 * cannot date.
189	 */
190	export function decayWeightForPath(
191		path: string,
192		usage: Map<string, UsageRow>,
193		opts: { now: number; halfLifeDays: number },
194	): number {
195		const row = usage.get(path);
196		if (!row) return 1;
197		return decayWeight({
198			now: opts.now,
199			halfLifeDays: opts.halfLifeDays,
200			usageCount: row.usageCount,
201			...(row.createdAt ? { createdAt: row.createdAt } : {}),
202			...(row.lastUsedAt ? { lastUsedAt: row.lastUsedAt } : {}),
203		});
204	}
205	
206	/** Read pi-memory's decay config from global settings.json + env (L3/L4). */
207	export function loadDecayConfig(env: NodeJS.ProcessEnv = process.env): DecayConfig {
208		const base: DecayConfig = {
209			enabled: DEFAULT_DECAY_CONFIG.enabled,
210			halfLifeDays: DEFAULT_DECAY_CONFIG.halfLifeDays,
211			autoDelete: { ...DEFAULT_DECAY_CONFIG.autoDelete },
212		};
213		try {
214			const settingsPath = join(env.PI_CODING_AGENT_DIR || join(homedir(), ".pi", "agent"), "settings.json");
215			if (existsSync(settingsPath)) {
216				const raw = readFileSync(settingsPath, "utf8");
217				const settings = JSON.parse(raw) as { extensionConfig?: Record<string, unknown> };
218				const decay = (settings.extensionConfig?.["pi-memory"] as { decay?: Record<string, unknown> } | undefined)?.decay;
219				if (decay && typeof decay === "object") {
220					if (typeof decay.enabled === "boolean") base.enabled = decay.enabled;
221					if (typeof decay.halfLifeDays === "number" && decay.halfLifeDays > 0) base.halfLifeDays = Math.floor(decay.halfLifeDays);
222					const ad = decay.autoDelete as Record<string, unknown> | undefined;
223					if (ad && typeof ad === "object") {
224						if (typeof ad.enabled === "boolean") base.autoDelete.enabled = ad.enabled;
225						if (typeof ad.staleAfterDays === "number" && ad.staleAfterDays > 0) base.autoDelete.staleAfterDays = Math.floor(ad.staleAfterDays);
226						if (typeof ad.maxUsage === "number" && ad.maxUsage >= 0) base.autoDelete.maxUsage = Math.floor(ad.maxUsage);
227						if (typeof ad.maxPerRun === "number" && ad.maxPerRun > 0) base.autoDelete.maxPerRun = Math.floor(ad.maxPerRun);
228					}
229				}
230			}
231		} catch {
232			/* fall back to defaults */
233		}
234		// L4 kill switch.
235		if (env.PI_MEMORY_DECAY_DISABLED === "1" || env.PI_MEMORY_DECAY_DISABLED === "true") base.enabled = false;
236		return base;
237	}
