/**
 * Read/write access to the pi-memory temporal-decay sidecar from the dream-memory
 * (read) side.
 *
 * pi-memory owns the SQLite store and the canonical decay methods (see
 * `extensions/pi-memory/src/db.ts` MemoryDb.recordMemoryUsage / decayCandidates /
 * deleteMemoryFile and `extensions/pi-memory/src/decay.ts`). dream-memory is a
 * *separate npm package* installed in its own node_modules, so it cannot import
 * pi-memory's MemoryDb (which pulls in better-sqlite3 + effect). Per the task's
 * blessed fallback we open the same sqlite file directly with Node's built-in
 * `node:sqlite` (Node ≥22) and mirror the identical SQL. Keep these queries in
 * sync with pi-memory's MemoryDb.
 *
 * CACHE SAFETY: every write here targets the `memory_usage` sidecar or deletes a
 * row/file on disk. None of it touches the cached system-prompt prefix. The decay
 * weight is only ever applied to dynamic-tail recall candidates.
 */

import { existsSync, readFileSync } from "node:fs";
import { createRequire } from "node:module";
import { homedir } from "node:os";
import { join } from "node:path";

import { decayWeight } from "./decay.ts";

const nodeRequire = createRequire(import.meta.url);

export interface DecayConfig {
	enabled: boolean;
	halfLifeDays: number;
	autoDelete: {
		enabled: boolean;
		staleAfterDays: number;
		maxUsage: number;
		maxPerRun: number;
	};
}

export const DEFAULT_DECAY_CONFIG: DecayConfig = {
	enabled: true,
	halfLifeDays: 30,
	autoDelete: { enabled: true, staleAfterDays: 90, maxUsage: 0, maxPerRun: 20 },
};

/** Minimal structural view of node:sqlite's DatabaseSync we rely on. */
interface SqliteSync {
	prepare(sql: string): {
		run(...params: unknown[]): unknown;
		get(...params: unknown[]): unknown;
		all(...params: unknown[]): unknown[];
	};
	close(): void;
}

export interface UsageRow {
	usageCount: number;
	lastUsedAt?: string;
	createdAt?: string;
}

export interface DecayCandidate {
	path: string;
	scope: string;
	type: string;
	createdAt?: string;
	usageCount: number;
	lastUsedAt?: string;
}

/** Resolve pi-memory's sqlite path (mirrors pi-memory `memoryDbPath`). */
export function piMemoryDbPath(env: NodeJS.ProcessEnv = process.env): string {
	if (env.PI_MEMORY_DB) return env.PI_MEMORY_DB;
	const root = env.PI_MEMORY_DIR?.length ? env.PI_MEMORY_DIR : join(homedir(), ".pi", "agent", "memory");
	return join(root, "db", "memory.sqlite");
}

/**
 * Open the pi-memory sqlite read/write. Returns undefined if the file does not
 * exist yet (fresh machine) or node:sqlite is unavailable — callers must treat a
 * missing handle as "decay disabled, neutral ranking".
 */
export function openPiMemorySidecar(path = piMemoryDbPath()): MemoryDecayDb | undefined {
	if (!existsSync(path)) return undefined;
	try {
		// Lazy require so environments without node:sqlite (or with it stubbed)
		// degrade gracefully instead of throwing at import time.
		const { DatabaseSync } = nodeRequire("node:sqlite") as { DatabaseSync: new (p: string) => SqliteSync };
		return new MemoryDecayDb(new DatabaseSync(path));
	} catch {
		return undefined;
	}
}

/**
 * Thin mirror of the pi-memory decay methods, backed by node:sqlite. SQL is kept
 * byte-equivalent to `extensions/pi-memory/src/db.ts`.
 */
export class MemoryDecayDb {
	constructor(private readonly db: SqliteSync) {}

	close(): void {
		try {
			this.db.close();
		} catch {
			/* best effort */
		}
	}

	/** Usage + createdAt for the given paths, keyed by path. Missing paths omitted. */
	usageByPath(paths: string[]): Map<string, UsageRow> {
		const out = new Map<string, UsageRow>();
		if (paths.length === 0) return out;
		const placeholders = paths.map(() => "?").join(", ");
		const rows = this.db
			.prepare(`
				SELECT mf.path AS path, mf.created_at AS createdAt,
				       COALESCE(mu.usage_count, 0) AS usageCount, mu.last_used_at AS lastUsedAt
				FROM memory_files mf
				LEFT JOIN memory_usage mu ON mu.path = mf.path
				WHERE mf.path IN (${placeholders})
			`)
			.all(...paths) as Array<{ path: string; createdAt?: string; usageCount: number; lastUsedAt?: string }>;
		for (const row of rows) {
			out.set(row.path, {
				usageCount: row.usageCount ?? 0,
				...(row.lastUsedAt ? { lastUsedAt: row.lastUsedAt } : {}),
				...(row.createdAt ? { createdAt: row.createdAt } : {}),
			});
		}
		return out;
	}

	/** Mirror of MemoryDb.recordMemoryUsage. */
	recordMemoryUsage(paths: string[], recallEventId: string, scores: Record<string, number> = {}): void {
		if (paths.length === 0) return;
		const now = new Date().toISOString();
		const stmt = this.db.prepare(`
			INSERT INTO memory_usage (path, usage_count, last_used_at, last_recall_event_id, last_score)
			VALUES (?, 1, ?, ?, ?)
			ON CONFLICT(path) DO UPDATE SET
				usage_count = memory_usage.usage_count + 1,
				last_used_at = excluded.last_used_at,
				last_recall_event_id = excluded.last_recall_event_id,
				last_score = COALESCE(excluded.last_score, memory_usage.last_score)
		`);
		for (const path of paths) {
			const score = scores[path];
			stmt.run(path, now, recallEventId, typeof score === "number" ? score : null);
		}
	}

	/** Mirror of MemoryDb.decayCandidates. */
	decayCandidates(opts: { staleAfterDays: number; maxUsage: number; limit?: number }): DecayCandidate[] {
		const cutoff = new Date(Date.now() - opts.staleAfterDays * 86_400_000).toISOString();
		const limit = opts.limit ?? 100;
		return this.db
			.prepare(`
				SELECT mf.path AS path, mf.scope AS scope, mf.type AS type, mf.created_at AS createdAt,
				       COALESCE(mu.usage_count, 0) AS usageCount, mu.last_used_at AS lastUsedAt
				FROM memory_files mf
				LEFT JOIN memory_usage mu ON mu.path = mf.path
				WHERE mf.active = 1
				  AND mf.created_at IS NOT NULL AND mf.created_at < ?
				  AND COALESCE(mu.usage_count, 0) <= ?
				  AND (mu.last_used_at IS NULL OR mu.last_used_at < ?)
				ORDER BY mf.created_at ASC
				LIMIT ?
			`)
			.all(cutoff, opts.maxUsage, cutoff, limit) as DecayCandidate[];
	}

	/** Mirror of MemoryDb.deleteMemoryFile. */
	deleteMemoryFile(path: string): { path: string; scope: string; type: string } | undefined {
		const row = this.db.prepare("SELECT path, scope, type FROM memory_files WHERE path = ?").get(path) as
			| { path: string; scope: string; type: string }
			| undefined;
		if (!row) return undefined;
		this.db.prepare("DELETE FROM memory_usage WHERE path = ?").run(path);
		this.db.prepare("DELETE FROM memory_files WHERE path = ?").run(path);
		return row;
	}
}

/**
 * Compute a decay multiplier for a memory at `path` given a usage map. Returns 1
 * (neutral) when the path is untracked (e.g. dream-memory's own wiki files that
 * are not in pi-memory's memory_files table) so we never penalise memories we
 * cannot date.
 */
export function decayWeightForPath(
	path: string,
	usage: Map<string, UsageRow>,
	opts: { now: number; halfLifeDays: number },
): number {
	const row = usage.get(path);
	if (!row) return 1;
	return decayWeight({
		now: opts.now,
		halfLifeDays: opts.halfLifeDays,
		usageCount: row.usageCount,
		...(row.createdAt ? { createdAt: row.createdAt } : {}),
		...(row.lastUsedAt ? { lastUsedAt: row.lastUsedAt } : {}),
	});
}

/** Read pi-memory's decay config from global settings.json + env (L3/L4). */
export function loadDecayConfig(env: NodeJS.ProcessEnv = process.env): DecayConfig {
	const base: DecayConfig = {
		enabled: DEFAULT_DECAY_CONFIG.enabled,
		halfLifeDays: DEFAULT_DECAY_CONFIG.halfLifeDays,
		autoDelete: { ...DEFAULT_DECAY_CONFIG.autoDelete },
	};
	try {
		const settingsPath = join(env.PI_CODING_AGENT_DIR || join(homedir(), ".pi", "agent"), "settings.json");
		if (existsSync(settingsPath)) {
			const raw = readFileSync(settingsPath, "utf8");
			const settings = JSON.parse(raw) as { extensionConfig?: Record<string, unknown> };
			const decay = (settings.extensionConfig?.["pi-memory"] as { decay?: Record<string, unknown> } | undefined)?.decay;
			if (decay && typeof decay === "object") {
				if (typeof decay.enabled === "boolean") base.enabled = decay.enabled;
				if (typeof decay.halfLifeDays === "number" && decay.halfLifeDays > 0) base.halfLifeDays = Math.floor(decay.halfLifeDays);
				const ad = decay.autoDelete as Record<string, unknown> | undefined;
				if (ad && typeof ad === "object") {
					if (typeof ad.enabled === "boolean") base.autoDelete.enabled = ad.enabled;
					if (typeof ad.staleAfterDays === "number" && ad.staleAfterDays > 0) base.autoDelete.staleAfterDays = Math.floor(ad.staleAfterDays);
					if (typeof ad.maxUsage === "number" && ad.maxUsage >= 0) base.autoDelete.maxUsage = Math.floor(ad.maxUsage);
					if (typeof ad.maxPerRun === "number" && ad.maxPerRun > 0) base.autoDelete.maxPerRun = Math.floor(ad.maxPerRun);
				}
			}
		}
	} catch {
		/* fall back to defaults */
	}
	// L4 kill switch.
	if (env.PI_MEMORY_DECAY_DISABLED === "1" || env.PI_MEMORY_DECAY_DISABLED === "true") base.enabled = false;
	return base;
}

