/**
 * Tests for the dream-memory (read-side) temporal decay: the mirrored decay
 * scorer, the node:sqlite sidecar accessor, and the gated auto-delete pass.
 *
 * Everything here writes only to the pi-memory `memory_usage`/`memory_files`
 * sidecar + on-disk markdown in a temp tree — never the cached system prompt.
 */

import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { existsSync } from "node:fs";
import { mkdtempSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { tmpdir } from "node:os";
import { join } from "node:path";

// Load node:sqlite via require so vite leaves the built-in alone (matches the
// source loader in memory-decay.ts).
const { DatabaseSync } = createRequire(import.meta.url)("node:sqlite") as {
	DatabaseSync: new (path: string) => {
		exec(sql: string): void;
		prepare(sql: string): { run(...p: unknown[]): unknown; get(...p: unknown[]): unknown; all(...p: unknown[]): unknown[] };
		close(): void;
	};
};
type DatabaseSync = InstanceType<typeof DatabaseSync>;

import { decayWeight } from "../src/decay.ts";
import { MemoryDecayDb, decayWeightForPath, type UsageRow } from "../src/memory-decay.ts";
import { isDeletableMemoryPath, runDecayPrune, decayTombstonePath } from "../src/dream/decay-prune.ts";

const DAY = 86_400_000;
const NOW = Date.parse("2026-06-02T00:00:00.000Z");

const SCHEMA = `
CREATE TABLE memory_files (
	path TEXT PRIMARY KEY, scope TEXT NOT NULL, project_slug TEXT, type TEXT NOT NULL,
	name TEXT, description TEXT, body_hash TEXT, mtime_ms INTEGER, created_at TEXT,
	updated_at TEXT, origin_observation_id TEXT, active INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE memory_usage (
	path TEXT PRIMARY KEY, usage_count INTEGER NOT NULL DEFAULT 0, last_used_at TEXT,
	last_recall_event_id TEXT, last_score REAL
);
`;

function makeDb(): { path: string; db: DatabaseSync } {
	const dir = mkdtempSync(join(tmpdir(), "dream-decay-db-"));
	const path = join(dir, "memory.sqlite");
	const db = new DatabaseSync(path);
	db.exec(SCHEMA);
	return { path, db };
}

function seedFile(db: DatabaseSync, path: string, createdAt: string, active = 1) {
	db.prepare("INSERT INTO memory_files (path, scope, type, created_at, updated_at, active) VALUES (?, 'profile', 'user', ?, ?, ?)").run(
		path,
		createdAt,
		createdAt,
		active,
	);
}

describe("decay scorer mirror parity", () => {
	it("matches the documented properties (bounded, age-monotonic, usage-monotonic)", () => {
		expect(decayWeight({ createdAt: NOW, now: NOW, halfLifeDays: 30, usageCount: 0 })).toBeCloseTo(1, 10);
		expect(decayWeight({ createdAt: NOW - 30 * DAY, now: NOW, halfLifeDays: 30, usageCount: 0 })).toBeCloseTo(0.5, 6);
		const young = decayWeight({ createdAt: NOW - 10 * DAY, now: NOW, halfLifeDays: 30, usageCount: 1 });
		const old = decayWeight({ createdAt: NOW - 100 * DAY, now: NOW, halfLifeDays: 30, usageCount: 1 });
		expect(young).toBeGreaterThan(old);
		expect(decayWeight({ now: NOW, halfLifeDays: 30 })).toBe(1);
	});
});

describe("MemoryDecayDb sidecar", () => {
	it("reads usage+createdAt, records usage, finds candidates, deletes", () => {
		const { path, db } = makeDb();
		try {
			const old = "2026-01-01T00:00:00.000Z";
			const recent = new Date(NOW - 5 * DAY).toISOString();
			seedFile(db, "/m/old-unused.md", old);
			seedFile(db, "/m/old-used.md", old);
			seedFile(db, "/m/recent.md", recent);
			db.close();

			const sidecar = new MemoryDecayDb(new DatabaseSync(path));
			try {
				sidecar.recordMemoryUsage(["/m/old-used.md"], "ev-1");
				const usage = sidecar.usageByPath(["/m/old-unused.md", "/m/old-used.md"]);
				expect(usage.get("/m/old-used.md")?.usageCount).toBe(1);
				expect(usage.get("/m/old-unused.md")?.usageCount).toBe(0);
				expect(usage.get("/m/old-unused.md")?.createdAt).toBe(old);

				const candidates = sidecar.decayCandidates({ staleAfterDays: 90, maxUsage: 0, limit: 10 });
				const paths = candidates.map((c) => c.path);
				expect(paths).toContain("/m/old-unused.md");
				expect(paths).not.toContain("/m/old-used.md");
				expect(paths).not.toContain("/m/recent.md");

				const removed = sidecar.deleteMemoryFile("/m/old-unused.md");
				expect(removed).toEqual({ path: "/m/old-unused.md", scope: "profile", type: "user" });
				expect(sidecar.usageByPath(["/m/old-unused.md"]).size).toBe(0);
			} finally {
				sidecar.close();
			}
		} finally {
			try { db.close(); } catch { /* already closed */ }
		}
	});

	it("decayWeightForPath is neutral for untracked paths", () => {
		const usage = new Map<string, UsageRow>([["/m/x.md", { usageCount: 0, createdAt: "2026-01-01T00:00:00.000Z" }]]);
		expect(decayWeightForPath("/m/unknown.md", usage, { now: NOW, halfLifeDays: 30 })).toBe(1);
		expect(decayWeightForPath("/m/x.md", usage, { now: NOW, halfLifeDays: 30 })).toBeLessThan(1);
	});
});

describe("isDeletableMemoryPath", () => {
	const root = "/root/.pi/agent/memory";
	it("protects head index files and out-of-root paths", () => {
		expect(isDeletableMemoryPath(join(root, "profile", "user_coffee.md"), root)).toBe(true);
		expect(isDeletableMemoryPath(join(root, "profile", "MEMORY.md"), root)).toBe(false);
		expect(isDeletableMemoryPath(join(root, "profile", "00-pi-active-context.md"), root)).toBe(false);
		expect(isDeletableMemoryPath("/etc/passwd", root)).toBe(false);
		expect(isDeletableMemoryPath(join(root, "profile", "notes.txt"), root)).toBe(false);
	});
});

describe("runDecayPrune", () => {
	let root: string;
	let dbPath: string;
	const savedEnv: Record<string, string | undefined> = {};

	beforeEach(() => {
		root = mkdtempSync(join(tmpdir(), "dream-prune-root-"));
		savedEnv.PI_MEMORY_DIR = process.env.PI_MEMORY_DIR;
		savedEnv.PI_CODING_AGENT_DIR = process.env.PI_CODING_AGENT_DIR;
		savedEnv.PI_MEMORY_DECAY_DISABLED = process.env.PI_MEMORY_DECAY_DISABLED;
		savedEnv.DREAM_DECAY_TOMBSTONE_PATH = process.env.DREAM_DECAY_TOMBSTONE_PATH;
		process.env.PI_MEMORY_DIR = root;
		process.env.DREAM_DECAY_TOMBSTONE_PATH = join(mkdtempSync(join(tmpdir(), "dream-prune-tomb-")), "tombstones.jsonl");
		// Isolate config lookup away from the real ~/.pi/agent/settings.json.
		process.env.PI_CODING_AGENT_DIR = mkdtempSync(join(tmpdir(), "dream-prune-cfg-"));
		delete process.env.PI_MEMORY_DECAY_DISABLED;

		const { path, db } = makeDb();
		dbPath = path;
		const profile = join(root, "profile");
		mkdirSync(profile, { recursive: true });
		const stale = join(profile, "user_stale.md");
		const head = join(profile, "MEMORY.md");
		writeFileSync(stale, "---\ntype: user\n---\nold note body");
		writeFileSync(head, "# index");
		seedFile(db, stale, "2026-01-01T00:00:00.000Z");
		seedFile(db, head, "2026-01-01T00:00:00.000Z");
		db.close();
	});

	afterEach(() => {
		for (const [k, v] of Object.entries(savedEnv)) {
			if (v === undefined) delete process.env[k];
			else process.env[k] = v;
		}
	});

	it("tombstones then deletes stale unused files, preserving the head", async () => {
		const result = await runDecayPrune({ dbPath, now: NOW });
		expect(result.status).toBe("pruned");
		expect(result.deleted).toBe(1);

		const stale = join(root, "profile", "user_stale.md");
		const head = join(root, "profile", "MEMORY.md");
		expect(existsSync(stale)).toBe(false); // deleted
		expect(existsSync(head)).toBe(true); // head preserved

		// Tombstone is recoverable: contains the full body.
		const tomb = readFileSync(decayTombstonePath(), "utf8").trim().split("\n");
		const last = JSON.parse(tomb[tomb.length - 1] ?? "{}");
		expect(last.path).toBe(stale);
		expect(last.body).toContain("old note body");
		expect(last.reason).toBe("temporal-decay-autodelete");

		// Sidecar row gone too.
		const sidecar = new MemoryDecayDb(new DatabaseSync(dbPath));
		try {
			expect(sidecar.decayCandidates({ staleAfterDays: 90, maxUsage: 0, limit: 10 }).some((c) => c.path === stale)).toBe(false);
		} finally {
			sidecar.close();
		}
	});

	it("is disabled by the PI_MEMORY_DECAY_DISABLED kill switch", async () => {
		process.env.PI_MEMORY_DECAY_DISABLED = "1";
		const result = await runDecayPrune({ dbPath, now: NOW });
		expect(result.status).toBe("disabled");
		expect(existsSync(join(root, "profile", "user_stale.md"))).toBe(true);
	});
});

