/**
 * dream-memory recall weighting — the frontmatter-derived score multipliers
 * (ADR 0009 §5 / Amendment 1).
 *
 * The recall score is `semantic × decay × statusWeight × confidenceWeight`.
 * The `decay` (temporal) factor lives in decay.ts — a verbatim mirror of
 * pi-memory's scorer, parity-pinned; do NOT fold status/confidence into it.
 * This module owns the two *frontmatter-derived* axes only: lifecycle status
 * and confidence maturity.
 *
 * Amendment 1 rule: superseded records are DOWN-WEIGHTED, not hard-filtered —
 * a superseded record stays reachable so recall can still surface "there is a
 * newer correction here" instead of going silent, and so the index knows the
 * record exists. ACL (visibility/sensitivity) is the *only* hard gate and runs
 * before scoring (a later slice). Neither status nor confidence ever zeroes a
 * candidate out; the smallest multiplier this module produces is still > 0.
 *
 * PURE: no fs, no sqlite, no settings read. Callers pass override weights; the
 * settings loader is wired at composition time (memory-decay's loadDecayConfig
 * extension), never here — keeps the scorer unit-testable and cache-irrelevant.
 */

import type { ConfidenceLevel, RecordStatus } from "../canonical/frontmatter.ts";

export interface StatusWeights {
	active: number;
	superseded: number;
}

export interface ConfidenceWeights {
	confirmed: number;
	consolidated: number;
	extracted: number;
}

/**
 * ADR 0009 Amendment 1 defaults. `superseded` is kept reachable but strongly
 * down-ranked (0.3). Confidence only nudges — the floor is held at 0.7 so a
 * highly relevant, freshly *extracted* fact still outranks a barely-relevant
 * *confirmed* one; confidence breaks ties, it does not dominate semantics.
 */
export const DEFAULT_STATUS_WEIGHTS: StatusWeights = { active: 1, superseded: 0.3 };
export const DEFAULT_CONFIDENCE_WEIGHTS: ConfidenceWeights = {
	confirmed: 1,
	consolidated: 0.85,
	extracted: 0.7,
};

/**
 * Lifecycle-status multiplier. An unknown or absent status returns the neutral
 * 1 — we never penalise a record we cannot classify (mirrors
 * `decayWeightForPath`'s neutral return for untracked paths).
 */
export function statusWeight(
	status: RecordStatus | string | undefined,
	weights: StatusWeights = DEFAULT_STATUS_WEIGHTS,
): number {
	if (status === "superseded") return weights.superseded;
	if (status === "active") return weights.active;
	return 1;
}

/** Confidence-maturity multiplier. Unknown/absent confidence → neutral 1. */
export function confidenceWeight(
	confidence: ConfidenceLevel | string | undefined,
	weights: ConfidenceWeights = DEFAULT_CONFIDENCE_WEIGHTS,
): number {
	switch (confidence) {
		case "confirmed":
