/**
 * Read the lifecycle status + confidence for a recall candidate — the
 * frontmatter inputs to `statusWeight`/`confidenceWeight` (ADR 0009
 * Amendment 1).
 *
 * This is the A-vs-B wiring seam. Today `SearchHit` carries no frontmatter, so
 * this returns `undefined` and the recall weight collapses to pure decay —
 * zero behaviour change. The next slice swaps the body to source these fields
 * (sidecar columns, preferred — no extra disk reads; or frontmatter parse)
 * without touching the ranking maths below. Until then it must stay neutral.
 */
export function recallFrontmatterFor(
	_hit: SearchHit,
): { status?: RecordStatus | string; confidence?: ConfidenceLevel | string } | undefined {
	return undefined;
}

/**
 * Apply the recall ranking multiplier to candidate scores BEFORE the curator
 * selects: `score × decay × statusWeight × confidenceWeight` (ADR 0009
 * Amendment 1). Temporal decay (mem0-inspired) sinks stale / never-recalled
 * memories; status down-weights superseded records (kept reachable, never
 * filtered); confidence nudges by maturity. Usage STATE comes from pi-memory's
 * `memory_usage` sidecar — never the cached prefix. Mutates `hits[].score` in
 * place. Untracked / unclassified hits get a neutral 1.0 on each axis. Never
 * throws — ranking is best-effort sugar.
 *
 * NOTE (wiring slice): status/confidence are currently gated behind the decay
 * sidecar's early returns because `recallFrontmatterFor` is neutral. When that
 * seam starts returning real frontmatter, lift the status/confidence weighting
 * out of the `!sidecar` / `usage.size === 0` guards so it applies even when
 * temporal decay is off, and rename to `applyRecallRanking`.
 */
export function applyDecayRanking(hits: SearchHit[], log: (m: string) => void, nowMs: number = Date.now()): void {
	const cfg = loadDecayConfig();
	if (!cfg.enabled) return;
	const paths = hits.map((h) => h.file_path).filter((p): p is string => typeof p === "string" && p.length > 0);
	if (paths.length === 0) return;
	const sidecar = openPiMemorySidecar();
	if (!sidecar) return;
	try {
		const usage = sidecar.usageByPath(paths);
		if (usage.size === 0) return;
		let weighted = 0;
		for (const hit of hits) {
			if (!hit.file_path || typeof hit.score !== "number") continue;
			const decay = decayWeightForPath(hit.file_path, usage, { now: nowMs, halfLifeDays: cfg.halfLifeDays });
			const fm = recallFrontmatterFor(hit);
			const w = recallWeight({ decay, status: fm?.status, confidence: fm?.confidence });
			if (w < 1) {
				hit.score = hit.score * w;
				weighted++;
			}
		}
		if (weighted > 0) log(`[active-recall] recall weight applied to ${weighted}/${hits.length} candidates`);
	} catch (err) {
		log(`[active-recall] recall ranking skipped: ${(err as Error).message}`);
	} finally {
		sidecar.close();
	}
}

