input.content:
/**
 * Tests for the frontmatter-derived recall weights (ADR 0009 Amendment 1):
 * `statusWeight`, `confidenceWeight`, the `recallWeight` composer, and the
 * `recallFrontmatterFor` wiring seam (which must stay neutral until the next
 * slice sources real frontmatter).
 *
 * Pure functions — no fs, no sqlite, no settings. The seam test asserts the
 * *current* neutral contract so a premature wiring change trips a red test.
 */

import { describe, expect, it } from "vitest";

import {
	confidenceWeight,
	DEFAULT_CONFIDENCE_WEIGHTS,
	DEFAULT_STATUS_WEIGHTS,
	recallWeight,
	statusWeight,
} from "../src/active-memory/recall-weight.ts";
import { recallFrontmatterFor } from "../src/active-memory/recall-selection.ts";

describe("statusWeight", () => {
	it("maps the known lifecycle states to the Amendment 1 defaults", () => {
		expect(statusWeight("active")).toBe(1);
		expect(statusWeight("superseded")).toBe(0.3);
	});

	it("down-weights superseded but never zeroes it (stays reachable)", () => {
		expect(statusWeight("superseded")).toBeGreaterThan(0);
		expect(statusWeight("superseded")).toBeLessThan(statusWeight("active"));
	});

	it("is neutral for unknown or absent status (never penalise the unclassified)", () => {
		expect(statusWeight(undefined)).toBe(1);
		expect(statusWeight("")).toBe(1);
		expect(statusWeight("archived")).toBe(1);
	});

	it("honours override weights", () => {
		expect(statusWeight("superseded", { active: 1, superseded: 0.1 })).toBe(0.1);
	});
});

describe("confidenceWeight", () => {
	it("ranks maturity confirmed > consolidated > extracted", () => {
		expect(confidenceWeight("confirmed")).toBe(1);
		expect(confidenceWeight("consolidated")).toBe(0.85);
		expect(confidenceWeight("extracted")).toBe(0.7);
		expect(confidenceWeight("confirmed")).toBeGreaterThan(confidenceWeight("consolidated"));
		expect(confidenceWeight("consolidated")).toBeGreaterThan(confidenceWeight("extracted"));
	});

	it("keeps the lowest-confidence floor above zero (a relevant extracted fact still surfaces)", () => {
		expect(confidenceWeight("extracted")).toBeGreaterThan(0);
	});

	it("is neutral for unknown or absent confidence", () => {
		expect(confidenceWeight(undefined)).toBe(1);
		expect(confidenceWeight("speculative")).toBe(1);
	});

	it("honours override weights", () => {
		expect(confidenceWeight("extracted", { confirmed: 1, consolidated: 0.9, extracted: 0.5 })).toBe(0.5);
	});
});

describe("recallWeight composition", () => {
	it("collapses to pure decay when status + confidence are absent (the seam contract)", () => {
		expect(recallWeight({ decay: 0.42 })).toBeCloseTo(0.42, 10);
		expect(recallWeight({ decay: 1 })).toBe(1);
	});

	it("multiplies decay × status × confidence", () => {
		expect(recallWeight({ decay: 0.8, status: "superseded", confidence: "extracted" })).toBeCloseTo(0.8 * 0.3 * 0.7, 10);
		expect(recallWeight({ decay: 1, status: "active", confidence: "confirmed" })).toBe(1);
	});

	it("never zeroes a positive-decay candidate (Amendment 1: down-weight, do not filter)", () => {
		const worst = recallWeight({ decay: 0.01, status: "superseded", confidence: "extracted" });
		expect(worst).toBeGreaterThan(0);
	});

	it("orders active above superseded and confirmed above extracted at equal decay", () => {
		const active = recallWeight({ decay: 0.5, status: "active", confidence: "confirmed" });
		const superseded = recallWeight({ decay: 0.5, status: "superseded", confidence: "confirmed" });
		expect(active).toBeGreaterThan(superseded);

		const confirmed = recallWeight({ decay: 0.5, status: "active", confidence: "confirmed" });
		const extracted = recallWeight({ decay: 0.5, status: "active", confidence: "extracted" });
		expect(confirmed).toBeGreaterThan(extracted);
	});

	it("threads override weights through", () => {
		const w = recallWeight({
			decay: 1,
			status: "superseded",
			confidence: "extracted",
			statusWeights: { active: 1, superseded: 0.5 },
			confidenceWeights: { confirmed: 1, consolidated: 0.9, extracted: 0.8 },
		});
		expect(w).toBeCloseTo(0.5 * 0.8, 10);
	});

	it("exposes sane default weight tables", () => {
		expect(DEFAULT_STATUS_WEIGHTS).toEqual({ active: 1, superseded: 0.3 });
		expect(DEFAULT_CONFIDENCE_WEIGHTS).toEqual({ confirmed: 1, consolidated: 0.85, extracted: 0.7 });
	});
});

describe("recallFrontmatterFor seam", () => {
	it("is neutral until the wiring slice sources real frontmatter", () => {
		// Guards the current contract: a hit yields no status/confidence, so
		// recallWeight collapses to pure decay. When this starts returning data,
		// this test should be updated alongside the wiring change — not before.
		expect(recallFrontmatterFor({ title: "t", permalink: "p", file_path: "x.md", score: 1 })).toBeUndefined();
	});
});

